insert into public.orbit_questions(id,year,number,discipline,language,context,prompt,alternatives,source_url) select id,year,number,discipline,language,context,prompt,alternatives,source_url from jsonb_populate_recordset(null::public.orbit_questions,'[{"id": "enem-2023-1-espanhol", "year": 2023, "number": 1, "discipline": "linguagens", "language": "espanhol", "context": "**TEXTO I**\n\n¿QUÉ ME PASA?:  \n¿PorQUE ME CUESTA TANTO ESTUDIAR?  \n¿PORQUE ME CUESTA TANTO CONCENTRARME?  \n¿PoRQUE……  \n¿PORQUÉ…..  \n¿PORQUÉ NO CONSIGO APRENDER COMO LOS DEMÁS?\n\n![](https://enem.dev/broken-image.svg)\n\nDisponível em: www.otrasvoceseneducacion.org. Acesso em: 8 nov. 2022.\n\n**ТЕХТО II**\n\nIshaan Awashi es un niño de 8 años cuyo mundo está plagado de maravillas que nadie más parece apreciar: colores, peces, perros y cometas, que simplemente no son importantes en la vida de los adultos, que parecen más interesados en cosas como los deberes, las notas o la limpieza. E Ishaan parece no poder hacer nada bien en clase. Cuando los problemas que ocasiona superan a sus padres, es internado en un colegio para que le disciplinen. Las cosas no mejoran en el nuevo colegio, donde Ishaan tiene además que aceptar estar lejos de sus padres. Hasta que un dia, el nuevo profesor de arte, Ram Shankar Nikumbh, entra en escena, se interesa por el pequeño Ishaan y todo cambia.\n\nDisponível em: https://elfinalde.com. Acesso em: 26 out. 2021 (adaptado)", "prompt": "O filme Como estrellas en la tierra aborda o tema da dislexia. Relacionando o cartaz do filme com a sinopse, constata-se que o(a)", "alternatives": [{"letter": "A", "text": "Olhar diferenciado para com o outro gera mudanças.", "file": null}, {"letter": "B", "text": "Estudante com dislexia apresenta um tom questionador.", "file": null}, {"letter": "C", "text": "Abordagem para lidar com a dislexia é pautada na disciplina.", "file": null}, {"letter": "D", "text": "Contato com os pais prejudica o acompanhamento da dislexia.", "file": null}, {"letter": "E", "text": "Mudança de interesses ocorre na transição da infância para a vida adulta.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/1"}, {"id": "enem-2023-2-espanhol", "year": 2023, "number": 2, "discipline": "linguagens", "language": "espanhol", "context": "", "prompt": "Me niego rotundamente\nA negar mi voz,\nMi sangre y mi piel.\nY me niego rotundamente\nA dejar de ser yo,\nA dejar de sentirme bien\nCuando miro mi rostro en el es\nCon mi boca\nRotundamente grande\nY mi nariz\nRotundamente hermosa,\nY mis dientes\nRotundamente blancos,\nY mi piel valientemente negra.\nY me niego categóricamente\nA dejar de hablar\nMi lengua, mi acento y mi historia\nY me niego absolutamente\nA ser parte de los que callan,\nDe los que temen,\nDe los que lloran\nPorque me acepto\nRotundamente libre,\nRotundamente negra,\nRotundamente hermosa.\nCAMPELL BARR, S. Disponível em:\nhttps.negracubanateniaqueser.com\nAcesso em 25 out. 2021.\nPara enfatizar caracteristicas e atitudes que reforçam a identidade da mulher negra, o poema da escritora costarriquenha apresenta:", "alternatives": [{"letter": "A", "text": "Advérbios como \"rotundamente\" e \"categóricamente\".", "file": null}, {"letter": "B", "text": "Verbos reflexivos como \"me niego\" e \"me acepto\".", "file": null}, {"letter": "C", "text": "Adjetivos como \"grande\" e \"hermosa\".", "file": null}, {"letter": "D", "text": "Substantivos como \"sangre\" e \"piel\".", "file": null}, {"letter": "E", "text": "Adjetivos possessivos como \"mi\" e \"mis\".", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/2"}, {"id": "enem-2023-3-espanhol", "year": 2023, "number": 3, "discipline": "linguagens", "language": "espanhol", "context": "**“Caramelos” en sus suelos**\n\nLas tierras de España, tu vista enamoran;\n\nsus gentes; te amistan; ¿“cocinas”?, ¡“te molan”!\n\n¿El plato común?, ¡pues «tortilla/patatas»!;\n\nen bares, figones, o tascas, ¡las «tapas»!;\n\n“sabor nacional”, ¡el «gazpacho», sus «vinos»,\n\n«sangría», y «jamón» de sabrosos cochinos!\n\n(Cual “sellos”, te grabas sus «Típicos Platos»;\n\n¡sabrás por dó pasas, por sólo tu olfato!,\n\n¡si en cada lugar, un sabor peculiar,\n\n“al paso” cautiva tu buen paladar!).\n\n¡Son más que “recetas”!, será “alegoría”!,\n\n¡será “identidad”! (¡hay “reserva” en su «Guía»!);\n\nson platos allende un “timón conductor”,\n\n¡son mar, ríos, sierras!, ¡son valles, son flor!,\n\n¡y aportan “Conventos” a gastronomia,\n\nsus «dulces»! (sabor “celestial”, ¡de ambrosia!).\n\nQUIROZ Y LÓPEZ M. Disponível em: https://pt.calameo.com. Acesso em: 25 out. 2021.", "prompt": "Nesse poema, o eu poético enaltece a", "alternatives": [{"letter": "A", "text": "Característica amistosa do povo espanhol.", "file": null}, {"letter": "B", "text": "Beleza das paisagens naturais da Espanha.", "file": null}, {"letter": "C", "text": "Variedade de pratos na gastronomia espanhola.", "file": null}, {"letter": "D", "text": "Relação entre os sentidos do paladar e do olfato na gastronomia.", "file": null}, {"letter": "E", "text": "Gastronomia como representação da identidade cultural de um povo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/3"}, {"id": "enem-2023-4-espanhol", "year": 2023, "number": 4, "discipline": "linguagens", "language": "espanhol", "context": "Manipular es sembrar en la conciencia y en la mente de la gente ideas, actitudes, conceptos y aspiraciones -incluso falsas, inmorales y deshonestas- que sirvan a los objetivos -ocultos o abiertos- de sus manipuladores.\n\nManipular es una de las primeras cosas que aprendemos en la vida. A muy temprana edad, los bebes descubren el poder del llanto, el berrinche, los pataleos, la risa o alguna “gracia” como recursos para demandar atención, exigir comida, pedir ayuda o simplemente mantener ocupada a la gente. Nuestras actitudes de adultos reflejan lo mucho o poco que algunos maduraron, procesaron y rebasaron ese periodo.\n\nPara que exista un manipulador, debe haber una base de ciudadanos indefensos, dóciles, desinformados. El manipulador es celoso, a veces casi paranoico; no admite cuestionamientos ni quiere que nadie ocupe su espacio, sabe que su vigencia depende de presencia controladora. Todos los días, hay que marcar la línea de discurso, incidir en el debate. El ridículo vale la pena si con ello se logra una cortina de humo.\n\nDisponível em: www.forbes.com.mx. Acesso em: 7 out. 2021 (adaptado).", "prompt": "Nesse texto, a expressão “cortina de humo” revela que o manipulador", "alternatives": [{"letter": "A", "text": "Amadurece tardiamente.", "file": null}, {"letter": "B", "text": "Busca mascarar a verdade.", "file": null}, {"letter": "C", "text": "Rejeita questionamentos alheios.", "file": null}, {"letter": "D", "text": "Aproxima-se de pessoas indefesas.", "file": null}, {"letter": "E", "text": "Faz-se presente de forma controladora.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/4"}, {"id": "enem-2023-5-espanhol", "year": 2023, "number": 5, "discipline": "linguagens", "language": "espanhol", "context": "**Que quede claro**\n\nCómo es posible que se cierren\n\ntantas bocas, tantos ojos,\n\ntantas puertas, muchas mentes ante un\n\nacto xenofóbico sin precedentes.\n\nPresidentes, ministros, cancilleres,\n\nautoridades, responsables.\n\n¿Quién pagará el daño causado a familiares?\n\nPor un loco del estrada sin modales. \\[…\\]\n\nSe alejó de aquel lugar donde su color era\n\nmucho más que su color, era su raza.\n\nPersiguiendo un sueño que desapareció,\n\nque se fusionó y terminó en una pesadilla. \\[…\\]\n\nDéjame que te cuente esta historia\n\nque sucedió en el metro de Barcelona,\n\ncuando aquella mañana la injusticia\n\ny xenofobia se juntaron de la mano,\n\nprotagonizando una de las más feas escenas de racismo.\n\nEn aquel vagón viajaba un ángel de color diferente,\n\nen su camino se interpuso aquel inconsciente,\n\nque aún sabiendo lo que hacía,\n\nseguía hablando con su gente.\n\nLe dio al ángel dos patadas en su cara,\n\nse rió de ella sin cambiar la mirada.\n\nY aún anda suelto, aún anda suelto…\n\nORISHAS. In: **Cosita buena**. Delaware: Suerte Publishing LCC, 2008 (fragmento).", "prompt": "A letra da canção Que quede claro, da banda cubana Orishas, revela o(a)", "alternatives": [{"letter": "A", "text": "Indignação diante do desrespeito à diversidade.", "file": null}, {"letter": "B", "text": "Violência característica das grandes metrópoles.", "file": null}, {"letter": "C", "text": "Preconceito da sociedade com relação ao misticismo.", "file": null}, {"letter": "D", "text": "Descuido da população com sonhos dos imigrantes.", "file": null}, {"letter": "E", "text": "Falta de segurança existente no transporte público urbano.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/5"}, {"id": "enem-2023-6-geral", "year": 2023, "number": 6, "discipline": "linguagens", "language": null, "context": "", "prompt": "A sessão do Comitê Olímpico Internacional (COI) aprovou uma mudança histórica e inédita no lema olímpico, criado em 1894 pelo Barão Pierre de Coubertin para expressar os valores e a excelência do esporte. Mais de 120 anos depois, o lema tem sua primeira alteração para ressaltar a solidariedade e incluir a palavra “juntos” mais rápido, mais alto, mais forte – juntos. A mudança foi aprovada por unanimidade pelos membros do COI e celebrada pelo presidente da entidade.\nDisponível em: https://ge.globo.com Acesso em: 10 nov. 2021 (adaptado)\nDe acordo com o texto, a alteração do lema olímpico teve como objetivo a", "alternatives": [{"letter": "A", "text": "Unificação do lema anterior ao atual.", "file": null}, {"letter": "B", "text": "Aproximação entre o lema olímpico e o COI.", "file": null}, {"letter": "C", "text": "Junção do lema olímpico com os princípios esportivos.", "file": null}, {"letter": "D", "text": "Associação entre o lema olímpico e a cooperatividade.", "file": null}, {"letter": "E", "text": "Vinculação entre o lema olímpico e os eventos atléticos.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/6"}, {"id": "enem-2023-7-geral", "year": 2023, "number": 7, "discipline": "linguagens", "language": null, "context": "**Mais iluminada que outras**\n\nTenho dois seios, estas duas coxas, duas mãos que me são muito úteis, olhos escuros, estas duas sobrancelhas que preencho com maquiagem comprada por dezenove e noventa e orelhas que não aceitam bijuterias. Este corpo é um corpo faminto, dentado, cruel, capaz e violento. Movo os braços e multidões correm desesperadas. Caminho no escuro com o rosto para baixo, pois cada parte isolada de mim tem sua própria vida e não quero domá-las. Animal da caatinga. Forte demais. Engolidora de espadas e espinhos. Dizem e eu ouvi, mas depois também li, que o estado do Ceará aboliu a escravidão quatro anos antes do restante do país. Todos aqueles corpos que eram trazidos com  \nseus dedos contados, seus calcanhares prontos e seus umbigos em fogo, todos eles foram interrompidos no porto. Um homem – dizem e eu ouvi e depois também li — liderou o levante. E todos esses corpos foram buscar outros incômodos. Foram ser incomodados.\n\nARRAES. J. Redemoinho em dia quente. São Paulo: Alfaguara, 2019.", "prompt": "Nesse texto, os recursos expressivos usados pela narradora", "alternatives": [{"letter": "A", "text": "Revelam as marcas da violência de raça e de gênero na construção da identidade.", "file": null}, {"letter": "B", "text": "Questionam o pioneirismo do estado do Ceará no enfrentamento à escravidão.", "file": null}, {"letter": "C", "text": "Reproduzem padrões estéticos em busca da valorização da autoestima feminina.", "file": null}, {"letter": "D", "text": "Sugerem uma atmosfera onírica alinhada ao desejo de resgate da espiritualidade.", "file": null}, {"letter": "E", "text": "Mimetizam, na paisagem, os corpos transformados pela violência da escravidão.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/7"}, {"id": "enem-2023-8-geral", "year": 2023, "number": 8, "discipline": "linguagens", "language": null, "context": "**De quem é esta língua?**\n\nUma pequena editora brasileira, a Urutau, acaba de lançar em Lisboa uma “antologia antirracista de poetas estrangeiros em Portugal”, com o título Volta para a tua terra.\n\nO livro denuncia as diversas formas de racismo a que os imigrantes estão sujeitos. Alguns dos poetas brasileiros antologiados queixam-se do desdém com que um grande número de portugueses acolhe o português brasileiro. É uma queixa frequente.\n\n“Aqui em Portugal eles dizem / — eles dizem – / que nosso português é errado, que nós não falamos português”, escreve a poetisa paulista Maria Giulia Pinheiro, para concluir: “Se a sua linguagem, a lusitana, / ainda conserva a palavra da opressão / ela não é a mais bonita do mundo./ Ela é uma das mais violentas”.\n\nAGUALUSA, J. E. Disponível em: https.iloglobo.globo.com Acesso em: 22 nov. 2021 (adaptado).", "prompt": "O texto de Agualusa tematiza o preconceito em relação ao português brasileiro. Com base no trecho citado pelo autor, infere-se que esse preconceito se deve", "alternatives": [{"letter": "A", "text": "À dificuldade de consolidação da literatura brasileira em outros países.", "file": null}, {"letter": "B", "text": "Aos diferentes graus de instrução formal entre os falantes de língua portuguesa.", "file": null}, {"letter": "C", "text": "À existência de uma língua ideal que alguns falantes lusitanos creem ser a falada em Portugal.", "file": null}, {"letter": "D", "text": "Ao intercâmbio cultural que ocorre entre os povos dos diferentes países de língua portuguesa.", "file": null}, {"letter": "E", "text": "À distância territorial entre os falantes do português que vivem em Portugal e no Brasil.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/8"}, {"id": "enem-2023-9-geral", "year": 2023, "number": 9, "discipline": "linguagens", "language": null, "context": "Na Idade Média, as notícias se propagavam com surpreendente eficácia. Segundo uma emérita professora de Sorbonne, um cavalo era capaz de percorrer 30 quilômetros por dia, mas o tempo podia se acelerar dependendo do interesse da notícia. As ordens mendicantes tinham um papel importante na disseminação de informações, assim como os jograis, os peregrinos e os vagabundos, porque todos eles percorriam grandes distâncias. As cidades também tinham correios organizados e selos para lacrar mensagens e tentar certificar a veracidade das correspondências. Graças a tudo isso, a circulação de boatos era intensa e politicamente relevante. Um exemplo clássico de _fake news_ da era medieval é a história do rei que desaparece na batalha e reaparece muito depois, idoso e transformado.\n\nDisponível em: www.elpais.com.br. Acesso em: 18 jun. 2018 (adaptado)", "prompt": "A propagação sistemática de informações é um fenômeno recorrente na história e no desenvolvimento das sociedades. No texto, a eficácia dessa propagação está diretamente relacionada ao (à)", "alternatives": [{"letter": "A", "text": "Velocidade de circulação das notícias.", "file": null}, {"letter": "B", "text": "Nível de letramento da população marginalizada.", "file": null}, {"letter": "C", "text": "Poder de censura por parte dos serviços públicos.", "file": null}, {"letter": "D", "text": "Legitimidade da voz dos representantes da nobreza.", "file": null}, {"letter": "E", "text": "Diversidade dos meios disponíveis em uma época histórica.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/9"}, {"id": "enem-2023-10-geral", "year": 2023, "number": 10, "discipline": "linguagens", "language": null, "context": "Se a interferência de contas falsas em discussões políticas nas redes sociais já representava um perigo para os sistemas democráticos, sua sofisticação e maior semelhança com pessoas reais têm agravado o problema pelo mundo.\n\nO perigo cresceu porque a tecnologia e os métodos evoluíram dos robôs, os “bots” — softwares com tarefas on-line automatizadas —, para os “ciborgues” ou “trolls”, contas controladas diretamente por humanos com ajuda de um pouco de automação.\n\nMas pesquisadores começam agora a observar outros padrões de comportamento: quando mensagens não são programadas, sua publicação se concentra só em horários de trabalho, já que é controlada por pessoas cuja profissão é exatamente essa, administrar um perfil falso durante o dia.\n\nOutra pista: a pobreza vocabular das mensagens publicadas por esses perfis. Um funcionário de uma empresa que supostamente produzia e vendia perfis falsos explica que às vezes “faltava criatividade” para criar mensagens distintas controlando tantos perfis falsos ao mesmo tempo.\n\nGRAGNANI, J. Disponível em: www.bbc.com. Acesso em: 16 dez. 2017.", "prompt": "De acordo com o texto, a análise de características da linguagem empregada por perfis automatizados contribui para o(a)", "alternatives": [{"letter": "A", "text": "Controle da atuação dos profissionais de TI.", "file": null}, {"letter": "B", "text": "Desenvolvimento de tecnologias como os \"trolls\".", "file": null}, {"letter": "C", "text": "Flexibilização dos turnos de trabalho dos controladores.", "file": null}, {"letter": "D", "text": "Necessidade de regulamentação do funcionamento dos \"bots\"", "file": null}, {"letter": "E", "text": "Identificação de padrões de disseminação de informações inverídicas.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/10"}, {"id": "enem-2023-11-geral", "year": 2023, "number": 11, "discipline": "linguagens", "language": null, "context": "Maio foi colorido de amarelo, e o foi porque mundialmente amarelo é a cor convencionada para as advertências. No trânsito, essas advertências têm sido fatais. A estimativa, caso nada seja feito, é a de que se atinjam assustadoras 2,4 milhões de mortes no trânsito em 2030 em todo o mundo.  \nA pressa constante, o sentimento de invencibilidade, a certeza de invulnerabilidade, a necessidade de poder, a falta de civilidade, a certeza de impunidade, a ausência de solidariedade, a inexistência de compaixão e o desrespeito por si próprio são circunstâncias reais que, não raro, concorrem para o comportamento violento no trânsito.  \nO Maio Amarelo, que preconiza a atenção pela vida, é uma das iniciativas nesse sentido. E é precisamente a atenção pela vida que está esquecida. Essa atenção, por certo, requer menos pressa, mais civilidade, limites assegurados, consciência de vulnerabilidade, solidariedade, compaixão e respeito por si e pelo outro. Reafirmar e praticar esses princípios e valores talvez seja um caminho mais seguro e menos violento, que garanta a vida e não celebre a morte.\n\nDisponível em: http://portaldotransito.com.br. Acesso em: 11 dez. 2018 (adaptado).", "prompt": "Considerando os procedimentos argumentativos utilizados, infere-se que o objetivo desse texto é", "alternatives": [{"letter": "A", "text": "Enumerar as causas determinantes da violência no trânsito.", "file": null}, {"letter": "B", "text": "Contextualizar a campanha de advertência no cenário mundial.", "file": null}, {"letter": "C", "text": "Divulgar dados numéricos alarmantes sobre acidentes de trânsito.", "file": null}, {"letter": "D", "text": "Sensibilizar o público para a importância de uma direção responsável.", "file": null}, {"letter": "E", "text": "Restringir os problemas da violência no trânsito a aspectos emocionais.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/11"}, {"id": "enem-2023-12-geral", "year": 2023, "number": 12, "discipline": "linguagens", "language": null, "context": "Ainda daquela vez pude constatar a bizarrice dos costumes que constituíam as leis mais ou menos constantes do seu mundo: ao me aproximar, verifiquei que o Sr. Timóteo, gordo e suado, trajava um vestido de franjas e lantejoulas que pertencera a sua mãe. O corpete descia-lhe excessivamente justo na cintura, e aqui e ali rebentava através da costura um pouco da carne aprisionada, esgarçando a fazenda e tornando o prazer de vestir-se daquele modo uma autêntica espécie de suplício. Movia-se ele com lentidão, meneando todas as suas franjas e abanando-se vigorosamente com um desses leques de madeira de sândalo, o que o envolvia numa enjoativa onda de perfume. Não sei direito o que colocara sobre a cabeça, assemelhava-se mais a um turbante ou a um chapéu sem abas de onde saiam vigorosas mechas de cabelos alourados. Como era costume seu também, trazia o rosto pintado — e para isto, bem como para suas vestimentas, apoderara-se de todo o guarda-roupa deixado por sua mãe, também em sua época famosa pela extravagância com que se vestia — o que sem dúvida fazia sobressair-lhe o nariz enorme, tão característico da família Meneses.\n\nCARDOSO, L. Crónica da casa assassinada. São Paulo: Circulo do Livro, s.d.", "prompt": "Pela voz de uma empregada da casa, a descrição de um dos membros da família exemplifica a renovação da ficção urbana nos anos 1950, aqui observada na", "alternatives": [{"letter": "A", "text": "Opção por termos e expressões de sentido ambíguo.", "file": null}, {"letter": "B", "text": "Crítica social inspirada pelo convívio com os patrões.", "file": null}, {"letter": "C", "text": "Descrição impressionista do fetiche do personagem.", "file": null}, {"letter": "D", "text": "Presença de um foco narrativo de caráter impreciso.", "file": null}, {"letter": "E", "text": "Ambiência de mistério das relações entre familiares.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/12"}, {"id": "enem-2023-13-geral", "year": 2023, "number": 13, "discipline": "linguagens", "language": null, "context": "Girassol da madrugada  \nTeu dedo curioso me segue lento no rosto  \nOs sulcos, as sombras machucadas por onde a  \n\\[vida passou.  \nQue silêncio, prenda minha… Que desvio triunfal  \n\\[da verdade,  \nQue círculos vagarosos na lagoa em que uma asa  \n\\[gratuita roçou..\n\nTive quatro amores eternos…  \nO primeiro era moça donzela,  \nO segundo… eclipse, boi que fala, cataclisma,  \nO terceiro era a rica senhora,  \nO quarto és tu… E eu afinal me repousei dos  \n\\[meus cuidados\n\nANDRADE, M. Poesias completas. Rio de Janeiro: Nova Fronteira, 2013 (fragmento).", "prompt": "Perante o outro, o eu lírico revela, na força das memórias evocadas, a", "alternatives": [{"letter": "A", "text": "Vergonha das marcas provocadas pela passagem do tempo.", "file": null}, {"letter": "B", "text": "Indecisão em face das possibilidades afetivas do presente.", "file": null}, {"letter": "C", "text": "Serenidade sedimentada pela entrega pacifica ao desejo.", "file": null}, {"letter": "D", "text": "Frustração causada pela vontade de retorno ao passado.", "file": null}, {"letter": "E", "text": "Disponibilidade para a exploração do prazer efêmero.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/13"}, {"id": "enem-2023-14-geral", "year": 2023, "number": 14, "discipline": "linguagens", "language": null, "context": "**Dão Lalalão**  \nDo povoado do Ão, ou dos sítios perto, alguém precisava urgente de querer vir por escutar a novela do rádio. Ouvia-a, aprendia-a, guardava na ideia, e, retornado ao Ão, no dia seguinte, a repetia a outros.\n\nAssim estavam jantando, vinham os do povoado receber a nova parte da novela do rádio. Ouvir já tinham ouvido tudo, de uma vez, fugia da regra: falhara ali no Ão, na véspera, o caminhão de um comprador de galinhas e ovos, seo Abrãozinho Buristém, que carregava um rádio pequeno, de pilhas, armara um fio no arame da cerca… Mas queriam escutar outra vez, por confirmação. — “A estória é estável de boa, mal que acompridada: taca e não rende…” — explicava o Zuz ao Dalberto.\n\nSoropita começou a recontar o capitulo da novela. Sem trabalho, se recordava das palavras, até com clareza — disso se admirava. Contava com prazer de demorar, encher a sala com o poder de outros altos personagens. Tomar a atenção de todos, pudesse contar aquilo noite adiante. Era preciso trazer luz, nem uns enxergavam mais os outros; quando alguém ria, ria de muito longe. O capitulo da novela estava terminando.\n\nROSA, J. G. **Noites do sertão (Corpo de baile)**. São Paulo: Global, 2021.", "prompt": "Nesse trecho do conto, o gosto dos moradores do povoado por ouvir a novela de rádio recontada por Soropita deve-se ao(à)", "alternatives": [{"letter": "A", "text": "Qualidade do som do rádio.", "file": null}, {"letter": "B", "text": "Estabilidade do enredo contado.", "file": null}, {"letter": "C", "text": "Ineditismo do capítulo da novela.", "file": null}, {"letter": "D", "text": "Jeito singular de falar aos ouvintes.", "file": null}, {"letter": "E", "text": "Dificuldade de compreensão da história.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/14"}, {"id": "enem-2023-15-geral", "year": 2023, "number": 15, "discipline": "linguagens", "language": null, "context": "As cinzas do Museu Nacional, no Rio de Janeiro, consumido pelas chamas no mês de setembro de 2018, são mais do que restos de fósseis, cerâmicas e espécimes raros. O museu abrigava, entre mais de 20 milhões de peças, os esqueletos com as respostas para perguntas que ainda não haviam sido respondidas — ou sequer feitas — por pesquisadores brasileiros. E o incêndio pode ter calado para sempre palavras e cantos indígenas ancestrais, de línguas que não existem mais no mundo.\n\nO acervo do local continha gravações de conversas, cantos e rituais de dezenas de sociedades indígenas, muitas feitas durante a década de 1960 com antigos gravadores de rolo e que ainda não haviam sido digitalizadas. Alguns dos registros abordavam línguas já extintas, sem falantes originais ainda vivos. “A esperança é que outras instituições tenham registros dessas línguas”, diz a linguista Marilia Facó Soares. A pesquisadora, que trabalha com os índios Tikuna, o maior grupo da Amazônia brasileira, crê ter perdido parte de seu material. “Terei que fazer novas viagens de campo para recompor meus arquivos. Mas obviamente não dá para recuperar a fala de nativos já falecidos, geralmente os mais idosos”, lamenta.\n\nDisponível em: https://brasil.elpais.com. Acesso em: 10 dez. 2018 (adaptado).", "prompt": "A perda dos registros linguísticos no incêndio do Museu Nacional tem impacto potencializado, uma vez que", "alternatives": [{"letter": "A", "text": "Exige a retomada das pesquisas por especialistas de diferentes áreas.", "file": null}, {"letter": "B", "text": "Representa danos irreparáveis à memória e à identidade nacionais.", "file": null}, {"letter": "C", "text": "Impossibilita o surgimento de novas pesquisas na área.", "file": null}, {"letter": "D", "text": "Resulta na extinção da cultura de povos originários.", "file": null}, {"letter": "E", "text": "Inviabiliza o estudo da língua do povo Tikuna.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/15"}, {"id": "enem-2023-16-geral", "year": 2023, "number": 16, "discipline": "linguagens", "language": null, "context": "", "prompt": "Mandioca, macaxeira, aipim e castelinha são nomes diferentes da mesma planta. Semáforo, sinaleiro e farol também significam a mesma coisa. O que muda é só o hábito cultural de cada região. A mesma coisa acontece com a Língua Brasileira de Sinais (Libras). Embora ela seja a comunicação oficial da comunidade surda no Brasil, existem sinais que variam em relação à região, à idade e até ao gênero de quem se comunica. A cor verde, por exemplo, possui sinais diferentes no Rio de Janeiro, Paraná e São Paulo. São os regionalismos na língua de sinais.\nEssas variações são um dos temas da disciplina Linguística na língua de sinais, oferecida pela Universidade Estadual Paulista (Unesp) ao longo do segundo semestre. “Muitas pessoas pensam que a língua de sinais é universal, o que não é verdade”, explica a professora e chefe do Departamento de Linguística, Literatura e Letras Clássicas da Unesp. “Mesmo dentro de um mesmo país, ela sofre variação em relação à localização geográfica, à faixa etária e até ao gênero dos usuários” completa a especialista.\nOs surdos podem criar sinais diferentes para identificar lugares, objetos e conceitos. Em São Paulo, o sinal de “cerveja” é feito com um giro do punho como uma meia- volta. Em Minas, a bebida é citada quando os dedos in- dicador e médio batem no lado do rosto. Também ocorrem mudanças históricas. Um sinal pode sofrer alterações decorrentes dos costumes da geração que o utiliza.\nDisponível em: www.educacao.sp.gov.br. Acesso em 1 nov. 2021 (adaptado)\nNesse texto, a Língua Brasileira de Sinais (Libras)", "alternatives": [{"letter": "A", "text": "Passa por fenômenos de variação linguística como qualquer outra língua.", "file": null}, {"letter": "B", "text": "Apresenta variações regionais, assumindo novo sentido para algumas palavras.", "file": null}, {"letter": "C", "text": "Sofre mudança estrutural motivada pelo uso de sinais diferentes para algumas palavras.", "file": null}, {"letter": "D", "text": "Diferencia-se em todo o Brasil, desenvolvendo cada região a sua própria língua de sinais.", "file": null}, {"letter": "E", "text": "É ininteligível para parte dos usuários em razão das mudanças de sinais motivadas geograficamente.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/16"}, {"id": "enem-2023-17-geral", "year": 2023, "number": 17, "discipline": "linguagens", "language": null, "context": "Como é bom reencontrar os leitores da _Revista da Cultura_ por meio de uma publicação com outro visual, conteúdo de qualidade e interesses ampliados! _\\]cultura\\[_, este nome simples, e eu diria mesmo familiar, nasce entre dois colchetes voltados para fora. E não é por acaso: são sinais abertos, receptivos, propícios à circulação de ideias. O DNA da publicação se mantém o mesmo, afinal, por longos anos montamos nossas edições com assuntos saídos das estantes de uma grande livraria — e assim continuará sendo. Literatura, sociologia, filosofia, artes… nunca será difícil montar a pauta da revista porque os livros nos ensinam que monotonia é só para quem não lê.\n\nHERZ, P. J _**\\]cultura\\[**_, n. 1, jun. 2018 (adaptado).", "prompt": "O uso não padrão dos colchetes para nomear a revista atribui-lhes uma nova função e está correlacionado ao(à)", "alternatives": [{"letter": "A", "text": "Perfil de público-alvo, constituído por leitores exigentes e especializados em leitura acadêmica.", "file": null}, {"letter": "B", "text": "Propósito do editor, chamando a atenção para o rigor normativo nos textos da revista.", "file": null}, {"letter": "C", "text": "Exclusividade na seleção temática, direcionada para a área das ciências humanas.", "file": null}, {"letter": "D", "text": "Identidade da revista, voltada para a recepção e a promoção de ideias circulantes em livros.", "file": null}, {"letter": "E", "text": "Padrão editorial dos artigos, organizados em torno de uma proposta de design inovador.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/17"}, {"id": "enem-2023-18-geral", "year": 2023, "number": 18, "discipline": "linguagens", "language": null, "context": "**TEXTO I**\n\n**Alegria, alegria**  \nO sol nas bancas de revista  \nMe enche de alegria e preguiça  \nQuem lê tanta noticia  \nEu vou  \nPor entre fotos e nomes  \nOs olhos cheios de cores  \nO peito cheio de amores vãos  \nEu vou  \nPor que não, por que não?\n\nVELOSO, C. **Alegria, alegria**. Rio de Janeiro: Polygram, 1990 (fragmento)\n\n**ТЕХТО II**\n\n**Anjos tronchos**  \nUns anjos tronchos do Vale do Silício  \nDesses que vivem no escuro em plena luz  \nDisseram vai ser virtuoso no vício  \nDas telas dos azuis mais do que azuis\n\nAgora a minha história é um denso algoritmo  \nQue vende venda a vendedores reais  \nNeurônios meus ganharam novo outro ritmo  \nE mais, e mais, e mais, e mais, e mais\n\nVELOSO, C. **Meu coco**. Rio de Janeiro: Sony, 2021 (fragmento)", "prompt": "Embora oriundas de momentos históricos diferentes essas letras de canção têm em comum a", "alternatives": [{"letter": "A", "text": "Referência às cores como elemento de crítica a hábitos contemporâneos.", "file": null}, {"letter": "B", "text": "Percepção da profusão de informações gerada pela tecnologia.", "file": null}, {"letter": "C", "text": "Contraposição entre os vícios e as virtudes da vida moderna.", "file": null}, {"letter": "D", "text": "Busca constante pela liberdade de expressão individual.", "file": null}, {"letter": "E", "text": "Crítica à finalidade comercial das notícias.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/18"}, {"id": "enem-2023-19-geral", "year": 2023, "number": 19, "discipline": "linguagens", "language": null, "context": "", "prompt": "“São tantas formas de matar um preto\nQue para alguns sua morte é justificada\nDevia tá fazendo coisa errada\nSe não era bandido, um dia ia ser\nPor ser PRETO sua morte é defendida\nO PRETO sempre merece morrer”.\nA estrofe acima é do poeta e educador social Baticum Proletário, que atua na periferia de Fortaleza, no Ceará, preparando jovens — em quase sua totalidade negros – para enfrentar as dificuldades impostas pelo racismo estrutural no país.\nÉ a partir da arte que Baticum consegue envolver a juventude em um projeto de fortalecimento dessa população ao promover batalhas de rimas, slams e saraus com temáticas que discutem os problemas sociais. Não por acaso, o tema mais explorado nas rimas, versos e prosas é a violência. De acordo com o mais recente Atlas da violência, em 2019, os negros representaram 77% das vítimas de homicídios, quase 30 assassinatos por 100 mil habitantes, a maioria deles jovens.\nO Atlas revela ainda que um negro tem quase 2,7 vezes mais chance de ser morto do que um branco, o que justifica o movimento de resistência crescente no Brasil.\nMENDONÇA. F. Disponível em: www.cartacapital.com.br. Acesso em: 22 nov. 2021 (adaptado).\nO uso de citação e de dados estatísticos nesse texto tem o objetivo de", "alternatives": [{"letter": "A", "text": "Ressaltar a importância da poesia para denunciar a morte de negros, que cresce a cada dia.", "file": null}, {"letter": "B", "text": "Destacar o crescimento exponencial da temática do preconceito na produção literária no Brasil.", "file": null}, {"letter": "C", "text": "Demonstrar o incremento no quantitativo de expressões artísticas na discussão de problemas sociais.", "file": null}, {"letter": "D", "text": "Evidenciar argumentos que reforçam a ideia de que os negros são vítimas em potencial da violência.", "file": null}, {"letter": "E", "text": "Salientar o aumento da participação de jovens nos movimentos de resistência na área da cultura.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/19"}, {"id": "enem-2023-20-geral", "year": 2023, "number": 20, "discipline": "linguagens", "language": null, "context": "", "prompt": "No princípio era o verbo. A frase que abre o primeiro capítulo do Evangelho de João e remete à criação do mundo, assim como também faz o Gênesis, é a mais famosa da Bíblia. A ideia de que o mundo é criado pela palavra, porém, é tão estruturante que está presente em outras religiões, para muito além das fundadas no cristianismo. Como humanos, a linguagem é o mundo que habitamos. Basta tentar imaginar um mundo em que não podemos usar palavras para dizer de nós e dos outros para compreender o que isso significa. Ou um mundo em que aquilo que você diz não é entendido pelo outro, e o que o outro diz não é entendido por você.\nO que acontece então quando a palavra é destruída e, com ela, a linguagem?\nDurante séculos, em diferentes sociedades e línguas, é importante lembrar, a linguagem serviu — e ainda serve — para manter privilégios de grupos de poder e deixar todos os outros de fora. Quem entende linguagem de advogados, juízes e promotores, linguagem de médicos, linguagem de burocratas, linguagem de cientistas? A maior parte da população foi submetida à violência de proposital mente ser impedida de compreender a linguagem daqueles que determinam seus destinos.\nSe o princípio é o verbo, o fim pode ser o silenciamento. Mesmo que ele seja cheio de gritos entre aqueles que já não têm linguagem comum para compreender uns aos outros.\nBRUM, E. Disponível em: https://brasil.elpais.com. Acesso em: 5 nov. 2021.\nNesse texto, a estratégia usada para convencer o leitor de que uma grande parcela da população não compreende a linguagem daqueles que detêm o poder foi", "alternatives": [{"letter": "A", "text": "Revelar a origem religiosa da linguagem.", "file": null}, {"letter": "B", "text": "Questionar o temor sobre o futuro da linguagem.", "file": null}, {"letter": "C", "text": "Descrever a relação entre sociedade e linguagem.", "file": null}, {"letter": "D", "text": "Apresentar as consequências do esfacelamento da linguagem.", "file": null}, {"letter": "E", "text": "Criticar o obstáculo promovido pelos usos especializa- dos da linguagem.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/20"}, {"id": "enem-2023-21-geral", "year": 2023, "number": 21, "discipline": "linguagens", "language": null, "context": "", "prompt": "Um grupo de pesquisadores da Universidade Federal do Ceará desenvolveu um dicionário para traduzir sintomas de doenças da linguagem popular para os termos médicos. Defruço, chanha e piloura, por exemplo, podem ser termos conhecidos para muitos, mas, durante uma consulta médica, o desconhecimento pode significar um diagnóstico errado.\n“Isso é um registro histórico e pode ser muito útil para estudos dessas comunidades, na abordagem médica delas. É de certa forma pioneiro no Brasil e, sem dúvida, um instrumento de trabalho importante, porque a comunicação é fundamental na relação médico-paciente”, avalia o reitor da instituição.\nDisponível em: https://gl.globo.com. Acesso em: 1 nov. 2021 (adaptado).\nAo registrarem usos regionais de termos da área médica, Pesquisadores", "alternatives": [{"letter": "A", "text": "Apontaram erros motivados pelo desconhecimento da variedade linguística local.", "file": null}, {"letter": "B", "text": "Explicaram problemas provocados pela incapacidade de comunicação.", "file": null}, {"letter": "C", "text": "Descobriram novos sintomas de doenças existentes na comunidade.", "file": null}, {"letter": "D", "text": "Propiciaram melhor compreensão dos sintomas dos pacientes.", "file": null}, {"letter": "E", "text": "Divulgaram um novo rol de doenças características da localidade.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/21"}, {"id": "enem-2023-22-geral", "year": 2023, "number": 22, "discipline": "linguagens", "language": null, "context": "Alguém muito recentemente cortara o mato, que na época das chuvas crescia e rodeava a casa da mãe de Ponciá Vicêncio e de Luandi. Havia também vestígios de que a terra fora revolvida, como se ali fosse plantar uma pequena roça. Luandi sorriu. A mãe devia estar bastante forte, pois ainda labutava a terra. Cantou alto uma cantiga que aprendera com o pai, quando eles trabalhavam na terra dos brancos. Era uma canção que os negros mais velhos ensinavam aos mais novos. Eles diziam ser uma cantiga de voltar, que os homens, lá na África, entoavam sempre, quando estavam regressando da pesca, da caça ou de algum lugar. O pai de Luandi, no dia em que queria agradar à mulher, costumava entoar aquela cantiga ao se aproximar de casa. Luandi não entendia as palavras do canto; sabia, porém, que era uma língua que alguns negros falavam ainda, principalmente os velhos. Era uma cantiga alegre. Luandi, além de cantar, acompanhava o ritmo batendo com as palmas das mãos em um atabaque imaginário. Estava de regresso à terra. Voltava em casa. Chegava cantando, dançando a doce e vitoriosa cantiga de regressar.\n\nEVARISTO, C. **Ponciá Vicêncio**. Rio de Janeiro: Pallas, 2018.", "prompt": "A leitura do texto permite reconhecer a “cantiga de voltar” como patrimônio linguístico que", "alternatives": [{"letter": "A", "text": "Representa a memória de uma língua africana extinta.", "file": null}, {"letter": "B", "text": "Exalta a rotina executada por jovens afrodescendentes.", "file": null}, {"letter": "C", "text": "Preserva a ancestralidade africana por meio da tradição oral.", "file": null}, {"letter": "D", "text": "Resgata a musicalidade africana por meio de palavras inteligíveis", "file": null}, {"letter": "E", "text": "Remonta à tristeza dos negros mais velhos com saudade da África.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/22"}, {"id": "enem-2023-23-geral", "year": 2023, "number": 23, "discipline": "linguagens", "language": null, "context": "TEXTO I  \nZapeei os canais, como há dezenas de anos faço, e pá: parei num que exibia um episódio daquela velha família do futuro, Os Jetsons.  \nNesse episódio em particular, a Jane Jetson, esposa do George, tratava de dirigir aquele veículo voador deles. Meu queixo foi caindo à medida que as piadinhas machistas sobre mulheres dirigirem foram se acumulando.  \nImpressionante! Que futuro careta aqueles roteiristas imaginavam! Seriam incapazes de projetar algo melhor, e não apenas em termos de tecnologias, robôs e carros voadores? Será que nossa máxima visão de futuro só atinge as coisas, e jamais as pessoas? Como a Jane, uma mulher de 33 anos no desenho, poderia ser o que foram as minhas bisavós?  \nO futuro, naquele desenho, se esqueceu de ser melhor nas relações entre as pessoas. Aliás… tão parecido com a vida.  \nFiquei de cara, como dizemos aqui, ou como dizíamos na minha adolescência, pobre adolescência, aprendendo, sem querer e sem muita defesa, um futuro tão besta quanto o passado.\n\nRIBEIRO, A. E. Disponível em: www.rascunho.com.br. Acesso em: 21 out. 2021 (adaptado).\n\nTEXTO II  \nMasculino e feminino são campos escorregadios que só se definem por oposição, sempre incompleta, um do outro. São formações imaginárias que buscam produzir uma diferença radical e complementar onde só existem, de fato, mínimas diferenças. O resto é questão de estilo. Até pelo menos a segunda metade do século 19, o divisor de águas era claro: os homens ocupavam o espaço público. As mulheres tratavam da vida privada. Privada de quê? De visibilidade, diria Hannah Arendt. De visibilidade pública. Do que as mulheres estiveram privadas até o século 20 foi de presença pública manifesta não em imagem, mas em palavra. A palavra feminina, reservada ao espaço doméstico, não produzia diferença na vida social.\n\nKHEL, M. R. Disponível em: https://alias.estadao.com.br. Acesso em: 19 out. 2021 (adaptado).", "prompt": "A representação da mulher apresentada no Texto I pode ser explicada pelo Texto II no que diz respeito à(às)", "alternatives": [{"letter": "A", "text": "Censura a formas de expressão femininas.", "file": null}, {"letter": "B", "text": "Ausência da figura feminina na vida pública.", "file": null}, {"letter": "C", "text": "Construções imaginárias cristalizadas na sociedade.", "file": null}, {"letter": "D", "text": "Limitações inerentes às figuras femininas e masculinas.", "file": null}, {"letter": "E", "text": "Dificuldade na atribuição de papéis masculinos e femininos.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/23"}, {"id": "enem-2023-24-geral", "year": 2023, "number": 24, "discipline": "linguagens", "language": null, "context": "![](https://enem.dev/2023/questions/24/78918e1a-00e2-4972-b8f7-9cc17a935ec2.png)", "prompt": "Esse anúncio publicitário, veiculado durante o contexto da pandemia de covid-19, tem por finalidade", "alternatives": [{"letter": "A", "text": "Divulgar o canal telefônico de atendimento a casos de violência contra a mulher.", "file": null}, {"letter": "B", "text": "Informar sobre a atuação de uma entidade defensora da mulher vítima de violência.", "file": null}, {"letter": "C", "text": "Evidenciar o trabalho da Defensoria Pública em relação ao problema do abuso contra a mulher.", "file": null}, {"letter": "D", "text": "Alertar a sociedade sobre o aumento da violência contra a mulher em decorrência do coronavírus.", "file": null}, {"letter": "E", "text": "Incentivar o público feminino a denunciar crimes de violência contra a mulher durante o período de isolamento", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/24"}, {"id": "enem-2023-25-geral", "year": 2023, "number": 25, "discipline": "linguagens", "language": null, "context": "Passado muito tempo, resolvi tentar falar, porque estava sozinha me embrenhando na mesma vereda que Donana costumava entrar. Ainda recordo da palavra que escolhi: arado. Me deleitava vendo meu pai conduzindo o arado velho da fazenda carregado pelo boi, rasgando a terra para depois lançar grãos de arroz em torrões marrons e vermelhos revolvidos. Gostava do som redondo fácil e ruidoso que tinha ao ser enunciado. “Vou trabalhar no arado.” “Vou arar a terra.” “Seria bom ter um arado novo, esse arado tá troncho e velho.” O som que deixou minha boca era uma aberração, uma desordem, como se no lugar do pedaço perdido da língua tivesse um ovo quente. Era um arado torto, deformado, que penetrava a terra de tal forma a deixá-la infértil, destruída, dilacerada.\n\nVIEIRA JR.. I. **Torto arado**. São Paulo: Todavia, 2019.", "prompt": "Com a perda de parte da língua na infância, a narradora tenta voltar a falar. Essa tentativa revela uma experiência que", "alternatives": [{"letter": "A", "text": "Reflete o olhar do pai sobre as etapas do plantio.", "file": null}, {"letter": "B", "text": "Metaforiza a linguagem como ferramenta de lavoura.", "file": null}, {"letter": "C", "text": "Explicita, na busca pela palavra, o medo da solidão.", "file": null}, {"letter": "D", "text": "Confirma a frustração da narradora com relação à terra.", "file": null}, {"letter": "E", "text": "Sugere, na ausência da linguagem, a estagnação do tempo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/25"}, {"id": "enem-2023-26-geral", "year": 2023, "number": 26, "discipline": "linguagens", "language": null, "context": "**A escravidão**\n\nEsses meninos que aí andam jogando peteca não viram nunca um escravo… Quando crescerem, saberão que já houve no Brasil uma raça triste, votada à escravidão e ao desespero; e verão nos museus a coleção hedionda dos troncos, dos vira-mundos e dos bacalhaus; e terão notícias dos trágicos horrores de uma época maldita: filhos arrancados ao seio das mães, virgens violadas em pranto, homens assados lentamente em fornos de cal, mulheres nuas recebendo na sua mísera nudez desvalida o duplo ultraje das chicotadas e dos olhares do feitor bestial. \\[…\\] Mas a sua indignação nunca poderá ser tão grande como a daqueles que nasceram e cresceram em pleno horror, no meio desse horrível drama de sangue e lodo, sentindo dentro do ouvido e da alma, numa arrastada e contínua melopeia, o longo gemer da raça mártir — orquestração satânica de todos os soluços, de todas as impressões, de todos os lamentos que a tortura e a injustiça podem arrancar a gargantas humanas.\n\nBILAC, O. Disponível em: www.escritas.org. Acesso em: 29 out. 2021", "prompt": "Publicado em 1902, o texto de Olavo Bilac enfatiza as mazelas da escravidão no Brasil ao", "alternatives": [{"letter": "A", "text": "Descrever de modo impessoal as consequências da exploração racial sobre as gerações futuras.", "file": null}, {"letter": "B", "text": "Contrapor a infância privilegiada das crianças da época à infância violentada das crianças escravizadas.", "file": null}, {"letter": "C", "text": "Antecipar o futuro apagamento das marcas da escravidão no contexto social.", "file": null}, {"letter": "D", "text": "Criticar a atenuação da violência contra os povos escravizados nas memórias retratadas pelos museus.", "file": null}, {"letter": "E", "text": "Imaginar a reação de indiferença de seus contemporâneos com os escravizados libertos.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/26"}, {"id": "enem-2023-27-geral", "year": 2023, "number": 27, "discipline": "linguagens", "language": null, "context": "", "prompt": "E assim as coisas continuaram acontecendo entre os dois, em quase sustos, um grande por acaso com cacoetes de gestos definitivos. Com o Nunca Mais se oferecendo o tempo todo, bastaria dizer foi um prazer ter te conhecido, bastaria não trocar telefones nem e-mails e enterrar a casualidade com a cal da sabedoria – nada poderia ser definitivo, os encontros duravam duas horas ou duas décadas ou duas vezes isso, mas em algum momento necessariamente seria o fim. De todos os grandes amores, De todos os pequenos. De todas as juras, das promessas, de todos os na-alegria-e-na-tristeza. De todos os não amores, os desamores, os casamentos para sempre, os rancores para sempre, de todas as paralelas que só se viabilizam na abstração da geometria, de todas as pequenas paixões e de todas as grandes paixões, de tudo que para na antessala da paixão, de todos os vínculos não experimentados, de todos.\nLISBOA, A. Rahushisha. Rio de Janeiro Objetiva 2014.\nO recurso que promove a progressão textual, contribuindo para a construção da ideia de que as relações amorosas têm um enredo comum, é a", "alternatives": [{"letter": "A", "text": "Repetição do pronome indefinido \"todos\".", "file": null}, {"letter": "B", "text": "Utilização do travessão na marcação do oposto.", "file": null}, {"letter": "C", "text": "Retomada do antecedente pelo pronome \"isso\".", "file": null}, {"letter": "D", "text": "Contraposição de ideias marcada pela conjunção mas.", "file": null}, {"letter": "E", "text": "Substantivação de expressões pela anteposição do artigo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/27"}, {"id": "enem-2023-28-geral", "year": 2023, "number": 28, "discipline": "linguagens", "language": null, "context": "", "prompt": "A garganta é a gruta que guarda o som\nA garganta está entre a mente e o coração\nVem coisa de cima, vem coisa de baixo e de \n[repente um nó (e o que eu quero dizer?)\nÀs vezes, acontece um negócio esquisito\nQuando eu quero falar eu grito, quando eu quero\n[gritar eu falo, o resultado\nCalo.\nESTRELA D’ALVA, R. Disponível em: https://claudia.abril.com.br. Acesso em: 23 nov. 2021 (fragmento).\nA função emotiva presente no poema cumpre o propósito do eu lírico de", "alternatives": [{"letter": "A", "text": "Revelar as desilusões amorosas.", "file": null}, {"letter": "B", "text": "Refletir sobre a censura à sua voz", "file": null}, {"letter": "C", "text": "Expressar a dificuldade de comunicação.", "file": null}, {"letter": "D", "text": "Ressaltar a existência de pressões externas.", "file": null}, {"letter": "E", "text": "Manifestar as dores do processo de criação.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/28"}, {"id": "enem-2023-29-geral", "year": 2023, "number": 29, "discipline": "linguagens", "language": null, "context": "Era um gato preto, como convinha a um cultor das boas letras, que já lera Poe traduzido por Baudelaire. Preto e gordo. E lerdo. Tão gordo e lerdo que a certa altura observei que ia perdendo inteiramente as qualidades características da raça, que são em suma o ódio de morte aos ratos. Já nem os afugentava! Os ratos de Ouro Preto são também dignos e solenes — não ria — tradicionalistas… descendentes de outros ratos que naqueles mesmos casarões presenciaram acontecimentos importantes da nossa história… No sobrado do desembargador Tomás Antônio Gonzaga, imagine o senhor uma reunião dos sonhadores inconfidentes, com os antepassados daqueles ratos a passearem pelo sótão ou mesmo pelo assoalho por entre as pernas dos homens absortos na esperança da independência nacional! E depois, os ancestres daqueles roedores que eu via agora deslizar sutilmente no meu quarto podiam ter subido pelo poste da ignomínia colonial, onde estava exposta a cabeça do Tiradentes! E quando as órbitas se descarnaram ignominiosamente, podiam até ter penetrado no recesso daquele crânio onde verdadeiramente ardera a literatura, com a simplicidade do heroísmo, a febre nacionalista…\n\nALPHONSUS, J. **Contos e novelas**. Rio de Janeiro: Imago; Brasília: INL, 1976.", "prompt": "Descrevendo seu gato, o narrador remete ao contexto e a protagonistas da Inconfidência para criar um efeito desconcertante centrado no", "alternatives": [{"letter": "A", "text": "Desenho imaginativo do casario colonial de Ouro Preto.", "file": null}, {"letter": "B", "text": "Efeito de apagamento de limites entre ficção e realidade.", "file": null}, {"letter": "C", "text": "Vínculo estabelecido entre animais urbanos e literatura.", "file": null}, {"letter": "D", "text": "Questionamento sutil quanto à sanidade dos inconfidentes.", "file": null}, {"letter": "E", "text": "Contraste entre austeridade pomposa e imagem repugnante.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/29"}, {"id": "enem-2023-30-geral", "year": 2023, "number": 30, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Enquanto estivemos entretidos com os urubus outras coisas andaram acontecendo na cidade. A Companhia baixou novas proibições, umas inteiramente bobocas, só pelo prazer de proibir (ninguém podia cuspir pra cima, nem carregar água em jacá, nem tapar o sol com peneira, como se todo mundo estivesse abusando dessas esquisitices); mas outras bem irritantes, como a de pular muro pra cortar caminho, tática que quase todo mundo que não sofria de reumatismo vinha adotando ultimamente, principalmente os meninos. E não confiando na proibição só, nem na força dos castigos, que eram rigorosos, a Companhia ainda mandou fincar cacos de garrafa nos muros. Achei isso um exagero, e comentei o assunto com mamãe. Meu pai ouviu lá do quarto e veio explicar. Disse que em épocas normais bastava uma coisa ou outra; mas agora a Companhia não podia admitir nenhuma brecha em suas ordens; se alguém desobedecesse à proibição podia se cortar nos cacos; se alguém conseguisse pular um muro quebrando era apanhado pela proibição, nhoc – e fez o gesto de quem torce o pescoço de um frango.\nVEIGA, J. J. Sombras de reis barbudos. Rio de Janeiro: Civilização Brasileira, 1978.\nSob a perspectiva do menino que narra, os fatos ficcionais oferecem um esboço do momento político vigente na década de 1970, aqui representado pelo", "alternatives": [{"letter": "A", "text": "Culto ao medo, infiltrado em situações do cotidiano.", "file": null}, {"letter": "B", "text": "Sentimento de dúvida quanto à veracidade das informações.", "file": null}, {"letter": "C", "text": "Ambiente de sonho, delineado por imagens perturbadoras.", "file": null}, {"letter": "D", "text": "Incentivo ao desenvolvimento econômico com a iniciativa privada.", "file": null}, {"letter": "E", "text": "Espaço urbano marcado por uma política de isolamento das crianças.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/30"}]') on conflict(id) do nothing;
insert into orbit_private.answer_keys select * from jsonb_populate_recordset(null::orbit_private.answer_keys,'[{"question_id": "enem-2023-1-espanhol", "correct_letter": "A"}, {"question_id": "enem-2023-2-espanhol", "correct_letter": "A"}, {"question_id": "enem-2023-3-espanhol", "correct_letter": "E"}, {"question_id": "enem-2023-4-espanhol", "correct_letter": "B"}, {"question_id": "enem-2023-5-espanhol", "correct_letter": "A"}, {"question_id": "enem-2023-6-geral", "correct_letter": "D"}, {"question_id": "enem-2023-7-geral", "correct_letter": "A"}, {"question_id": "enem-2023-8-geral", "correct_letter": "C"}, {"question_id": "enem-2023-9-geral", "correct_letter": "E"}, {"question_id": "enem-2023-10-geral", "correct_letter": "E"}, {"question_id": "enem-2023-11-geral", "correct_letter": "D"}, {"question_id": "enem-2023-12-geral", "correct_letter": "C"}, {"question_id": "enem-2023-13-geral", "correct_letter": "C"}, {"question_id": "enem-2023-14-geral", "correct_letter": "D"}, {"question_id": "enem-2023-15-geral", "correct_letter": "B"}, {"question_id": "enem-2023-16-geral", "correct_letter": "A"}, {"question_id": "enem-2023-17-geral", "correct_letter": "D"}, {"question_id": "enem-2023-18-geral", "correct_letter": "B"}, {"question_id": "enem-2023-19-geral", "correct_letter": "D"}, {"question_id": "enem-2023-20-geral", "correct_letter": "E"}, {"question_id": "enem-2023-21-geral", "correct_letter": "D"}, {"question_id": "enem-2023-22-geral", "correct_letter": "C"}, {"question_id": "enem-2023-23-geral", "correct_letter": "C"}, {"question_id": "enem-2023-24-geral", "correct_letter": "E"}, {"question_id": "enem-2023-25-geral", "correct_letter": "B"}, {"question_id": "enem-2023-26-geral", "correct_letter": "C"}, {"question_id": "enem-2023-27-geral", "correct_letter": "A"}, {"question_id": "enem-2023-28-geral", "correct_letter": "C"}, {"question_id": "enem-2023-29-geral", "correct_letter": "E"}, {"question_id": "enem-2023-30-geral", "correct_letter": "A"}]') on conflict(question_id) do nothing;
