insert into public.orbit_questions(id,year,number,discipline,language,context,prompt,alternatives,source_url) select id,year,number,discipline,language,context,prompt,alternatives,source_url from jsonb_populate_recordset(null::public.orbit_questions,'[{"id": "enem-2023-31-geral", "year": 2023, "number": 31, "discipline": "linguagens", "language": null, "context": "**Migalhas**\n\nEntre a toalha branca e um bule de café\n\nseria inapropriado dizer\n\neu não te amo mais.\n\nEra necessário algo mais solene,\n\num jardim japonês para as perdas pensadas,\n\num noturno de tempestade para arrebentar de dor,\n\numa praia de pedras para chorar em silêncio,\n\numa cama alta para o incenso da despedida,\n\numa janela dando para o abismo.\n\nNo entanto você abaixa os olhos\n\ne recolhe lentamente as migalhas de pão\n\nsobre a mesa posta para dois.\n\nMARQUES, A. M. **A vida submarina**. São Paulo: Cia. das Letras, 2021.", "prompt": "Nesse poema, a representação do sentimento amoroso recupera a tradição lírica, mas se ajusta à visão contemporânea ao", "alternatives": [{"letter": "A", "text": "Invocar o interlocutor para uma tomada de posição.", "file": null}, {"letter": "B", "text": "Questionar a validade do envolvimento romântico.", "file": null}, {"letter": "C", "text": "Diluir em banalidade a comoção de um amor frustrado.", "file": null}, {"letter": "D", "text": "Transformar em paz as emoções conflituosas do casal.", "file": null}, {"letter": "E", "text": "Condicionar a existência da paixão a espaços idealizados.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/31"}, {"id": "enem-2023-32-geral", "year": 2023, "number": 32, "discipline": "linguagens", "language": null, "context": "", "prompt": "O sol começa a descer por trás da vegetação da Ilha da Restinga, na outra margem do rio Paraíba, colorindo o céu de amarelo, laranja e lilás. Então se ouvem as primeiras notas do Bolero, do compositor francês Maurice Ravel, executadas pelo saxofonista Jurandy. É assim o pôr do sol da praia do Jacaré, em Cabedelo (Grande João Pessoa). Depois do Bolero, Jurandy toca Asa branca, de Luiz Gonzaga, e Meu sublime torrão, de Genival Macedo, espécie de hino não oficial da Paraíba.\nPINHEIRO, A. Sol se põe embaiado pelo Bolero de Ravel. Disponível em: http://tools.folha.com.br. Acesso em: 16 set. 20212 (adaptado).\nA interpretação musical de Jurandy do Sax, codinome de José Jurandy Félix, apresenta caracterizado pela", "alternatives": [{"letter": "A", "text": "Inter-relação de referenciais estéticos aparentemente distanciados.", "file": null}, {"letter": "B", "text": "Valorização de músicas que revelam mensagens de serenidade.", "file": null}, {"letter": "C", "text": "Consagração do repertório erudito como cultura dominante.", "file": null}, {"letter": "D", "text": "Iniciativa de estímulo à vocação turística da cidade.", "file": null}, {"letter": "E", "text": "Divisão hierárquica entre gêneros e estilos musicais.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/32"}, {"id": "enem-2023-33-geral", "year": 2023, "number": 33, "discipline": "linguagens", "language": null, "context": "**Texto I**\n\n![](https://enem.dev/2023/questions/33/d3f9dfc2-3337-498f-8dcd-67a7f5909bbb.png)\n\nSEGALL, L. Eternos caminhantes. Óleo sobre tela, 138 x 184 cm. Museu Lasar Segall. IbramMinc. São Paulo, 1919.\n\n**Texto II**\n\nEm 1933, a obra Eternos caminhantes ingressou em uma das primeiras edições das exposições de Arte Degenerada, promovida por membros do partido nazista alemão. Nos anos seguintes, ela voltaria a ser exibida na mostra denominada Exposição da Vergonha, promovida por pequenos grupos abastados. Em 1937, essa obra foi confiscada pelo Ministério da Propaganda daquele país, na grande ação nacional-socialista contra a “Arte Degenerada”.\n\nSCHWARTZ, J. Perseguição à Arte Moderna em tempos de amarra São Paulo: Museu Lasar Segall, 2018 (adaptado)", "prompt": "Quase cinquenta obras de Lasar Segall foram confiscadas pelo regime totalitário alemão na primeira metade do século XX, entre elas a obra Eternos caminhantes, considerada degenerada por", "alternatives": [{"letter": "A", "text": "Representar uma estética tida como inconveniente para o ideário político vigente.", "file": null}, {"letter": "B", "text": "Manifestar um posicionamento político-cultural concebido por grupos de oposição.", "file": null}, {"letter": "C", "text": "Expressar a cultura artística por meio da representação parcial do corpo humano.", "file": null}, {"letter": "D", "text": "Apresentar uma composição que antecipa o imaginário artístico germânico.", "file": null}, {"letter": "E", "text": "Estimular discussões sobre o papel da arte na construção coletiva de cultura.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/33"}, {"id": "enem-2023-35-geral", "year": 2023, "number": 35, "discipline": "linguagens", "language": null, "context": "A indústria do esporte eletrônico é um mercado que está crescendo em um ritmo mais rápido do que a economia mundial. Sua popularidade cresceu muito e no Brasil não é diferente. De acordo com os dados de uma pesquisa, mais de 64% dos brasileiros que jogam videogame já ouviram falar de esporte eletrônico. No entanto, o que chama a atenção é o crescimento superior a 10% do público praticante comparado ao ano anterior, que subiu de 44,7% para 55,4%. Trata-se de um percentual expressivo, já que o Brasil está no top 3 dentre os países que têm maior número de espectadores de esporte eletrônico do mundo. Comparado ao ano anterior, em 2020, o Brasil teve um marco de crescimento de 20% na audiência. Mundo afora, a árdua dedicação de grandes gamers contribuiu para o reconhecimento do Comitê Olímpico Internacional, aliado a outras cinco federações esportivas e suas desenvolvedoras de jogos, que direcionaram um olhar mais atento ao assunto, permitindo dar o primeiro passo para concretizar, pela primeira vez na história dos jogos eletrônicos, um evento olímpico oficial.\n\nDisponível em: https://chicoterra.com. Acesso em: 15 nov. 2021 (adaptado).", "prompt": "O contexto em que o esporte eletrônico é apresentado no texto demonstra o(a)", "alternatives": [{"letter": "A", "text": "Condição favorável à expansão dessa modalidade.", "file": null}, {"letter": "B", "text": "Promoção dessa prática por jogadores profissionais.", "file": null}, {"letter": "C", "text": "Impulsionamento de um processo de marketing.", "file": null}, {"letter": "D", "text": "Favorecimento de fabricantes dos jogos.", "file": null}, {"letter": "E", "text": "Modificação da audiência televisiva.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/35"}, {"id": "enem-2023-36-geral", "year": 2023, "number": 36, "discipline": "linguagens", "language": null, "context": "Marabaixo é uma expressão artistico-cultural formada nas tradições e na identificação cultural entre as comunidades negras do Amapá. O nome remonta às mortes de escravizados em navios negreiros que eram jogados na água. Em sua homenagem, hinos de lamento eram cantados mar abaixo, mar acima. Posteriormente, o Marabaixo se integrou à vivência das comunidades negras em um ciclo de danças, cantorias com tambores e festas religiosas, recebendo, em 2018, o título de Patrimônio Cultural do Brasil.\n\nDisponível em: http://portal.iphan.gov.br. Acesso em: 15 nov. 2021 (adaptado).", "prompt": "A manifestação do Marabaixo se constituiu em expressão de arte e cultura, exercendo função de", "alternatives": [{"letter": "A", "text": "Ressignificar episódios dramáticos em novas práticas culturais.", "file": null}, {"letter": "B", "text": "Adaptar coreografias como imitação dos movimentos do mar.", "file": null}, {"letter": "C", "text": "Lembrar dos mortos no passado escravista como forma de lamento.", "file": null}, {"letter": "D", "text": "Perpetuar uma narrativa de apagamento dos fatos históricos traumáticos.", "file": null}, {"letter": "E", "text": "Ritualizar a passagem de atos fúnebres nas produções coletivas com espírito festivo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/36"}, {"id": "enem-2023-37-geral", "year": 2023, "number": 37, "discipline": "linguagens", "language": null, "context": "O uso das redes sociais como forma de ampliar universos foi uma descoberta recente para o artista Wolney Fernandes, que começou a criar quando o ambiente em Goiás era mais árido em relação às artes visuais. “Hoje, ser diferente é uma potência e quem sabe o que quer com a própria arte encontra espaço”, diz. As colagens artísticas do goiano aparecem em capas de obras literárias pelo Brasil e exterior.\n\nDisponível em: https://opopular.com.br. Acesso em: 15 nov. 2021 (adaptado).", "prompt": "O artista goiano Wolney Fernandes busca expor seu trabalho por meio de plataformas virtuais com o objetivo de", "alternatives": [{"letter": "A", "text": "Dar suporte à técnica de colagem em Artes Visuais, contornando dificuldades práticas.", "file": null}, {"letter": "B", "text": "Aproximar-se da estética visual própria da editoração de obras artísticas, como capas de livros.", "file": null}, {"letter": "C", "text": "Oferecer uma vitrine internacional para sua produção artística, a fim de dar mais visibilidade a suas obras.", "file": null}, {"letter": "D", "text": "Enfatizar o caráter original e inovador de suas criações artísticas, diferenciando-se das artes tradicionais.", "file": null}, {"letter": "E", "text": "Trazer um sentido tecnológico às suas colagens, uma vez que as imagens artísticas são recorrentes nas redes sociais.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/37"}, {"id": "enem-2023-38-geral", "year": 2023, "number": 38, "discipline": "linguagens", "language": null, "context": "", "prompt": "O mais antigo grupo de rap indígena do país, Brô MCs, surgiu em 2009, na aldeia Jaguapiru, em Dourados, Mato Grosso do Sul. Os integrantes conheceram o rap pelo rádio, ouvindo um programa que apresentava cantores e grupos brasileiros desse gênero musical. O Brô MCs conseguiu influenciar outros a fazerem rap e a lutarem pelas causas indígenas. Um dos nomes do movimento, Kunumi MC, é um jovem de 16 anos, da aldeia Krukutu, em São Paulo.\nO adolescente enxerga o rap como uma cultura da defesa e começou a fazer rimas quando percebeu que a poesia, pela qual sempre se interessou, podia virar música.\nNas letras que cria, inspiradas tanto pelo rap quanto pelos ritmos indígenas, tenta incluir sempre assuntos aos quais acha importante dar voz, principalmente, a questão da demarcação de terras.\nDisponível em: www.correiobraziliense.com.br. Acesso em: 13 nov. 2021 (adaptado).\nO movimento rap dos povos originários do Brasil revela o(a)", "alternatives": [{"letter": "A", "text": "Fusão de manifestações artísticas urbanas contemporâneas com a cultura indígena.", "file": null}, {"letter": "B", "text": "Contraposição das temáticas socioambientais indigenas as questões urbanas.", "file": null}, {"letter": "C", "text": "Rejeição da indústria radiofônica às músicas indígenas.", "file": null}, {"letter": "D", "text": "Distanciamento da realidade social indígena.", "file": null}, {"letter": "E", "text": "E estímulo ao estudo da poesia indígena.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/38"}, {"id": "enem-2023-39-geral", "year": 2023, "number": 39, "discipline": "linguagens", "language": null, "context": "A petição on-line criada por um cidadão paulista surtiu efeito: casado há três anos com seu companheiro, ele pedia a alteração da definição de “casamento” no tradicional dicionário _Michaelis_ em português. Na definição anterior, casamento aparecia como “união legítima entre homem e mulher” e “união legal entre homem e mulher, para constituir família”.\n\nO novo verbete não traz em nenhum momento as palavras homem ou mulher — agora a definição de casamento se refere a “pessoas”.\n\nPara o diretor de comunicação do site onde a petição foi publicada, a iniciativa mostra a “eficiência da mobilização”. “Em dois dias, mudou-se uma definição que permanecia a mesma há décadas”, afirma. E conclui: “A plataforma serve para todos os tipos de causas, para as mudanças que importam para as pessoas.”.\n\nSENRA, R. Disponível em: www.bbc.com. Acesso em: 29 out. 2015.", "prompt": "A notícia trata da mudança ocorrida em um dicionário da língua portuguesa. Segundo o texto, essa mudança foi impulsionada pela", "alternatives": [{"letter": "A", "text": "Inclusão de informações no verbete.", "file": null}, {"letter": "B", "text": "Relevância social da instituição casamento.", "file": null}, {"letter": "C", "text": "Utilização pública da petição pelos cidadãos.", "file": null}, {"letter": "D", "text": "Rapidez na disseminação digital do verbete.", "file": null}, {"letter": "E", "text": "Divulgação de plataformas para a criação de petição", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/39"}, {"id": "enem-2023-40-geral", "year": 2023, "number": 40, "discipline": "linguagens", "language": null, "context": "A neozelandesa Laurel Hubbard fez história nos Jogos Olimpicos. Apesar de ter ficado de fora da disputa por medalhas, a levantadora de peso deixou sua marca na edição de Tóquio por ser a primeira mulher abertamente transgênero a participar de uma competição olímpica. No início da carreira, na década de 1990, a neozelandesa participava de disputas na categoria masculina. Em 2001, aos 23 anos, ela se afastou da atividade. “A pressão de tentar me encaixar em um mundo que talvez não tenha sido feito para pessoas como eu se tornou um fardo muito grande para suportar.” Em 2012, Laurel começou sua transição de gênero por meio de terapias hormonais e, em 2013, declarou abertamente ser uma mulher trans. Para o Comitê Olímpico Internacional, a participação de mulheres trans nos Jogos é permitida caso o nível de testosterona, hormônio que aumenta a massa muscular, esteja abaixo de 10 nanomols por litro por pelo menos 12 meses.\n\nDisponivel em: https://revistagalileu.globo.com Acesso em: 18 nov. 2021 (adaptado).", "prompt": "No texto, os limites do potencial inclusivo do esporte são dados pela", "alternatives": [{"letter": "A", "text": "Dificuldade de conseguir bons resultados esportivos.", "file": null}, {"letter": "B", "text": "Dependência de características biológicas padronizadas.", "file": null}, {"letter": "C", "text": "Inexistência de uma categoria para pessoas transgênero", "file": null}, {"letter": "D", "text": "Necessidade de afastamento temporário das competições", "file": null}, {"letter": "E", "text": "Impossibilidade de uso controlado de substâncias", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/40"}, {"id": "enem-2023-41-geral", "year": 2023, "number": 41, "discipline": "linguagens", "language": null, "context": "“Ganhei 25 medalhas em mundiais, sete em Jogos Olímpicos, e sou uma sobrevivente de abuso sexual.” Foi assim que Simone Biles se apresentou ao comitê do Senado norte-americano que investiga as supostas falhas do FBI no caso Larry Nassar. Biles e outras três atletas, vítimas dos abusos do ex-médico da equipe de ginástica feminina dos EUA, exigiram que os agentes da investigação sejam processados por falta de ação prévia contra Nassar, agora preso. Biles esclareceu que culpa Larry Nassar e “todo o sistema que o permitiu e o perpetrou”, acusando a Federação de Ginástica e o Comitê Olímpico dos Estados Unidos de saberem “muito antes” que ela havia sofrido abusos. A melhor ginasta do mundo é um ícone. Nos Jogos Olímpicos de Tóquio, uma lesão psicológica a impediu de competir como previa. No entanto, ela chegou ao topo como uma líder no trabalho de acabar com o preconceito com os problemas de saúde mental. “Não quero que nenhum outro atleta olímpico sofra o horror que eu e outras centenas suportamos e continuamos suportando até hoje”, afirmou.\n\nDisponível em https://brasil.elpais.com Acesso em 31 out 2021 (adaptado).", "prompt": "O fato relatado na notícia chama a atenção acerca da necessidade de reflexão sobre a relação entre o esporte e", "alternatives": [{"letter": "A", "text": "O desempenho atlético internacional.", "file": null}, {"letter": "B", "text": "A dimensão emocional dos atletas.", "file": null}, {"letter": "C", "text": "Os comitês olímpicos nacionais.", "file": null}, {"letter": "D", "text": "As instituições de inteligência.", "file": null}, {"letter": "E", "text": "As federações esportivas.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/41"}, {"id": "enem-2023-42-geral", "year": 2023, "number": 42, "discipline": "linguagens", "language": null, "context": "O acesso às Práticas Corporais/Atividades Físicas (PC/AF) é desigual no Brasil, à semelhança de outros indicadores sociais e de saúde. Em geral, PC/AF prazerosas, diversificadas, mais afeitas ao período de lazer estão concentradas nas populações mais abastadas. As atividades físicas de deslocamento, trajetos a pé ou de bicicleta para estudar ou trabalhar, por exemplo, são mais frequentes na classe social menos favorecida. Aqui, há uma relação inversa e perversa entre variáveis socioeconômicas de acesso às PC/AF. As maiores prevalências de inatividade física foram em mulheres, pessoas com 60 anos ou mais, negros, pessoas com autoavaliação de saúde ruim ou muito ruim, com renda familiar de até quatro salários mínimos por pessoa, pessoas que desconhecem programas públicos de PC/A e residentes em áreas sem locais públicos para a prática.\n\nKNUTH, A. G.; ANTUNES, P. C. **Saúde e Sociedade**, n. 2, 2021 (adaptado).", "prompt": "O fator central que impacta a realização de práticas corporais/atividades fisicas no tempo de lazer no Brasil é a", "alternatives": [{"letter": "A", "text": "Diferença entre homens e mulheres.", "file": null}, {"letter": "B", "text": "Inexistência de políticas públicas.", "file": null}, {"letter": "C", "text": "Diversidade de faixa etária.", "file": null}, {"letter": "D", "text": "Variação de condição étnica.", "file": null}, {"letter": "E", "text": "Desigualdade entre classes sociais.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/42"}, {"id": "enem-2023-43-geral", "year": 2023, "number": 43, "discipline": "linguagens", "language": null, "context": "", "prompt": "Mestre e companheiro, disse eu que nos íamos despedir. Mas disse mal. A morte não extingue: transforma; não aniquila; renova; não divorcia: aproxima. Um dia supuseste “morta e separada” a consorte dos teus sonhos e das tuas agonias, que te soubera “pôr um undo inteiro no recanto” do teu ninho; e, todavia, nunca ela te esteve mais presente, no íntimo de ti mesmo e na expressão do teu canto, no fundo do teu ser e na face de tuas ações. Esses catorze versos inimitáveis, em que o enlevo dos teus discípulos resume o valor de toda uma literatura, eram a aliança de ouro do teu segundo noivado, um anel de outras núpcias, para a vida nova do teu renascimento e da tua glorificação, com a sócia sem nódoa dos teus anos e de mocidade e madureza, da florescência e frutificação de tua alma. Para os eleitos do mundo das ideias a miséria está em decadência, e não na morte. A nobreza de uma nos preserva das ruínas de outra. Quando eles atravessavam essa passagem do invisível, que os conduz à região da verdade sem mescla, então é que entramos a sentir o começo do seu reino, o reino dos mortos sobre os vivos.\nBARBOSA, R. O adeus da Academia a Machado de Assis. Rio de Janeiro: Agir, 1962.\nEsse é um trecho do discurso de Rui Barbosa na Academia Brasileira de Letras em homenagem a Machado de Assis por ocasião de sua morte. Uma das características desse discurso de homenagem é a presença de", "alternatives": [{"letter": "A", "text": "Metáforas relacionadas à trajetória pessoal e criadora do homenageado.", "file": null}, {"letter": "B", "text": "Recursos fonológicos empregados para a valorização do ritmo do texto.", "file": null}, {"letter": "C", "text": "Frases curtas e diretas no relato de vida e da morte do homenageado.", "file": null}, {"letter": "D", "text": "Contraposição de ideias presentes na obra do homenageado.", "file": null}, {"letter": "E", "text": "Seleção vocabular representativa do sentimento de nostalgia.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/43"}, {"id": "enem-2023-44-geral", "year": 2023, "number": 44, "discipline": "linguagens", "language": null, "context": "![](https://enem.dev/broken-image.svg)", "prompt": "Essa campanha publicitária do Ministério da Saúde visa", "alternatives": [{"letter": "A", "text": "Divulgar um conjunto de benefícios proporcionados pela amamentação.", "file": null}, {"letter": "B", "text": "Apresentar tratamentos para infecções respiratórias em bebês.", "file": null}, {"letter": "C", "text": "Defender o direito das mulheres de amamentar em público.", "file": null}, {"letter": "D", "text": "Orientar sobre os exercícios para uma boa amamentação.", "file": null}, {"letter": "E", "text": "Informar sobre o aumento de anticorpos nas mães.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/44"}, {"id": "enem-2023-45-geral", "year": 2023, "number": 45, "discipline": "linguagens", "language": null, "context": "", "prompt": "Carta aberta à população brasileira\nPrezados Cidadãos e Cidadãs, O envelhecimento populacional é um fenômeno mundial. Infelizmente, nosso país ainda não está preparado para atender às demandas dessa população.\nEste é o retrato da saúde pública no Brasil, que, apesar dos indiscutíveis avanços, apresenta um cenário de deficiências e falta de integração em todos os níveis de atenção à saúde: primária (atendimento deficiente nas unidades de saúde da atenção básica), secundária (carência de centros de referência com atendimento por especialistas) e terciária (atendimento hospitalar com abordagem ao idoso centrada na doença), ou seja, não há, na prática, uma rede de atenção à saúde do idoso.\nDiante desse cenário, a Sociedade Brasileira de Geriatria e Gerontologia (SBGG) vem a público manifestar suas preocupações com o presente e o futuro dos idosos no Brasil. É preciso garantir a saúde como direito universal.\nEsperamos que tanto nossos atuais quanto os futuros governantes e legisladores reflitam sobre a necessidade de investir na saúde e na qualidade de vida associada ao envelhecimento.\nDignidade à saúde do idoso!\nRio de Janeiro, 15 de setembro de 2014.\nDisponível em: www.sbgg.org.br. Acesso em: 20 out. 2021 (adaptado).\nO objetivo desse texto é", "alternatives": [{"letter": "A", "text": "A sensibilizar o idoso a respeito dos cuidados com a saude.", "file": null}, {"letter": "B", "text": "Alertar os governantes sobre os cuidados requeridos pelo idoso.", "file": null}, {"letter": "C", "text": "Divulgar o trabalho da Sociedade Brasileira de Geriatria e Gerontologia.", "file": null}, {"letter": "D", "text": "Informar o setor público sobre o retrocesso da legislação destinada à população idosa.", "file": null}, {"letter": "E", "text": "Chamar a atenção da população sobre a qualidade dos serviços de saúde pública para o idoso.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/45"}, {"id": "enem-2023-46-geral", "year": 2023, "number": 46, "discipline": "ciencias-humanas", "language": null, "context": "![](https://enem.dev/2023/questions/46/4eac436b-15be-438c-8219-f2043ab21946.png)", "prompt": "Fotografia da avó bordada\nSCARELI. G. A máquina de costura e os fios da memória Revista Brasileira de Pesquisa (Auto) Biográfica, n. 18 maio-ago, 2021\nA definição de Sertão descrita no bordado associa esse recorte espacial a", "alternatives": [{"letter": "A", "text": "Percursos e roteiros turísticos.", "file": null}, {"letter": "B", "text": "Trajetos e movimentos holísticos.", "file": null}, {"letter": "C", "text": "Vivências e itinerários socioafetivos.", "file": null}, {"letter": "D", "text": "Fronteiras e demarcações territoriais.", "file": null}, {"letter": "E", "text": "Profissões e interesses econômicos.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/46"}, {"id": "enem-2023-47-geral", "year": 2023, "number": 47, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Felizes tempos eram esses! As moças iam à missa de madrugada. De dia ninguém as via e se alguma, em dia de festa, queria passear com a avó ou a tia, havia de ir de cadeirinhas. Bem razão têm os nossos velhos de chorar por esses tempos, em que as filhas não sabiam escrever, e por isso não mandavam nem recebiam bilhetinhos.\n \nNovo correio de Modas, 1853, apud DONEGÁ, A. L.\nPublicar ficção em meado do século XIX,: um estudo de revistas femininas editadas pelos irmãos Laemmert. Campinas, unicamp, 2013 (adaptado)\nNa perspectiva do autor,  as tradições e os costumes sociofamiliares sofreram alterações no século XIX, decorrentes de quais fatores?", "alternatives": [{"letter": "A", "text": "Hábitos de leitura e mobilidade regional.", "file": null}, {"letter": "B", "text": "Circulação de impressos e trânsito religioso.", "file": null}, {"letter": "C", "text": "Valorização da lingua e imigração estrangeira.", "file": null}, {"letter": "D", "text": "Práticas de letramento e transformação cultural.", "file": null}, {"letter": "E", "text": "Flexibilização do ensino e reformismo pedagógico.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/47"}, {"id": "enem-2023-48-geral", "year": 2023, "number": 48, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "No Cerrado, o conhecimento local está sendo cada vez mais subordinado à lógica do agronegócio. De um lado, o capital impõe os conhecimentos biotecnológicos, como mecanismo de universalização de práticas agrícolas e de novas tecnologias, e de outro, o modelo capitalista subordina homens e mulheres à lógica do mercado. Assim, as águas, as sementes, os minerais, as terras (bens comuns) tornam-se propriedade privada. Além do mais, há outros fatores negativos, como a mecanização pesada, a “pragatização” dos seres humanos e não humanos, a violência simbólica, a superexploração, as chuvas de veneno e a violência contra a pessoa.\nCALAÇA, M.; SILVA, E. B.; JESUS, J. N. Territorialização do agronegócio e subordinação\ndo campesinato no Cerrado, Élisée, Rev. Geo. ÚEG, n. 1, jan.-jun. 2021 (adaptado).\nOs elementos descritos no texto, a respeito da territorialização da produção, demonstram que há um:", "alternatives": [{"letter": "A", "text": "Cerco aos camponeses, inviabilizando a manutenção das condições para a vida.", "file": null}, {"letter": "B", "text": "Descaso aos latifundiários, impactando a plantação de alimentos para a exportação.", "file": null}, {"letter": "C", "text": "Desprezo ao assalariado, afetando o engajamento dos sindicatos para o trabalhador.", "file": null}, {"letter": "D", "text": "Desrespeito aos governantes, comprometendo a criação de empregos para o lavrador.", "file": null}, {"letter": "E", "text": "Assédio ao empresariado, dificultando o investimento de maquinários para a produção.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/48"}, {"id": "enem-2023-49-geral", "year": 2023, "number": 49, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "TEXTO I\nCom uma população de 25 milhões de habitantes (cerca de 60% de minorias muçulmanas, principalmente da etnia Uigur), Xinjiang é uma região estratégica para a China. Faz fronteira com oito países, é uma artéria crucial do megaprojeto de infraestrutura chinês Cinturão e Rota e tem as maiores reservas nacionais de carvão e gás natural.\n(NINIO, M. Disponível em: https: oglobo.globo.com. Acesso em: 5 out. 2021 adaptado)\nTEXTO II\nDentre as províncias da Região Oeste, Xinjiang se destaca ao receber mais de 1,7 milhão de migrantes entre 2000 e 2010. O principal motivo desse fluxo migratório é que o governo fornece subsídios à população visando aumentar a proporção de chineses da etnia Han em relação à população local de etnias turca e muçulmana.\nALVES. F.: TOYOSHIMA. S. Disparidade socioeconômica e fluxo migratório chinês: interpretação de eventos contemporâneos segundo os clássicos do desenvolvimento. Revista de Economia Contemporânea. n 1. jan. abr. 2017 (adaptado)\nA política demográfica para a província mencionada nos textos é parte da seguinte ação estratégica do governo chinês:", "alternatives": [{"letter": "A", "text": "Promover a ocupação rural.", "file": null}, {"letter": "B", "text": "Favorecer a liberdade religiosa.", "file": null}, {"letter": "C", "text": "Descentralizar a gestão pública.", "file": null}, {"letter": "D", "text": "Incentivar a pluralidade cultural.", "file": null}, {"letter": "E", "text": "Assegurar a integridade territorial.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/49"}, {"id": "enem-2023-50-geral", "year": 2023, "number": 50, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Superar a história da escravidão como principal marca da trajetória do negro no país tem sido uma tônica daqueles que se dedicam a pesquisar as heranças de origem afro à cultura brasileira. A esse esforço de reconstrução da própria história do país, alia-se agora a criação da plataforma digital Ancestralidades. “A história do negro no Brasil vai continuar sendo contada, e cada passo que a gente dá para trás é um passo que a gente avança”, diz Márcio Black, idealizador da plataforma, sobre o estudo de figuras ainda encobertas pela perspectiva histórica imposta pelos colonizadores da América.\nFIORATI, G. Projeto joga luz sobre negros e revê perspectiva histórica Disponivel em: www1.folha.uol.com.br. Acesso em: 10 nov. 2021 (adaptado)\nEm relação ao conhecimento sobre a formação cultural brasileira, iniciativas como a descrita no texto favorecem o(a)", "alternatives": [{"letter": "A", "text": "Recuperação do tradicionalismo.", "file": null}, {"letter": "B", "text": "Estímulo ao antropocentrismo.", "file": null}, {"letter": "C", "text": "Reforço do etnocentrismo.", "file": null}, {"letter": "D", "text": "Resgate do teocentrismo.", "file": null}, {"letter": "E", "text": "Crítica ao eurocentrismo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/50"}, {"id": "enem-2023-51-geral", "year": 2023, "number": 51, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Escrito durante a Primeira Guerra Mundial, o seguinte trecho faz parte da carta enviada pelo secretário do exterior britânico, Sir Arthur James Balfour, ao banqueiro Lord Rotschild, presidente da Liga Sionista, em 2 de novembro de 1917, a carta ficou conhecida como Declaração Balfour:\n“O governo de Sua Majestade vê com aprovação o estabelecimento na Palestina de um lar nacional para o povo judeu, e fará todos os esforços para facilitar tal objetivo. Nada será feito que possa prejudicar os direitos civis e religiosos das comunidades não judaicas na Palestina.”\nGATTAZ, A. A Guerra da Palestina. São Paulo: Usina do Livro, 2002 (adaptado).\nA análise do resultado do processo em questão revela que o governo inglês foi incapaz de garantir seu objetivo de", "alternatives": [{"letter": "A", "text": "Promover o bem-estar social.", "file": null}, {"letter": "B", "text": "Negociar o apoio muçulmano.", "file": null}, {"letter": "C", "text": "Mediar os conflitos territoriais.", "file": null}, {"letter": "D", "text": "Estimular a cooperação regional.", "file": null}, {"letter": "E", "text": "Combater os governos autocráticos.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/51"}, {"id": "enem-2023-52-geral", "year": 2023, "number": 52, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "TEXTO I\nComo presença consciente no mundo não posso escapar à responsabilidade ética no meu mover-me no mundo. Se sou puro produto da determinação genética ou cultural ou de classe, sou irresponsável pelo que faço no meu mover-me no mundo e, se careço de responsabilidade, não posso falar em ética.\nFREIRE, P. Pedagogia da autonomia: saberes necessários à prática educativa. São Paulo: Paz e Terra, 1996\nТЕХТО II\nPaulo Freire construiu uma pedagogia da esperança. Na sua concepção, a história não é algo pronto e acabado. As estruturas de opressão e as desigualdades, apesar de serem naturalizadas, são sócio e historicamente construídas. Daí a importância de os educandos tomarem consciência da sua realidade para, assim, transformá-la.\nDEMARCHI, J. L. Paulo Freire. Disponivel em: https://diplomatique.org.br. Acesso em: 6 out. 2021 (adaptado).\nCom base no conceito de ética pedagógica presente nos textos, os educandos tornam-se responsáveis pela", "alternatives": [{"letter": "A", "text": "Participação sociopolítica.", "file": null}, {"letter": "B", "text": "Definição estético-cultural.", "file": null}, {"letter": "C", "text": "Competição econômica local.", "file": null}, {"letter": "D", "text": "Manutenção do sistema escolar.", "file": null}, {"letter": "E", "text": "Capacitação de mobilidade individual.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/52"}, {"id": "enem-2023-53-geral", "year": 2023, "number": 53, "discipline": "ciencias-humanas", "language": null, "context": "A cordilheira do Himalaia tem mais de 50 milhões de anos., sendo classificada como a maior cordilheira do planeta. Originário da língua sânscrito, comum na região, seu nome quer dizer “morada da neve”. É possível encontrar nessa cordilheira as quinze maiores montanhas do mundo. Ao todo, existem mais de cem picos, que contam com altitudes bem maiores que 7 000 m. O Everest, considerado o ponto mais alto da Terra, tem nada menos que 8 848 m de altitude, e continua crescendo, aproximadamente, 0,8 mm a cada ano.\n\nDisponível em: https://meioambiente.culturamix.com. Acesso em: 12 nov. 2021 (adaptado).", "prompt": "Qual dinâmica natural é responsável pelo fenômeno apresentado?", "alternatives": [{"letter": "A", "text": "Derrame de lava vulcânica.", "file": null}, {"letter": "B", "text": "Encontro de placas tectônicas.", "file": null}, {"letter": "C", "text": "Ação do intemperismo químico.", "file": null}, {"letter": "D", "text": "Sedimentação de erosão eólica.", "file": null}, {"letter": "E", "text": "Derretimento de geleiras glaciais.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/53"}, {"id": "enem-2023-54-geral", "year": 2023, "number": 54, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Eu poderia concluir que a raiva é um pensamento, que estar com raiva é pensar que alguém é detestável, e que esse pensamento, como todos os outros — assim como Descartes o mostrou —, não poderia residir em nenhum fragmento de matéria. A raiva seria, portanto, espírito. Porém, quando me volto para minha própria experiência da raiva, devo confessar que ela não estava fora do meu corpo, mas inexplicavelmente nele.\nMERLEAU-PONTY, M. Quinta conversa: o homem visto de fora. São Paulo: Martins Fontes, 1948 (adaptado).\nNo que se refere ao problema do corpo, a filosofia cartesiana apresenta-se como contraponto ao entendimento expresso no texto por", "alternatives": [{"letter": "A", "text": "Apresentar uma visão dualista.", "file": null}, {"letter": "B", "text": "Confirmar uma tese naturalista.", "file": null}, {"letter": "C", "text": "Demonstrar uma premissa relativa.", "file": null}, {"letter": "D", "text": "Sustentar um argumento idealista.", "file": null}, {"letter": "E", "text": "Defender uma posição intencionalista.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/54"}, {"id": "enem-2023-55-geral", "year": 2023, "number": 55, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "A diversão é o prolongamento do trabalho sob o capitalismo tardio. Ela é procurada por quem quer escapar ao processo de trabalho mecanizado para se pôr de novo em condições de enfrentá-lo. Mas, ao mesmo tempo, a mecanização atingiu um tal poderio sobre a pessoa em seu lazer e sobre a sua felicidade, ela determina tão profundamente a fabricação das mercadorias destinadas à diversão que essa pessoa não pode mais perceber outra coisa senão as cópias que reproduzem o próprio processo de trabalho…\nADORNO, T; HORKHEIMER, M. Dialética do esclarecimento. Rio de Janeiro: Zahar 1997.\nNo texto, o tempo livre é concebido como", "alternatives": [{"letter": "A", "text": "Consumo de produtos culturais e elaborados no mesmo sistema produtivo do capitalismo", "file": null}, {"letter": "B", "text": "Forma de realizar as diversas potencialidades da natureza humana.", "file": null}, {"letter": "C", "text": "Alternativa para equilibrar tensões psicológicas do dia a dia.", "file": null}, {"letter": "D", "text": "Promoção da satisfação de necessidades artificiais.", "file": null}, {"letter": "E", "text": "Mecanismo de organização do ócio e do prazer.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/55"}, {"id": "enem-2023-56-geral", "year": 2023, "number": 56, "discipline": "ciencias-humanas", "language": null, "context": "![](https://enem.dev/broken-image.svg)\n\nLAERTE. Disponível em: www.laerte.art.br. Acesso em: 23 nov. 2021 (adaptado)", "prompt": "A charge ilustra um anseio presente na sociedade contemporânea, que se caracteriza pela", "alternatives": [{"letter": "A", "text": "Situação de revolta individual.", "file": null}, {"letter": "B", "text": "Satisfação de desejos pessoais.", "file": null}, {"letter": "C", "text": "Participação em ações decisórias.", "file": null}, {"letter": "D", "text": "Permanência em passividade social.", "file": null}, {"letter": "E", "text": "Conivência em interesses partidários.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/56"}, {"id": "enem-2023-57-geral", "year": 2023, "number": 57, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Quem se mete pelo caminho do pedido de perdão deve estar pronto a escutar uma palavra de recusa. Entrar na atmosfera do perdão é aceitar medir-se com a possibilidade sempre aberta do imperdoável. Perdão pedido não é perdão a que se tem direito [devido]. É com o preço destas reservas que a grandeza do perdão se manifesta.\nRICOEUR, P. O perdão pode curar. Disponível em: www.lusosofia.net. Acesso em: 14 out 2019.\nA reflexão sobre o perdão apresentada no texto encontra fundamento na(s)", "alternatives": [{"letter": "A", "text": "Rejeição particular amparada pelo desejo de poder.", "file": null}, {"letter": "B", "text": "Decisão subjetiva determinada pela vontade divina.", "file": null}, {"letter": "C", "text": "Liberdade mitigada pela predestinação do espírito.", "file": null}, {"letter": "D", "text": "Escolhas humanas definidas pelo conhecimento empírico.", "file": null}, {"letter": "E", "text": "Relações interpessoais medidas pela autonomia dos indivíduos.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/57"}, {"id": "enem-2023-58-geral", "year": 2023, "number": 58, "discipline": "ciencias-humanas", "language": null, "context": "A Cavalgada de Sant’Ana é uma expressão da devoção dos vaqueiros à padroeira de Caicó (RN). Nas décadas de 1950 a 1970, esse evento, então denominado Cavalaria, era celebrado pelas pessoas que residiam na zona rural do município de Caicó. Essas pessoas usavam os animais (jegues, mulas e cavalos) como único meio de transporte, sobretudo para se dirigirem à cidade nos dias de feiras, trazendo seus produtos para comercializarem. Estando em Caicó no período da Festa de Sant’Ana, esses agricultores se organizavam em cavalgada até o pátio da Catedral de Sant’Ana para louvar a santa e receber bênção para seus animais. Por volta da década de 1970, com a chegada do automóvel à zona rural do município, essa expressão cultural foi extinta. O meio de transporte utilizando os animais passou a ser substituído por carros, sobretudo caminhonetes e caminhões, que transportavam os camponeses para a cidade em dias de feiras e festas. Desde 2002, um grupo de caicoenses retomou essa expressão cultural e, em conjunto com a associação dos vaqueiros, realiza no primeiro domingo da Festa a Cavalgada de Sant’Ana. O evento, além de contar com a participação dos cavaleiros que residem nas zonas rurais, atrai também pessoas que residem em Caicó, cidades vizinhas e amantes das vaquejadas.\n\nFESTA DE SANT’ANA. Disponivel em: http://portal.iphan.gov.br Acesso em: 12 out. 2021 (adaptado).", "prompt": "As mudanças culturais mencionadas no texto caracterizam-se pela presenca de", "alternatives": [{"letter": "A", "text": "Elementos tradicionais e modernos em torno de uma crença religiosa.", "file": null}, {"letter": "B", "text": "Argumentos teológicos e históricos em consequência de uma ordem papal.", "file": null}, {"letter": "C", "text": "Fundamentos estéticos e etnográficos em função de uma cerimônia clerical.", "file": null}, {"letter": "D", "text": "Práticas corporais e esportivas em decorrência de uma imposição eclesiástica.", "file": null}, {"letter": "E", "text": "Discursos filosóficos e antropológicos em resultado de uma determinação paroquial.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/58"}, {"id": "enem-2023-59-geral", "year": 2023, "number": 59, "discipline": "ciencias-humanas", "language": null, "context": "Do século XVI em diante, pelo menos nas classes mais altas, o garfo passou a ser usado como utensílio para comer, chegando através da Itália primeiramente à França e, em seguida, à Inglaterra e à Alemanha, depois de ter servido, durante algum tempo, apenas para retirar alimentos sólidos da travessa. Henrique III introduziu-o na França, trazendo-o provavelmente de Veneza. Seus cortesãos não foram pouco ridicularizados por essa maneira “afetada” de comer e, no princípio, não eram muito hábeis no uso do utensílio: pelo menos se dizia que metade da comida cala do garfo no caminho do prato à boca. Em data tão recente como o século XVII, o garfo era ainda basicamente artigo de luxo, geralmente feito de prata ou ouro.\n\nELIAS. N. **O processo civilizador**: uma história dos costumes. Rio de Janeiro: Zahar, 1994.", "prompt": "O processo social relatado indica a formação de uma etiqueta que tem como principio a", "alternatives": [{"letter": "A", "text": "Distinção das classes sociais.", "file": null}, {"letter": "B", "text": "Valorização de habitos de higiene.", "file": null}, {"letter": "C", "text": "Exaltação da cultura mediterrânea.", "file": null}, {"letter": "D", "text": "Consagração de tradições medievais.", "file": null}, {"letter": "E", "text": "Disseminação de produtos manufaturados.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/59"}, {"id": "enem-2023-60-geral", "year": 2023, "number": 60, "discipline": "ciencias-humanas", "language": null, "context": "Negar o pedido por dinheiro indispensável para necessidades pessoais ou comprar bens usando o nome da pessoa sem o consentimento dela. Ameaçar o corte de recursos dependendo de atitudes pessoais, esconder documentos ou trocar senhas do banco sem avisar. Ou, ainda, proibir a pessoa de trabalhar ou destruir seus pertences. As histórias são comuns, mas às vezes não são reconhecidas como abuso. Mas é uma das cinco formas de conduta contra a mulher previstas na Lei Maria da Penha.\n\nLEWGOY. J. **Conduta quase invisível destrói a vida de mulheres**. Disponível em: https://valorinveste.globo.com. Acesso em: 23 out. 2021 (adaptado).", "prompt": "O texto apresenta tipos de conduta sujeitos a punição, conforme previsto na Lei Maria da Penha, porque consistem em formas de", "alternatives": [{"letter": "A", "text": "Ação difamatória.", "file": null}, {"letter": "B", "text": "Desvio comportamental.", "file": null}, {"letter": "C", "text": "Expressão preconceituosa.", "file": null}, {"letter": "D", "text": "Violência patrimonial.", "file": null}, {"letter": "E", "text": "Desentendimento matrimonial.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/60"}, {"id": "enem-2023-61-geral", "year": 2023, "number": 61, "discipline": "ciencias-humanas", "language": null, "context": "Por trás da “mágica” do Google Assistant de sua capacidade de interpretar 26 idiomas está uma enorme equipe de linguistas distribuídos globalmente, trabalhando como subcontratados, que devem rotular tediosamente os dados de treinamento para que funcione. Eles ganham baixos salários e são rotineiramente forçados a trabalhar horas extras não remuneradas. A inteligência artificial não funciona como um pozinho mágico. Ela funciona por meio de trabalhadores que treinam algoritmos incansavelmente até que eles automatizem seus próprios trabalhos.\n\n**A Inteligência Artificial (IA) da economia freelancer está vindo atrás de você**. Disponível em: https://mittechreview.com.br. Acesso em: 6 out. 2021 (adaptado).", "prompt": "O texto critica a mudança tecnológica em razão da seguinte consequência:", "alternatives": [{"letter": "A", "text": "Diversificação da função.", "file": null}, {"letter": "B", "text": "Mobilidade da população.", "file": null}, {"letter": "C", "text": "Autonomia do empregado.", "file": null}, {"letter": "D", "text": "Concentração da produção.", "file": null}, {"letter": "E", "text": "Invisibilidade do profissional.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/61"}]') on conflict(id) do nothing;
insert into orbit_private.answer_keys select * from jsonb_populate_recordset(null::orbit_private.answer_keys,'[{"question_id": "enem-2023-31-geral", "correct_letter": "C"}, {"question_id": "enem-2023-32-geral", "correct_letter": "A"}, {"question_id": "enem-2023-33-geral", "correct_letter": "A"}, {"question_id": "enem-2023-35-geral", "correct_letter": "A"}, {"question_id": "enem-2023-36-geral", "correct_letter": "A"}, {"question_id": "enem-2023-37-geral", "correct_letter": "C"}, {"question_id": "enem-2023-38-geral", "correct_letter": "A"}, {"question_id": "enem-2023-39-geral", "correct_letter": "C"}, {"question_id": "enem-2023-40-geral", "correct_letter": "B"}, {"question_id": "enem-2023-41-geral", "correct_letter": "B"}, {"question_id": "enem-2023-42-geral", "correct_letter": "E"}, {"question_id": "enem-2023-43-geral", "correct_letter": "A"}, {"question_id": "enem-2023-44-geral", "correct_letter": "A"}, {"question_id": "enem-2023-45-geral", "correct_letter": "E"}, {"question_id": "enem-2023-46-geral", "correct_letter": "C"}, {"question_id": "enem-2023-47-geral", "correct_letter": "D"}, {"question_id": "enem-2023-48-geral", "correct_letter": "A"}, {"question_id": "enem-2023-49-geral", "correct_letter": "E"}, {"question_id": "enem-2023-50-geral", "correct_letter": "E"}, {"question_id": "enem-2023-51-geral", "correct_letter": "C"}, {"question_id": "enem-2023-52-geral", "correct_letter": "A"}, {"question_id": "enem-2023-53-geral", "correct_letter": "B"}, {"question_id": "enem-2023-54-geral", "correct_letter": "A"}, {"question_id": "enem-2023-55-geral", "correct_letter": "A"}, {"question_id": "enem-2023-56-geral", "correct_letter": "C"}, {"question_id": "enem-2023-57-geral", "correct_letter": "E"}, {"question_id": "enem-2023-58-geral", "correct_letter": "A"}, {"question_id": "enem-2023-59-geral", "correct_letter": "A"}, {"question_id": "enem-2023-60-geral", "correct_letter": "D"}, {"question_id": "enem-2023-61-geral", "correct_letter": "E"}]') on conflict(question_id) do nothing;
