insert into public.orbit_questions(id,year,number,discipline,language,context,prompt,alternatives,source_url) select id,year,number,discipline,language,context,prompt,alternatives,source_url from jsonb_populate_recordset(null::public.orbit_questions,'[{"id": "enem-2023-62-geral", "year": 2023, "number": 62, "discipline": "ciencias-humanas", "language": null, "context": "Enormes alto-falantes sul-coreanos instalados na fronteira com o Norte costumavam transmitir desde canções em estilo K-pop (como é chamado o pop sul-coreano) até boletins climáticos e noticiário crítico ao vizinho comunista. O Norte costuma praticar atividade semelhante, transmitindo por seus alto-falantes discursos críticos a Seul e aliados. Durante os anos 1980, o governo sul-coreano construiu um mastro de 97 metros de altura para hastear sua bandeira no povoado de Daesong-dong, na fronteira com o Norte. O Norte respondeu com a construção de um mastro ainda mais alto (160 m) na cidade fronteiriça de Gijung-dong. “Essas demonstrações são uma válvula de escape competitiva e importante entre os dois lados, fora de um possível conflito militar”, diz o analista Ankit Panda.\n\nTAN, Y. **Disputa de mastros e alto-falantes com K-pop:** as pequenas picuinhas do conflito entre as Coreias. Disponível em: www.bbc.com. Acesso em: 7 nov. 2021 (adaptado).", "prompt": "Os atos de competição citados têm suas origens históricas vinculadas a um contexto de", "alternatives": [{"letter": "A", "text": "Domínio cultural-identitário de atores sociais.", "file": null}, {"letter": "B", "text": "Disputas étnico-raciais de povos tradicionais.", "file": null}, {"letter": "C", "text": "Divergências político-ideológicas de agentes estatais.", "file": null}, {"letter": "D", "text": "Imposição econômico-financeira de empresas privadas", "file": null}, {"letter": "E", "text": "Protestos ecológico-sustentáveis de entidades ambientais", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/62"}, {"id": "enem-2023-63-geral", "year": 2023, "number": 63, "discipline": "ciencias-humanas", "language": null, "context": "Seda, madeiras aromáticas e têxteis, obras de arte, lã, cristais e muitas, muitas peças de porcelana chegaram ao Brasil ao longo dos séculos XVII e XVIII. A opulência proporcionada pelo ouro fez com que esses itens fossem ainda mais presentes em cidades mineiras como Ouro Preto, Mariana e Sabará. Esses objetos inspiraram a criação das chinesices, termo que designa um tipo de arte que evoca motivos chineses, presentes em várias igrejas barrocas de Minas Gerais. No Brasil, é bem provável que a inspiração para as pinturas nas igrejas barrocas com pássaros, elefantes, tigres, mandarins e pagodes tenha sido tirada de gravuras, tecidos, móveis e, principalmente, das porcelanas chinesas que circulavam livremente em uma sociedade enriquecida pelo comércio do ouro e pedras preciosas.\n\nMARIUZZO, P. **Estudos interdisciplinares ampliam conhecimento sobre chinesice no barroco mineiro**. Disponível em: http://cienciaecultura.bvs.br. Acesso em: 23 nov. 2021 (adaptado).", "prompt": "O desenvolvimento do processo artístico descrito no texto foi possível pelo(a)", "alternatives": [{"letter": "A", "text": "Representação arquitetônica.", "file": null}, {"letter": "B", "text": "Intercâmbio transcontinental.", "file": null}, {"letter": "C", "text": "Dependência econômica.", "file": null}, {"letter": "D", "text": "Intervenção estatal.", "file": null}, {"letter": "E", "text": "Padrão estético.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/63"}, {"id": "enem-2023-64-geral", "year": 2023, "number": 64, "discipline": "ciencias-humanas", "language": null, "context": "**Txai Suruí, liderança da Juventude Indígena, profere seu discurso na abertura da COP-26**\n\n“O clima está esquentando, os animais estão desaparecendo, os rios estão morrendo e nossas plantações não florescem como no passado. A Terra está falando: ela nos diz que não temos mais tempo.”\n\nVICK, M. **Quais são as conquistas do movimento indígena na COP-26**. Disponível em: www.nexojornal.com.br. Acesso em: 10 nov. 2021 (adaptado).", "prompt": "O discurso da líder indígena explicita um problema global relacionado ao(à)", "alternatives": [{"letter": "A", "text": "Manejo tradicional.", "file": null}, {"letter": "B", "text": "Reciclagem residual.", "file": null}, {"letter": "C", "text": "Consumo consciente.", "file": null}, {"letter": "D", "text": "Exploração predatória.", "file": null}, {"letter": "E", "text": "Reaproveitamento energético.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/64"}, {"id": "enem-2023-65-geral", "year": 2023, "number": 65, "discipline": "ciencias-humanas", "language": null, "context": "![](https://enem.dev/broken-image.svg)\n\nNas reportagens publicadas sobre a inauguração de Museu de Arte de São Paulo, em 1947, quando ele ainda ocupava um edifício na rua Sete de Abril, Lina Bo Bardi não foi mencionada nenhuma vez. A arquiteta era responsável pelo projeto do museu que mudaria para sempre a posição de São Paulo no circuito mundial das artes. Mas não houve nenhum registro disso. O louvor se concentrou em seu marido e parceiro profissional, o respeitado crítico de arte Pietro Maria Bardi. Passados 75 anos, a mulher então ignorada recebeu um Leão de Ouro póstumo, a maior homenagem da Bienal de Arquitetura de Veneza, e tem agora sua história contada em duas biografias de peso, que procuram destrinchar uma carreira marcada pela ousadia e pela contradição.\n\nPORTO, W. L**ina Bo Bardi tem sua arquitetura contraditória destrinchada em biografias**. Disponível em: www1.folha.uol.com.br. Acesso em: 10 nov. 2021 (adaptado).", "prompt": "As transformações pelas quais passaram as sociedades ocidentais e que possibilitaram o reconhecimento recente do trabalho da arquiteta mencionada no texto foram resultado das mobilizações sociais pela", "alternatives": [{"letter": "A", "text": "Equidade de genêro.", "file": null}, {"letter": "B", "text": "Liberdade de expressão.", "file": null}, {"letter": "C", "text": "Admissibilidade de voto.", "file": null}, {"letter": "D", "text": "Igualdade de oportunidade.", "file": null}, {"letter": "E", "text": "Reciprocidade de tratamento.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/65"}, {"id": "enem-2023-66-geral", "year": 2023, "number": 66, "discipline": "ciencias-humanas", "language": null, "context": "**ТЕХТО I**\n\nComo é horrível ver um filho comer e perguntar: “Tem mais?” Esta palavra “tem mais” fica oscilando dentro do cérebro de uma mãe que olha as panela e não tem mais.\n\nJESUS, C. M. Quarto de despejo: diário de uma favelada. São Paulo: Ática. 2014.\n\n**ТЕХТО ІІ**\n\nA experiência de ver os filhos com fome na década de 1950, descrita por Carolina, é vivida no Brasil de 2021 por uma moradora de Petrolândia, em Pernambuco. “Eu trabalhava de ajudante de cabeleireira, mas a moça que tinha o salão fechou. Eu vinha me sustentando com o auxílio que tinha, mas agora eu não fui contemplada. Às vezes as pessoas me ajudam com alimentos para os meus filhos. De vez em quando, eu acho algum bico para fazer, mas é muito raro. Tem dias que não tenho nem o leite da minha bebê.”\n\nCARRANÇA, T. “Até o feijão nos esqueceu”: o livro de 1960 que poderia ter sido escritonas favelas de 2021.\n\nDisponível em: www.bbc.com. Acesso em: 6 out. 2021 (adaptado).", "prompt": "Considerando a realidade brasileira, os textos se aproximam ao apresentarem uma reflexão sobre o(a)", "alternatives": [{"letter": "A", "text": "Recorrência da miséria.", "file": null}, {"letter": "B", "text": "Planejamento da saúde.", "file": null}, {"letter": "C", "text": "Superação da escassez.", "file": null}, {"letter": "D", "text": "Constância da economia.", "file": null}, {"letter": "E", "text": "Romantização da carência.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/66"}, {"id": "enem-2023-67-geral", "year": 2023, "number": 67, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "No sul da Bahia, desde o século XVIII, tem-se registros de um tipo de sistema agroflorestal. Até hoje, esse sistema é característica marcante da paisagem da região, conhecido como cabruca, que consiste no cultivo do cacau à sombra do dossel da floresta nativa. Esse sistema de cultivo do cacau (graças à tolerância da espécie à sombra) é considerado amigável para a vida silvestre, pois apresenta superioridade em termos de conservação da biodiversidade quando comparado com outras plantações tropicais (monoculturas de dendê, seringa ou café), agricultura ou pastagens.\nSOLLBERG, I.; SCHIAVETTI, A. MORAES M. E. B. Manejo agrícola no Refúgio de Vida Silvestre de Una: agroflorestas como uma perspectiva de conservação. Revista Árvore. n. 2, 2014 (adaptado)\nA prática produtiva apresentada é um exemplo de", "alternatives": [{"letter": "A", "text": "Difusão comercial de lavouras temporárias.", "file": null}, {"letter": "B", "text": "Utilização sustentável dos recursos naturais.", "file": null}, {"letter": "C", "text": "Ampliação tecnológica da pecuária intensiva.", "file": null}, {"letter": "D", "text": "Padronização alimentar dos povos tradicionais.", "file": null}, {"letter": "E", "text": "Modernização logística de plantios convencionais.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/67"}, {"id": "enem-2023-68-geral", "year": 2023, "number": 68, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "O masseiro, a mulher, e quatro filhos, dormindo numa tapera de quatro paredes de caixão, coberta de zinco. A água do mangue, na maré cheia, ia dentro de casa. Os maruins de noite encalombavam o corpo dos meninos. O mangue tinha ocasião que fedia, e os urubus faziam ponto por ali atrás dos petiscos. Perto da rua lavavam couro de boi, pele de bode para o curtume de um espanhol. Morria peixe envenenado e quando a maré secava os urubus enchiam o papo, ciscavam a lama, passeando banzeiros pelas biqueiras dos mocambos no Recife.\nRÊGO. J. L. O moleque Ricardo. Rio de Janeiro. J. Olympio, 1966 (adaptado).\nA aglomeração urbana representada no texto resulta em", "alternatives": [{"letter": "A", "text": "Conservação do meio rural.", "file": null}, {"letter": "B", "text": "Crescimento da vegetação ciliar.", "file": null}, {"letter": "C", "text": "Interferência do espaço geográfico.", "file": null}, {"letter": "D", "text": "Equilíbrio do ambiente das cidades.", "file": null}, {"letter": "E", "text": "Controle da proliferação dos animais.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/68"}, {"id": "enem-2023-69-geral", "year": 2023, "number": 69, "discipline": "ciencias-humanas", "language": null, "context": "Elas foram as pioneiras dos direitos das mulheres no Afeganistão. Defensoras ferrenhas da lei, buscaram justiça para os mais marginalizados. Mas, agora, mais de 220 juízas afegãs estão escondidas por medo de retaliação sob o regime do Talibã. Uma delas condenou centenas de homens por violência contra as mulheres, incluindo estupro, assassinato e tortura. Mas poucos dias depois que o Talibã assumiu o controle de sua cidade e milhares de criminosos condenados foram libertados da prisão, as ameaças de morte começaram. O país sempre foi considerado um dos lugares mais difíceis e perigosos do mundo para as mulheres. De acordo com estudos de organizações não governamentais, cerca de 87% das mulheres e meninas serão vítimas de abuso durante a vida.\n\nDisponível em: https://g1.globo.com. Acesso em: 12 out. 2021 (adaptado).", "prompt": "O texto evidencia situação representativa de", "alternatives": [{"letter": "A", "text": "Afronta às estruturas sociais.", "file": null}, {"letter": "B", "text": "Desprezo aos valores religiosos.", "file": null}, {"letter": "C", "text": "Transgressão às normas morais.", "file": null}, {"letter": "D", "text": "Desrespeito à dignidade humana.", "file": null}, {"letter": "E", "text": "Oposição aos princípios hierárquicos.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/69"}, {"id": "enem-2023-70-geral", "year": 2023, "number": 70, "discipline": "ciencias-humanas", "language": null, "context": "No cemitério, a sociedade religiosa encarregada do funeral, aterrorizada, apressou a cerimônia de tal forma que a mãe de Herzog perdeu o momento em que o caixão do filho começou a ser coberto pela terra. Quatro jornalistas que estavam presos no DOI chegaram para assistir ao sepultamento. Um se afastara, chorando. Dizia: Eles matam, eles matam! Não pergunte nada. Não podemos dizer nada. Eles matam mesmo. Falava-se baixo. Ouviram-se dois curtos discursos. O primeiro, da atriz Ruth Escobar: Até quando vamos suportar tanta violência? Até quando vamos continuar enterrando nossos mortos em silêncio? No segundo, Audálio Dantas recitou o Navio negreiro, de Castro Alves: _Senhor Deus dos desgraçados / Dizei-me Vós, Senhor Deus / Se é mentira, se é verdade, / Tanto horror perante os céus._\n\nGASPARI, E. A ditadura encurralada. São Paulo: Cia. das Letras, 2004.", "prompt": "O acontecimento descrito no texto, ocorrido em meados dos anos 1970, atesta a seguinte característica do regime político-institucional vigente:", "alternatives": [{"letter": "A", "text": "Incorporação da estética popular para justificar o ideal de integração nacional.", "file": null}, {"letter": "B", "text": "Afirmação da estratégia psicossocial para favorecer o objetivo de propaganda cívica.", "file": null}, {"letter": "C", "text": "Institucionalização de mecanismos repressivos para eliminar os focos de resistência.", "file": null}, {"letter": "D", "text": "Adoção de cerimoniais públicos para controlar as manifestações de grupos opositores.", "file": null}, {"letter": "E", "text": "Estatização de meios de comunicação para selecionar a divulgação de atos governamentais.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/70"}, {"id": "enem-2023-71-geral", "year": 2023, "number": 71, "discipline": "ciencias-humanas", "language": null, "context": "Alternativas logísticas estão servindo de instrumentos que ativam os mercados especuladores de terras nas diferentes regiões da Amazônia e constituem em indicadores utilizados por diferentes atores para defender ou denunciar o avanço da cultura da soja na região e, com ela, a retomada do desmatamento. É evidente que o crescimento do desmatamento tem a ver também com a expansão da soja, porém atribuir a ela o fator principal parece não totalmente correto. Parto da compreensão central de que a lógica que gera o desmatamento está articulada pelo tripé grileiros, madeireiros e pecuaristas.\n\nOLIVEIRA, A. U. A Amazônia e a nova geografia da produção da soja. **Terra Livre**, n. 26, jan.-jun. 2006 (adaptado).", "prompt": "Na visão do autor, o problema central da situação descrita é desencadeado pela", "alternatives": [{"letter": "A", "text": "Apropriação de áreas devolutas.", "file": null}, {"letter": "B", "text": "Sonegação de impostos federais.", "file": null}, {"letter": "C", "text": "Incorporação de exportação ilegal.", "file": null}, {"letter": "D", "text": "Desoneração de setores produtivos.", "file": null}, {"letter": "E", "text": "Flexibilização de legislação ambiental.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/71"}, {"id": "enem-2023-72-geral", "year": 2023, "number": 72, "discipline": "ciencias-humanas", "language": null, "context": "**TEXTO I**\n\nPor hora, apenas os mais abastados poderão sonhar em viajar ao espaço, seja por um foguete ou por um avião híbrido, mas toda a população global poderá sentir os efeitos dessas viagens e avanços tecnológicos. Para uma aventura dessas, as empresas tiveram que criar novas tecnologias, materiais e softwares, o que podem, em algum momento, voltar para a sociedade. A câmera fotográfica, hoje comum no mundo, antes foi uma invenção para ser usada em telescópios e o titânio, usado até na medicina, foi desenvolvido para a construção de foguetes.\n\nORLANDO, G. **Corrida espacial dos bilionários pode trazer vantagens para todos**. Disponível em: https://noticias.r7.com/. Acesso em: 5 nov. 2021 (adaptado).\n\n**TEXTO II**\n\n![](https://enem.dev/2023/questions/72/19b09a90-8898-4d03-b11a-eedae69b1e1d.png)\n\nCAZO. Disponível em: www.humorpolitico.com.br. Acesso em: 5 nov. 2021.", "prompt": "Os textos apresentam perspectivas da nova corrida espacial que revelam, respectivamente:", "alternatives": [{"letter": "A", "text": "Dependência e progresso.", "file": null}, {"letter": "B", "text": "Expectativa e desconfiança.", "file": null}, {"letter": "C", "text": "Angústia e adaptação.", "file": null}, {"letter": "D", "text": "Pioneirismo e retrocesso.", "file": null}, {"letter": "E", "text": "Receio e civilidade.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/72"}, {"id": "enem-2023-73-geral", "year": 2023, "number": 73, "discipline": "ciencias-humanas", "language": null, "context": "Os séculos XV e XVI, quando se vão desmoronando as estruturas socioeconômicas da Idade Média perante os novos imperativos da Época moderna, constituem um momento-chave na história florestal de toda a Europa Ocidental. Abre-se, genericamente, um longo período de “crise florestal”, que se manifesta com acuidade nos países onde mais se desenvolvem as atividades industriais e comerciais. As necessidades em produtos lenhosos aumentam drasticamente com o crescimento do consumo nos mercados urbanos e nas regiões onde progridem a metalurgia e a construção naval, além da sua utilização na vida quotidiana de toda a população.\n\nDEVY-VARETA, N. Para uma geografia histórica da floresta portuguesa. **Revista da Faculdade de Letras – Geografia,** n. 1, 1986 (adaptado).", "prompt": "Qual acontecimento do período contribuiu diretamente para o agravamento da situação descrita?", "alternatives": [{"letter": "A", "text": "O processo de expansão marítima.", "file": null}, {"letter": "B", "text": "A eclosão do renascimento cultural.", "file": null}, {"letter": "C", "text": "A concretização da centralização política.", "file": null}, {"letter": "D", "text": "O movimento de reformas religiosas.", "file": null}, {"letter": "E", "text": "A manutenção do sistema feudal.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/73"}, {"id": "enem-2023-74-geral", "year": 2023, "number": 74, "discipline": "ciencias-humanas", "language": null, "context": "Tahuantinsuyu — nome do Império Inca em quéchua — era dividido em quatro partes ou suyus: Chinchaysuyu (noroeste do Peru e Equador), Antisuyu (parte amazônica do império), Collasuyu (atual Bolívia) e Condesuyu (costa do Oceano Pacífico) e tinha Cuzco, no atual Peru, como sua capital imperial. Oficialmente, todas as etnias dominadas pelos incas deveriam adotar a língua quéchua, adorar o Sapa Inca e o Sol e pagar taxas em forma de horas de trabalhos periódicos. No entanto, pode-se dizer que o Império Inca era como um mosaico cultural em que vários e diferentes grupos étnicos adoravam o Sapa Inca e o Sol mas, simultaneamente, continuavam a adorar seus deuses locais e também a falar em suas línguas nativas.\n\nMARTINS, C. **Os incas e os tahuantinsuyu**: apresentação. Disponível em: http://antigo.anphlac.org. Acesso em: 6 out. 2021 (adaptado).", "prompt": "Ao comparar, no texto, a vertente da dominação territorial com os aspectos culturais, os incas tinham uma postura", "alternatives": [{"letter": "A", "text": "Aceitável no que alude aos direitos humanos.", "file": null}, {"letter": "B", "text": "Admissível no que remete às crenças coloniais.", "file": null}, {"letter": "C", "text": "Tolerável no que se refere aos regimes tributários.", "file": null}, {"letter": "D", "text": "Flexível no que diz respeito aos costumes religiosos.", "file": null}, {"letter": "E", "text": "Compreensível no que concerne às normas laborais.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/74"}, {"id": "enem-2023-75-geral", "year": 2023, "number": 75, "discipline": "ciencias-humanas", "language": null, "context": "A torcida do Fluminense inicia um movimento para mudar a letra de uma das músicas mais populares das arquibancadas tricolores. Grupos pedem a remoção do termo “mulambo imundo”, em uma provocação direta ao Flamengo. Mulambo é um termo que surgiu em Angola, na época da escravatura, e eles eram chamados de mulambos pelos senhores de engenho, os patrões das fazendas.\n\nDisponível em: https://oglobo.globo.com. Acesso em: 23 nov. 2021.", "prompt": "Qual mudança no comportamento social a proposta reportada no texto reflete?", "alternatives": [{"letter": "A", "text": "A Rejeição de costumes elitistas.", "file": null}, {"letter": "B", "text": "Repulsão de condutas misóginas.", "file": null}, {"letter": "C", "text": "Condenação do preconceito racial.", "file": null}, {"letter": "D", "text": "Criminalização de práticas homofóbicas", "file": null}, {"letter": "E", "text": "Contestação do comportamento machista.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/75"}, {"id": "enem-2023-76-geral", "year": 2023, "number": 76, "discipline": "ciencias-humanas", "language": null, "context": "![](https://enem.dev/2023/questions/76/4b3eb253-249e-4bc3-bb08-5d48b44c53c1.jpg)\n\nDisponível em: www.insper.edu.br. Acesso em: 27 set. 2021 (adaptado).", "prompt": "Qual fator foi determinante para a mudança do indicador apresentado no gráfico?", "alternatives": [{"letter": "A", "text": "Flexibilização legal da prática de aborto.", "file": null}, {"letter": "B", "text": "Envelhecimento da população brasileira.", "file": null}, {"letter": "C", "text": "Crescimento dos casos de gravidez precoce.", "file": null}, {"letter": "D", "text": "Participação feminina no mercado de trabalho.", "file": null}, {"letter": "E", "text": "Diminuição dos benefícios na licença-maternidade.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/76"}, {"id": "enem-2023-77-geral", "year": 2023, "number": 77, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Havia já muito tempo que a Europa desfrutava os benefícios da vacina e arrancava à morte milhares de inocentes, condenados a serem vítimas do terrível flagelo das bexigas, e o governo de Portugal nunca se lembrara de transmitir ao Brasil a mais útil das descobertas humanas, quando aliás nenhum país mais do que ele carecia deste salutar invento ou se atendesse às vantagens da população ou ao perdimento de imensas somas na mortandade contínua de escravos, que este flagelo devorava. O certo é que mais ocupado de seu ouro que de seus habitantes, Portugal, como em outros muitos casos, esperou que o Brasil por seu próprio impulso remediasse a este mal.\nPEREIRA, J. C. 12 jan. 1828 apud LOPES, M. B.; POLITO, R. Para uma história da vacina no Brasil: um manuscrito inédito de Norberto e Macedo. História, Ciências, Saúde – Manguinhos, n. 2, abr. -jun. 2007 (adaptado).\nEscrito em 1828, o texto expressa a seguinte ideia de origem iluminista:", "alternatives": [{"letter": "A", "text": "As leis observáveis regem o mundo material.", "file": null}, {"letter": "B", "text": "O monarca racional promove a sociedade justa.", "file": null}, {"letter": "C", "text": "O direito natural justifica a liberdade dos homens.", "file": null}, {"letter": "D", "text": "A produção da terra garante a riqueza das nações.", "file": null}, {"letter": "E", "text": "A responsabilidade dos governantes assegura a saúde dos povos.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/77"}, {"id": "enem-2023-78-geral", "year": 2023, "number": 78, "discipline": "ciencias-humanas", "language": null, "context": "Os movimentos da agricultura urbana no Rio de Janeiro vêm crescendo nos últimos vinte anos, tanto por meio de reproduções de modelos de vida antigos, vinculados ao resgate dos próprios costumes, como — e cada vez mais — são revelados hábitos inventivos nos quais moradores urbanos de diferentes classes sociais, sem nenhuma referência anterior com o campo, passam a se dedicar a essas atividades. Ao possibilitar o acesso ao plantio e, consequentemente, à alimentação, permite-se uma nova relação com o que se come, reduzindo o percurso da cadeia produtiva e aproximando produtores de consumidores, pois ambos se confundem nas experiências de agricultura urbana.\n\nPORTILHO, M.; RODRIGUES, C. G. O.; FERNANDEZ, A. C. F. Cultivando relações no arranjo local da Penha: a mobilização de mulheres a partir das práticas de agricultura urbana na favela. Cidades, Comunidades e Territórios, n. 42, jun. 2021.", "prompt": "A prática agrícola destacada no texto apresenta como vantagem no espaço urbano a", "alternatives": [{"letter": "A", "text": "Ocupação de lugares ociosos.", "file": null}, {"letter": "B", "text": "Densificação da área central.", "file": null}, {"letter": "C", "text": "Valorização do mercado externo.", "file": null}, {"letter": "D", "text": "Priorização de insumos químicos.", "file": null}, {"letter": "E", "text": "Mecanização de técnicas de cultivo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/78"}, {"id": "enem-2023-79-geral", "year": 2023, "number": 79, "discipline": "ciencias-humanas", "language": null, "context": "**TEXTO I**\n\nGerineldo dorme porque já está conformado com o seu mundo. Porque já sabe tudo o que lhe pode acontecer após haver submetido todos os objetos que o rodeiam a um minucioso inventário de possibilidades. Seu apartamento, mais que um apartamento, é uma teoria de sorte e de azar. Melhor que ninguém, Gerineldo conhece o coeficiente da dilatação de suas janelas e mantém marcado no termômetro, com uma linha vermelha, o ponto em que se quebrarão os vidros, despedaçados em estilhaços de morte. Sabe que os arquitetos e os engenheiros já previram tudo, menos o que nunca já aconteceu.\n\nMARQUEZ, G. G. O pessimista. In: Textos do Caribe. Rio de Janeiro: Record, 1981.\n\n**ТЕХТО II**\n\nA situação é o sujeito inteiro (ele não é nada a não ser a sua situação) e é também a coisa inteira (nunca há mais nada senão as coisas). É o sujeito a elucidar as coisas pela sua própria superação, se assim quisermos; ou são as coisas a reenviar ao sujeito a imagem dele. É a total facticidade, a contingência absoluta do mundo, do meu nascimento, do meu lugar, do meu passado, dos meus redores — e é a minha liberdade sem limites que faz com que haja para mim uma facticidade.\n\nSARTRE, J.-P. O ser e o nada: ensaio de ontologia fenomenológica. Petrópolis: Vozes, 1997 (adaptado).", "prompt": "A postura determinista adotada pelo personagem Gerineldo contrasta com a ideia existencialista contida no pensamento filosófico de Sartre porque", "alternatives": [{"letter": "A", "text": "Evidencia a manifestação do inconsciente.", "file": null}, {"letter": "B", "text": "Nega a possibilidade de transcendência.", "file": null}, {"letter": "C", "text": "Contraria o conhecimento difuso.", "file": null}, {"letter": "D", "text": "Sustenta a fugacidade da vida.", "file": null}, {"letter": "E", "text": "Refuta a evolução biológica.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/79"}, {"id": "enem-2023-80-geral", "year": 2023, "number": 80, "discipline": "ciencias-humanas", "language": null, "context": "O Golpe Militar de 1964 foi implacável no combate ao que restava das Ligas Camponesas, generalizadas na década anterior. No entanto, em relação aos sindicatos, sua atitude foi ambígua. Por meio de acordos com os Estados Unidos, foram concebidos centros sindicais e cursos de liderança com base em princípios conservadores e ministrados por membros da Igreja Católica.\n\nDEL PRIORE, M.; VENÂNCIO, R. Uma história da vida rural no Brasil. Rio de Janeiro: Ediouro, 2006 (adaptado).", "prompt": "Os sindicatos rurais foram tratados da forma descrita no texto porque o governo pretendia utiliza-los para", "alternatives": [{"letter": "A", "text": "Controlar as tensões políticas.", "file": null}, {"letter": "B", "text": "Limitar a legislação trabalhista.", "file": null}, {"letter": "C", "text": "Divulgar o programa populista.", "file": null}, {"letter": "D", "text": "Regularizar a propriedade da terra.", "file": null}, {"letter": "E", "text": "Estimular a oferta de mão de obra.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/80"}, {"id": "enem-2023-81-geral", "year": 2023, "number": 81, "discipline": "linguagens", "language": null, "context": "", "prompt": "A economia das ilegalidades se reestruturou com o desenvolvimento da sociedade capitalista. A ilegalidade dos bens foi separada da ilegalidade dos direitos. Divisão que corresponde a uma oposição de classes, pois, de um lado, a ilegalidade mais acessível às classes populares será a dos bens — transferência violenta das propriedades; de outro, à burguesia, então, se reservará a ilegalidade dos direitos: a possibilidade de desviar seus próprios regulamentos e suas próprias leis; e essa grande redistribuição das ilegalidades se traduzirá até por uma especialização dos circuitos judiciários; para as ilegalidades de bens — para o roubo — os tribunais ordinários e os castigos; para as ilegalidades de direitos — fraudes, evasões fiscais, operações comerciais irregulares — jurisdições especiais com transações, acomodações, multas atenuadas etc.\n FOUCAULT, M. Vigiar e punir: nascimento da prisão. Petropolis: Vozes, 1987 \nO texto apresenta uma relação de cálculo politico-econômico que caracteriza o poder punitivo por meio da • gestão das ilicitudes pelo sistema judicial. aplicação das sanções pelo modelo equânime. supressão dos crimes pela penalização severa. regulamentação dos privilégios pela justiça social. repartição de vantagens pela hierarquização cultural", "alternatives": [{"letter": "A", "text": "Gestão das ilicitudes pelo sistema judicial.", "file": null}, {"letter": "B", "text": "Aplicação das sanções pelo modelo equânime.", "file": null}, {"letter": "C", "text": "Supressão dos crimes pela penalização severa.", "file": null}, {"letter": "D", "text": "Regulamentação dos privilégios pela justiça social.", "file": null}, {"letter": "E", "text": "Repartição de vantagens pela hierarquização cultural.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/81"}, {"id": "enem-2023-82-geral", "year": 2023, "number": 82, "discipline": "ciencias-humanas", "language": null, "context": "Os vapores cruzavam os mares transportando pessoas, mercadorias e ideias, e ainda carregavam a mala postal, repleta de mensagens. Múltiplas histórias escritas atravessavam o oceano buscando por notícias de filhos e pais, irmãos, maridos e esposas, noivos e noivas. As missivas traziam boas e más novas, comunicavam alegremente nascimentos e casamentos, também doenças e mortes; enviavam declarações de amor e fidelidade, fotos de família; encaminhavam conselhos de velhos, pedidos de ajuda e de dinheiro; expediam cartas bancárias e de chamada. Essa literatura epistolar possibilitava a transmissão e reconstrução das tradições. Os deslocamentos tornaram-se um dos mais potentes produtores de escritura ao longo da história.\n\nTRUZZI, O.; MATOS, I. Saudades: sensibilidades no epistolário de e/imigrantes  \nportuqueses (Portugal-Brasil 1890-1930). Rev. Bras. Hist., n. 70, jul.-dez. 2015.", "prompt": "Conforme o texto, as correspondências trocadas entre imigrantes no Brasil com os seus países de procedência constituíam um dispositivo tecnológico que possibilitava o(a)", "alternatives": [{"letter": "A", "text": "Disputa ideológica entre a comunidade de estrangeiros e a de nativos.", "file": null}, {"letter": "B", "text": "Circularidade cultural entre a sociedade de partida e a de acolhimento.", "file": null}, {"letter": "C", "text": "Controle doutrinário das narrativas do cotidiano de origem e de destino..", "file": null}, {"letter": "D", "text": "Fiscalização política dos fluxos de populações do Novo e do Velho Mundo.", "file": null}, {"letter": "E", "text": "Monitoramento social dos grupos de trabalhadores da cidade e do campo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/82"}, {"id": "enem-2023-83-geral", "year": 2023, "number": 83, "discipline": "ciencias-humanas", "language": null, "context": "Diversos são os fatores causadores da degradação do solo, atuando de forma direta ou indireta, mas quase sempre a grande maioria das terras degradadas inicia esse processo com o desmatamento, que pode ser seguido por diversas formas de ocupação desordenada, como: corte de taludes para a construção de casas, rodovias e ferrovias, agricultura, com uso da queimada, vários tipos de mineração, irrigação excessiva, crescimento desordenado das cidades, superpastoreio, uso do solo para diversos tipos de despejos industriais e domésticos, sem tratamento da área que recebe esses despejos; enfim, de uma forma ou de outra, os solos tornam-se degradados, sendo muitas vezes difícil, ou quase impossível, a sua recuperação.\n\nGUERRA, A. T. Degradação dos solos: conceitos e temas. In: GUERRA, A. T.; JORGE, M. C. O. (Org.). **Degradação dos solos no Brasil**. Rio de Janeiro: Difel, 2018.", "prompt": "A partir da ocupação desordenada exporta no texto, o que impede a recuperação do recurso natural destacado é a", "alternatives": [{"letter": "A", "text": "Elevação da biomassa.", "file": null}, {"letter": "B", "text": "Redução da salinização.", "file": null}, {"letter": "C", "text": "Diminuição da fertilidade.", "file": null}, {"letter": "D", "text": "Ampliação da microfauna.", "file": null}, {"letter": "E", "text": "Decomposição do substrato.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/83"}, {"id": "enem-2023-84-geral", "year": 2023, "number": 84, "discipline": "ciencias-humanas", "language": null, "context": "A partir da década de 1930, começam a ser discutidos no Brasil os princípios de racionalização do trabalho. As preocupações com a cozinha e o trabalho doméstico foram introduzidas com a medicina sanitária e a oferta de gás e eletricidade para uso doméstico no início do século XX. A organização da cozinha visava atingir uma simplificação das tarefas, com a economia de movimentos, e o barateamento dos equipamentos, a partir da produção em grande escala. A padronização e racionalização da habitação e seus componentes visava uma radical transformação da casa, em especial da cozinha, e apoiava-se tanto no desenvolvimento de novos equipamentos quanto nos estudos de racionalização do trabalho doméstico. A principal preocupação era o desenvolvimento de um novo tipo de habitação, que deveria induzir um novo comportamento social.\n\nSILVA, J. L. M. Transformações no espaço doméstico: o fogão a gás e a cozinha paulistana, 1870-1930. Anais do Museu Paulista, n. 2. jul-dez 2007 (adaptado).", "prompt": "No contexto descrito, as mudanças mencionadas proporcionavam às mulheres o(a)", "alternatives": [{"letter": "A", "text": "Controle do orçamento familiar.", "file": null}, {"letter": "B", "text": "Libertação das tradições religiosas.", "file": null}, {"letter": "C", "text": "Exercício da representatividade política.", "file": null}, {"letter": "D", "text": "Ampliação dos momentos de socialização.", "file": null}, {"letter": "E", "text": "Afastamento das atividades especializadas.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/84"}, {"id": "enem-2023-85-geral", "year": 2023, "number": 85, "discipline": "ciencias-humanas", "language": null, "context": "Produtores rurais europeus são antigos opositores de um grande acordo com o Mercosul. Na visão deles, existe um nítido risco de concorrência desleal, pois, na Europa, é preciso seguir regras mais rígidas de produção, o que encarece o processo. Assim, eles não conseguiriam competir com os preços, por exemplo, da carne brasileira e teriam seus negócios ameaçados. Por outro lado, o setor industrial europeu se mobiliza a favor do acordo, uma vez que as reduções de tarifas no comércio internacional dariam maior acesso ao mercado sul-americano. Um exemplo é o setor automotivo europeu, que prevê maior participação e concorrência nos países do Mercosul caso o acordo siga em frente.\n\nROUBICEK, M. Como o risco ambiental afeta o acordo entre Mercosul e União Europeia.  \nDisponível em: www.nexojornal.com.br. Acesso em: 25 out. 2021.", "prompt": "No contexto do acordo citado, os dois grupos econômicos europeus defendem, respectivamente, a", "alternatives": [{"letter": "A", "text": "Restrição dos fluxos migratórios e a maior atuação de sindicatos.", "file": null}, {"letter": "B", "text": "Ampliação das leis trabalhistas e a plena importação de manufaturados.", "file": null}, {"letter": "C", "text": "Proteção das florestas nacionais e a ampla transferência de tecnologias.", "file": null}, {"letter": "D", "text": "Manutenção das barreiras fitossanitárias e a livre circulação de mercadorias.", "file": null}, {"letter": "E", "text": "Remoção dos entraves alfandegários e a melhor remuneração de empregados.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/85"}, {"id": "enem-2023-86-geral", "year": 2023, "number": 86, "discipline": "ciencias-humanas", "language": null, "context": "Durante a Revolução Francesa, um certo padre Niollant escondeu-se no pequeno castelo de L’Escarbas. Pagou amplamente a hospitalidade do velho fidalgo ocupando-se da educação de sua filha, Anaïs. A presença da mãe em nada modificou essa educação masculina dada a uma jovem criatura já muito inclinada à independência em virtude da vida no campo. O padre transmitiu à aluna sua intrepidez de opiniões e sua facilidade de julgamento, sem pensar que essas qualidades, tão necessárias num homem, se tornam defeitos numa mulher destinada aos humildes afazeres de mãe de família. Embora o padre recomendasse continuamente à aluna ser tanto mais graciosa e modesta quanto seu saber era mais extenso, a senhorita de Nègrepelisse ficou com excelente opinião de si mesma.\n\nBALZAC. H. Ilusões perdidas. São Paulo: Penguin Classics:  \nCia. das Letras, 2011 (adaptado).", "prompt": "O comportamento desenvolvido pela personagem evidencia uma postura de", "alternatives": [{"letter": "A", "text": "Abandono de laços afetivos.", "file": null}, {"letter": "B", "text": "Negação da ideia de subjetividade.", "file": null}, {"letter": "C", "text": "Aceitação da hierarquia de gênero.", "file": null}, {"letter": "D", "text": "Consolidação da estratificação social.", "file": null}, {"letter": "E", "text": "Ruptura de valores institucionalizados.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/86"}, {"id": "enem-2023-87-geral", "year": 2023, "number": 87, "discipline": "ciencias-humanas", "language": null, "context": "**TEXTO I**\n\nOriunda da Romênia, Genny Gleizer aportou no Brasil em 1932. Assim como milhares de judeus do Leste Europeu, sua vinda para o Brasil ocorreu em um momento de ascensão do antissemitismo na Europa que tornava precárias suas vidas. O Brasil se colocava como uma possibilidade na busca por condições de sobrevivência e desenvolvimento.\n\nANTÃO, A. C. C. B. Gênero, imigração e política: o caso da judia comunista Genny Gleizer no Governo Vargas (1932-1935). Rio de Janeiro: Casa de Oswaldo Cruz, 2017 (adaptado).\n\n**ТЕХТО II**\n\nA presença judaica no Brasil foi criando aos poucos certas desconfianças que se refletiram em órgãos da imprensa e em círculos intelectuais e políticos. Em parte, essa imagem negativa adviria da onda nacionalista surgida no final dos anos 1910, que concebia imigrantes como concorrentes dos trabalhadores brasileiros, ou como seres improdutivos, exploradores da mão de obra e da riqueza autóctone. Além disso, as elites políticas da época acreditavam que os estrangeiros eram portadores das doutrinas anarquista e comunista, estranhas à “indole do povo brasileiro”. Esses “indesejáveis” seriam um mal externo que corromperia a nação.\n\nMAIO, M. C.: CALAÇA, C. E. Um balanço da bibliografia sobre o antissemitismo  \nno Brasil. In: GRINBERG, K. (Org.). Os judeus no Brasil. Rio de Janeiro: Civilização Brasileira, 2005 (adaptado).", "prompt": "Conforme descrito nos textos, o tratamento dispensado aos grupos mencionados se fundamentava em", "alternatives": [{"letter": "A", "text": "Preceitos teológicos e religiosos.", "file": null}, {"letter": "B", "text": "Aspectos socioeconômicos e ideológicos.", "file": null}, {"letter": "C", "text": "Regulamentações territoriais e alfandegárias.", "file": null}, {"letter": "D", "text": "Orientações constitucionais e estatutárias.", "file": null}, {"letter": "E", "text": "Decretos legislativos e internacionais.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/87"}, {"id": "enem-2023-88-geral", "year": 2023, "number": 88, "discipline": "ciencias-humanas", "language": null, "context": "Concorrer e competir não são a mesma coisa. A concorrência pode até ser saudável sempre que a batalha entre agentes, para melhor empreender uma tarefa e obter melhores resultados finais, exige o respeito a certas regras de convivência preestabelecidas ou não. Já a competitividade se funda na invenção de novas armas de luta, num exercício em que a única regra é a conquista da melhor posição. A competitividade é uma espécie de guerra em que tudo vale e, desse modo, sua prática provoca um afrouxamento dos valores morais e um convite ao exercício de violência.\n\nSANTOS, M. **Por uma outra globalização**: do pensamento único à consciência universal. Rio de Janeiro: Record, 2006.", "prompt": "De acordo com a diferenciação feita pelo autor, que prática econômica é considerada moralmente condenável?", "alternatives": [{"letter": "A", "text": "Adoção do dumping comercial.", "file": null}, {"letter": "B", "text": "Fusão da função administrativa.", "file": null}, {"letter": "C", "text": "Criação de holding empresarial.", "file": null}, {"letter": "D", "text": "Limitação do mercado monopolista.", "file": null}, {"letter": "E", "text": "Modernização da produção industrial.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/88"}, {"id": "enem-2023-89-geral", "year": 2023, "number": 89, "discipline": "ciencias-humanas", "language": null, "context": "![](https://enem.dev/2023/questions/89/9bf9cf75-4df7-495a-8f99-bb6bac2abe2e.PNG)", "prompt": "Qual medida é capaz de minimizar as mudanças apresentadas nas simulações?", "alternatives": [{"letter": "A", "text": "Expandir o transporte marítimo.", "file": null}, {"letter": "B", "text": "Incentivar os fluxos migratórios.", "file": null}, {"letter": "C", "text": "Monitorar as atividades vulcânicas.", "file": null}, {"letter": "D", "text": "Controlar as emissões de carbono.", "file": null}, {"letter": "E", "text": "Priorizar a utilização de termoelétricas.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/89"}, {"id": "enem-2023-90-geral", "year": 2023, "number": 90, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Não tinha outra filosofia. Nem eu. Não digo que a Universidade me não tivesse ensinado alguma; mas eu decorei-lhe só as fórmulas, o vocabulário, o esqueleto. Tratei-a como tratei o latim; embolsei três versos de Virgílio, dois de Horácio, uma dúzia de locuções morais e políticas, para as despesas da conversação. Tratei-os como tratei a história e a jurisprudência. Colhi de todas as cousas a fraseologia, a casca, a ornamentação.\nASSIS, M. Memórias póstumas do Brás Cubas. Belo Horizonte: Autêntica. 1999.\nA descrição crítica do personagem de Machado de Assis assemelha-se às características dos sofistas, contestados pelos filósofos gregos da Antiguidade, porque se mostra alinhada à", "alternatives": [{"letter": "A", "text": "Elaboração conceitual de entendimentos.", "file": null}, {"letter": "B", "text": "Utilização persuasiva do discurso.", "file": null}, {"letter": "C", "text": "Narração alegórica dos rapsodos.", "file": null}, {"letter": "D", "text": "Investigação empírica da physis.", "file": null}, {"letter": "E", "text": "Expressão pictográfica da pólis.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/90"}, {"id": "enem-2023-91-geral", "year": 2023, "number": 91, "discipline": "ciencias-natureza", "language": null, "context": "O número de abelhas encontra-se em declínio em várias regiões do mundo, inclusive no Brasil, sendo que vários fatores contribuem para o colapso de suas colmeias. Nos Estados Unidos, bombas de sementes de espécies vegetais nativas têm sido utilizadas para combater o desaparecimento desses insetos. Elas são pequenas bolinhas recheadas com sementes, adubo e argila. Quando são arremessadas e ficam expostas ao sol e à chuva, germinam até mesmo em solo pouco fértil.\n\nDARAYA, V. Disponível em: http://planetasustentavel.abril.com.br.  \nAcesso em: 2 fev. 2015 (adaptado).", "prompt": "Esse método contribui para a preservação das abelhas porque", "alternatives": [{"letter": "A", "text": "Reduz sua predação", "file": null}, {"letter": "B", "text": "Reduz o uso de pesticidas.", "file": null}, {"letter": "C", "text": "Reduz a competição por abrigo.", "file": null}, {"letter": "D", "text": "Aumenta a oferta de alimento", "file": null}, {"letter": "E", "text": "Aumenta os locais de reprodução", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/91"}]') on conflict(id) do nothing;
insert into orbit_private.answer_keys select * from jsonb_populate_recordset(null::orbit_private.answer_keys,'[{"question_id": "enem-2023-62-geral", "correct_letter": "C"}, {"question_id": "enem-2023-63-geral", "correct_letter": "B"}, {"question_id": "enem-2023-64-geral", "correct_letter": "D"}, {"question_id": "enem-2023-65-geral", "correct_letter": "A"}, {"question_id": "enem-2023-66-geral", "correct_letter": "A"}, {"question_id": "enem-2023-67-geral", "correct_letter": "B"}, {"question_id": "enem-2023-68-geral", "correct_letter": "C"}, {"question_id": "enem-2023-69-geral", "correct_letter": "D"}, {"question_id": "enem-2023-70-geral", "correct_letter": "C"}, {"question_id": "enem-2023-71-geral", "correct_letter": "A"}, {"question_id": "enem-2023-72-geral", "correct_letter": "B"}, {"question_id": "enem-2023-73-geral", "correct_letter": "A"}, {"question_id": "enem-2023-74-geral", "correct_letter": "D"}, {"question_id": "enem-2023-75-geral", "correct_letter": "C"}, {"question_id": "enem-2023-76-geral", "correct_letter": "D"}, {"question_id": "enem-2023-77-geral", "correct_letter": "E"}, {"question_id": "enem-2023-78-geral", "correct_letter": "A"}, {"question_id": "enem-2023-79-geral", "correct_letter": "B"}, {"question_id": "enem-2023-80-geral", "correct_letter": "A"}, {"question_id": "enem-2023-81-geral", "correct_letter": "A"}, {"question_id": "enem-2023-82-geral", "correct_letter": "B"}, {"question_id": "enem-2023-83-geral", "correct_letter": "C"}, {"question_id": "enem-2023-84-geral", "correct_letter": "D"}, {"question_id": "enem-2023-85-geral", "correct_letter": "D"}, {"question_id": "enem-2023-86-geral", "correct_letter": "E"}, {"question_id": "enem-2023-87-geral", "correct_letter": "B"}, {"question_id": "enem-2023-88-geral", "correct_letter": "A"}, {"question_id": "enem-2023-89-geral", "correct_letter": "D"}, {"question_id": "enem-2023-90-geral", "correct_letter": "B"}, {"question_id": "enem-2023-91-geral", "correct_letter": "D"}]') on conflict(question_id) do nothing;
