insert into public.orbit_questions(id,year,number,discipline,language,context,prompt,alternatives,source_url) select id,year,number,discipline,language,context,prompt,alternatives,source_url from jsonb_populate_recordset(null::public.orbit_questions,'[{"id": "enem-2023-92-geral", "year": 2023, "number": 92, "discipline": "ciencias-natureza", "language": null, "context": "Os mais antigos cozinhavam o feijão na panela de ferro a fim de acabar com a palidez de seus filhos. Alguns chegavam até a colocar um prego enferrujado nesse cozimento para liberar o ferro contido nele. Sabe-se que esse elemento pode ser encontrado na sua forma metálica ou iônica, sendo essencial para a manutenção da vida humana.", "prompt": "As estratégias citadas eram utilizadas com o objetivo de", "alternatives": [{"letter": "A", "text": "Tratar a diarreia.", "file": null}, {"letter": "B", "text": "Prevenir a anemia.", "file": null}, {"letter": "C", "text": "Evitar as verminoses.", "file": null}, {"letter": "D", "text": "Remediar o raquitismo", "file": null}, {"letter": "E", "text": "Combater a febre amarela.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/92"}, {"id": "enem-2023-93-geral", "year": 2023, "number": 93, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "A utilização de tecnologia nuclear é um tema bastante controverso, por causa do risco de acidentes graves, como aqueles ocorridos em Chernobyl (1986), em Goiânia (1987) e em Fukushima (2011). Apesar de muitas desvantagens, como a geração de resíduos tóxicos, a descontaminação ambiental dispendiosa em caso de acidentes e a utilização em armas nucleares, a geração de energia nuclear apresenta vantagens em comparação a outras fontes de energia.\nA geração dessa energia tem como característica:", "alternatives": [{"letter": "A", "text": "Formar resíduos facilmente recicláveis.", "file": null}, {"letter": "B", "text": "Promover o aumento do desmatamento.", "file": null}, {"letter": "C", "text": "Contribuir para a produção de chuva ácida.", "file": null}, {"letter": "D", "text": "Emitir gases tóxicos que são lançados no ambiente.", "file": null}, {"letter": "E", "text": "Produzir calor sem o consumo de combustíveis fósseis.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/93"}, {"id": "enem-2023-94-geral", "year": 2023, "number": 94, "discipline": "ciencias-humanas", "language": null, "context": "Em uma indústria, o controle da dureza da água é importante quando ela é utilizada em caldeiras, uma vez que sais pouco solúveis, formados a partir de sulfatos e carbonatos, podem acumular-se no interior das tubulações, causando obstruções. Para avaliar a água utilizada nessa indústria, foram realizados testes de qualidade que consideraram os seauintes parâmetros:\n\n![](https://enem.dev/2023/questions/94/429989c0-d615-4e19-a5e6-838e81a6039c.png)", "prompt": "Qual teste deve ser considerado para controlar a formação desse tipo de obstrução de tubulações?", "alternatives": [{"letter": "A", "text": "1", "file": null}, {"letter": "B", "text": "2", "file": null}, {"letter": "C", "text": "3", "file": null}, {"letter": "D", "text": "4", "file": null}, {"letter": "E", "text": "5", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/94"}, {"id": "enem-2023-95-geral", "year": 2023, "number": 95, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "As aves apresentam dois tipos de músculos em seus corpos: vermelhos e brancos. Aves migratórias como garças, gansos e patos selvagens têm os músculos vermelhos bem desenvolvidos, com ampla rede de vasos sanguíneos.\nNas viagens por grandes distâncias, tais músculos são fundamentais, pois favorecem o(a)", "alternatives": [{"letter": "A", "text": "Execução de manobras.", "file": null}, {"letter": "B", "text": "Metabolismo corpóreo elevado.", "file": null}, {"letter": "C", "text": "Manutenção da aerodinâmica.", "file": null}, {"letter": "D", "text": "Deslocamento a grandes velocidades.", "file": null}, {"letter": "E", "text": "Capacidade de voo em grandes altitudes.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/95"}, {"id": "enem-2023-96-geral", "year": 2023, "number": 96, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Existe no comércio um produto antimofo constituído por uma embalagem com tampa perfurada contendo cloreto de cálcio anidro, CaCI,. Uma vez aberto o lacre, essa substância absorve a umidade ambiente, transformando-se em cloreto de cálcio di-hidratado, CaCI, 2H,0. Considere a massa molar da água igual a 18 g mol-1, e a massa molar do cloreto de cálcio anidro igual a 111 g mol-1.\nNa hidratação da substância presente no antimofo, o ganho percentual, em massa, é mais próximo de", "alternatives": [{"letter": "A", "text": "14%", "file": null}, {"letter": "B", "text": "16%", "file": null}, {"letter": "C", "text": "24%", "file": null}, {"letter": "D", "text": "32%", "file": null}, {"letter": "E", "text": "75%", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/96"}, {"id": "enem-2023-97-geral", "year": 2023, "number": 97, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Um garoto comprou vários abacates na feira, mas descobriu que eles não estavam maduros o suficiente para serem consumidos. Sua mãe recomendou que ele colocasse os abacates em um recipiente fechado, pois isso aceleraria seu amadurecimento. Com certa dúvida, o garoto realizou esta experiência: colocou alguns abacates no recipiente e deixou os demais em uma fruteira aberta. Surpreendendo-se, ele percebeu que os frutos que estavam no recipiente fechado amadureceram mais rapidamente.\nA aceleração desse processo é causada por", "alternatives": [{"letter": "A", "text": "Acúmulo de gás etileno.", "file": null}, {"letter": "B", "text": "Redução da umidade do ar.", "file": null}, {"letter": "C", "text": "Aumento na concentração de CO2.", "file": null}, {"letter": "D", "text": "Diminuição da intensidade luminosa.", "file": null}, {"letter": "E", "text": "Isolamento do contato com O2 atmosférico.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/97"}, {"id": "enem-2023-98-geral", "year": 2023, "number": 98, "discipline": "ciencias-humanas", "language": null, "context": "Há muito tempo são conhecidas espécies de lesmas-do-mar com uma capacidade impar: guardar parte da maquinaria das células das algas que consomem — os cloroplastos — e mantê-los funcionais dentro das suas próprias células, obtendo assim parte do seu alimento. Investigadores portugueses descobriram que essas lesmas-do-mar podem ser mais eficientes nesse processo do que as próprias algas que consomem.\n\nDisponível em: www.cienciahoje.pt. Acesso em: 10 fev. 2015 (adaptado).", "prompt": "Essa adaptação confere a esse organismo a capacidade de obter primariamente", "alternatives": [{"letter": "A", "text": "Ácidos necleicos.", "file": null}, {"letter": "B", "text": "Carboidratos.", "file": null}, {"letter": "C", "text": "Proteínas.", "file": null}, {"letter": "D", "text": "Vitaminas.", "file": null}, {"letter": "E", "text": "Lipídios.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/98"}, {"id": "enem-2023-99-geral", "year": 2023, "number": 99, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "A leishmaniose visceral é uma zoonose causada por um protozoário do gênero Leishmania que é encontrado em diversos tecidos. Ela é transmitida ao homem de forma indireta, por vetores do ambiente doméstico. O cão é considerado um importante hospedeiro desse protozoário, podendo ou não apresentar os sintomas da doença, como perda de peso, anemia, ferimentos na pele, diarreia, conjuntivite e insuficiência renal. Em uma região que sofre com alta incidência dessa doença, uma campanha do centro de zoonoses buscou verificar a presença desse protozoário nos cães para tentar controlar a doença.", "alternatives": [{"letter": "A", "text": "Urina.", "file": null}, {"letter": "B", "text": "Saliva.", "file": null}, {"letter": "C", "text": "Fezes.", "file": null}, {"letter": "D", "text": "Sangue.", "file": null}, {"letter": "E", "text": "Secreção ocular.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/99"}, {"id": "enem-2023-100-geral", "year": 2023, "number": 100, "discipline": "ciencias-natureza", "language": null, "context": "Um professor lança uma esfera verticalmente para cima, a qual retorna, depois de alguns segundos, ao ponto de lançamento. Em seguida, lista em um quadro todas as possibilidades para as grandezas cinemáticas.\n\n![](https://enem.dev/2023/questions/100/92848aa5-da82-4c66-9945-7051120a42c9.jpg)", "prompt": "Ele solicita aos alunos que analisem as grandezas cinemáticas no instante em que a esfera atinge a altura máxima, escolhendo uma combinação para os módulos e sentidos da velocidade e da aceleração. A escolha que corresponde à combinação correta é", "alternatives": [{"letter": "A", "text": "V = 0 e a ≠ 0 para cima.", "file": null}, {"letter": "B", "text": "V ≠ 0 para cima e a = 0", "file": null}, {"letter": "C", "text": "V = 0 e a ≠ 0 para baixo.", "file": null}, {"letter": "D", "text": "V ≠ 0 para cima e a ≠ 0 para cima.", "file": null}, {"letter": "E", "text": "V ≠ 0 para baixo e a ≠ 0 para baixo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/100"}, {"id": "enem-2023-101-geral", "year": 2023, "number": 101, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "Muitas mulheres sofrem com desconfortos nos dias que antecedem a menstruação, a chamada tensão pré-menstrual. Entre outros sintomas, podem ocorrer alterações de humor. Atualmente, acredita-se que os sintomas são resultado da queda na concentração do neurotransmissor serotonina, que, por sua vez, está relacionado com a diminuição na produção dos hormônios ovarianos estrógeno e progesterona, observada nessa fase do ciclo feminino.\nDIMMOCK, P. W. et al. Efficacy of Selective Serotonin-Reuptake Inhibitors in Premenstrual Syndrome: a Systematic Review. The Lancet, n. 9 236, 2000 (adaptado).\nA redução da produção desses hormônios nessa fase está relacionada com o(a)", "alternatives": [{"letter": "A", "text": "Regressão do corpo lúteo ovariano.", "file": null}, {"letter": "B", "text": "Diminuição na produção de ocitocina.", "file": null}, {"letter": "C", "text": "Liberação do gameta feminino na ovulação.", "file": null}, {"letter": "D", "text": "Aumento nos níveis dos hormônios LH e FSH.", "file": null}, {"letter": "E", "text": "Elevação nos níveis sorológicos de adrenalina.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/101"}, {"id": "enem-2023-102-geral", "year": 2023, "number": 102, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "As cetonas fazem parte de famílias olfativas encontradas em muitos alimentos. A molécula de hexan-3-ona é um exemplo desses compostos voláteis responsáveis pelo aroma, podendo ser obtida por processos energéticos realizados em meio ácido, na presença de oxidantes como o permanganato de potássio. Para se produzir esse composto volátil em laboratório, deve-se oxidar a molécula de", "alternatives": [{"letter": "A", "text": "Hexanal.", "file": null}, {"letter": "B", "text": "Hexan-1-ol.", "file": null}, {"letter": "C", "text": "Hexan-3-ol.", "file": null}, {"letter": "D", "text": "Hex-1-en-1-ol.", "file": null}, {"letter": "E", "text": "Ácido hexanoico.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/102"}, {"id": "enem-2023-103-geral", "year": 2023, "number": 103, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "Durante a evolução das plantas, ocorreu uma transição do ambiente aquático para o ambiente terrestre graças ao surgimento de algumas estruturas que as tornaram independentes da água. Esse fato permitiu maior dispersão desse grupo de seres vivos, sendo possível observá-los em diferentes ambientes na atualidade.\nQual estrutura possibilitou a independência da água para a fecundação dos seres vivos citados acima?", "alternatives": [{"letter": "A", "text": "Fruto.", "file": null}, {"letter": "B", "text": "Esporo.", "file": null}, {"letter": "C", "text": "Semente.", "file": null}, {"letter": "D", "text": "Tubo polínico.", "file": null}, {"letter": "E", "text": "Vaso condutor.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/103"}, {"id": "enem-2023-104-geral", "year": 2023, "number": 104, "discipline": "ciencias-natureza", "language": null, "context": "O vidro contendo alumínio em sua composição é um excelente material para acondicionar medicamentos e suplementos, porque pode ser esterilizado por aquecimento. No entanto, quando o medicamento ou suplemento contém substâncias que se ligam fortemente ao íon desse metal, a dissolução do alumínio é promovida em função do deslocamento do equilíbrio químico estabelecido entre a espécie imobilizada no vidro e a espécie em solução. Por essa razão, recomenda-se que suplementos de nutrição de recém-nascidos contendo gluconato de cálcio sejam acondicionados em embalagens plásticas, e não nesse tipo de vidro.\n\n**Atualização da recomendação da Sociedade Portuguesa de Neonatologia.**  \nDisponível em: www.spneonatologia.pt. Acesso em: 22 out. 2021 (adaptado).", "prompt": "Caso esse suplemento seja acondicionado em embalagem desse tipo de vidro, o risco de contaminação por alumínio será maior se o(a)", "alternatives": [{"letter": "A", "text": "Vidro do frasco for translúcido.", "file": null}, {"letter": "B", "text": "Concentração de gluconato de cálcio for alta.", "file": null}, {"letter": "C", "text": "Frasco de vidro apresentar uma maior espessura.", "file": null}, {"letter": "D", "text": "Vidro for previamente esterilizado em altas temperaturas.", "file": null}, {"letter": "E", "text": "Reação do alumínio com gluconato de cálcio for endotérmica.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/104"}, {"id": "enem-2023-105-geral", "year": 2023, "number": 105, "discipline": "ciencias-natureza", "language": null, "context": "Barbatimão é o nome popular de uma árvore cuja casca e utilizada para fins medicinais. Essa casca é constituída principalmente de dois tecidos vegetais: periderme e floema. A extração da casca tem levado à morte muitos indivíduos dessa espécie, quando o corte retira um anel completo ao longo da circunferência do tronco. Aqueles que têm parte da casca retirada sem completar essa circunferência podem sobreviver.", "prompt": "A morte desses indivíduos, decorrente da retirada do anel completo da casca, é provocada pela interrupção da", "alternatives": [{"letter": "A", "text": "Fotossíntese.", "file": null}, {"letter": "B", "text": "Transpiração.", "file": null}, {"letter": "C", "text": "Troca de gases.", "file": null}, {"letter": "D", "text": "Formação de brotos.", "file": null}, {"letter": "E", "text": "Nutrição das raízes.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/105"}, {"id": "enem-2023-106-geral", "year": 2023, "number": 106, "discipline": "ciencias-natureza", "language": null, "context": "A tecnologia de vacinas de RNA mensageiro (RNAm) é investigada há anos. Avanços científicos em genética molecular permitiram desenvolver uma vacina para controle da pandemia da covid-19 causada pelo vírus de RNA SARS-CoV-2. A vacina de RNAm tem sequências de genes do vírus. Entretanto, por ser muito instável, o RNAm deve ser recoberto por uma capa de lipídios que evita sua degradação e favorece sua ação. Dessa forma, o RNAm desempenhará sua função especifica atuando no mesmo compartimento celular de sempre.\n\nDisponível em: https://sbim.org.br. Acesso em: 29 nov. 2021 (adaptado).", "prompt": "A imunização produzida por esse tipo de vacina é alcançada por meio da", "alternatives": [{"letter": "A", "text": "Estimulação de leucócitos induzida pela capa lipídica contendo RNAm.", "file": null}, {"letter": "B", "text": "Atuação do RNAm como sequestrador do vírus para o meio extracelular.", "file": null}, {"letter": "C", "text": "Tradução do RNAm em proteína viral, desencadeando a resposta antigênica.", "file": null}, {"letter": "D", "text": "Competição entre o RNAm vacinal e o RNA viral pelos sítios dos ribossomos.", "file": null}, {"letter": "E", "text": "Incorporação do RNAm viral ao genoma do hospedeiro. gerando novo fenótipo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/106"}, {"id": "enem-2023-107-geral", "year": 2023, "number": 107, "discipline": "ciencias-natureza", "language": null, "context": "Na fertilização in vitro, espermatozoides são adicionados aos gametas femininos retirados de uma mulher. Após o período de incubação, a fecundação é favorecida pela ação de enzimas. Em um procedimento realizado, observou-se que nenhum dos gametas femininos foi fertilizado e, posteriormente, verificou-se que havia sido adicionado, equivocadamente, um coquetel de inibidores das enzimas do acrossomo, no lugar de um dos nutrientes constituintes do meio de cultura.", "prompt": "O coquetel de inibidores impediu o(a)", "alternatives": [{"letter": "A", "text": "Formação do pronúcleo masculino.", "file": null}, {"letter": "B", "text": "Início da divisão mitótica do zigoto.", "file": null}, {"letter": "C", "text": "Término da segunda divisão meiótica do ovócito.", "file": null}, {"letter": "D", "text": "Passagem do espermatozoide pela corona radiata e zona pelúcida.", "file": null}, {"letter": "E", "text": "Fusão das membranas plasmáticas do ovócito e do espermatozoide.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/107"}, {"id": "enem-2023-108-geral", "year": 2023, "number": 108, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "O fogão por indução funciona a partir do surgimento de uma corrente elétrica induzida no fundo da panela, com consequente transformação de energia elétrica em calor por efeito Joule. A principal vantagem desses fogões é a eficiência energética, que é substancialmente maior que a dos fogões convencionais.\nA corrente elétrica mencionada é induzida por", "alternatives": [{"letter": "A", "text": "Radiação.", "file": null}, {"letter": "B", "text": "Condução.", "file": null}, {"letter": "C", "text": "Campo elétrico variável.", "file": null}, {"letter": "D", "text": "Campo magnético variável.", "file": null}, {"letter": "E", "text": "Ressonância eletromagnética.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/108"}, {"id": "enem-2023-109-geral", "year": 2023, "number": 109, "discipline": "ciencias-humanas", "language": null, "context": "Uma academia decide trocar gradualmente seus aparelhos de musculação. Agora, os frequentadores que utilizam os aparelhos do tipo 1 podem também utilizar os aparelhos do tipo 2, representados na figura, para elevar cargas correspondentes às massas M1 e M2 com velocidade constante. A fim de que o exercício seja realizado com a mesma força F, os usuários devem ser orientados a respeito da relação entre as cargas nos dois tipos de aparelhos, já que as polias fixas apenas mudam a direção das forças, enquanto a polia móvel divide as forças.\n\nEm ambos os aparelhos, considere as cordas inextensíveis, as massas das polias e das cordas desprezíveis e que não há dissipação de energia.\n\n![](https://enem.dev/2023/questions/109/e083688b-cc00-4c8b-9de6-01f07a7a6a5c.png)", "prompt": "Para essa academia, qual deve ser a razão M2/M1 informada aos usuários?", "alternatives": [{"letter": "A", "text": "1/4", "file": null}, {"letter": "B", "text": "1/2", "file": null}, {"letter": "C", "text": "1", "file": null}, {"letter": "D", "text": "2", "file": null}, {"letter": "E", "text": "4", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/109"}, {"id": "enem-2023-110-geral", "year": 2023, "number": 110, "discipline": "ciencias-natureza", "language": null, "context": "Um assistente de laboratório precisou descartar sete frascos contendo solução de nitrato de mercúrio(l) que não foram utilizados em uma aula prática. Cada frasco continha 5,25 g de Hg2(NO3)2 dissolvidos em água. Temendo a toxidez do mercúrio e sabendo que o Hg2Cl2 tem solubilidade muito baixa, o assistente optou por retirar o mercúrio da solução por precipitação com cloreto de sódio (NaCl), conforme a equação química:\n\n![](https://enem.dev/2023/questions/110/9874e4c1-d246-4697-8798-52f1577c2542.png)\n\nNa dúvida sobre a massa de NaCl a ser utilizada, o assistente aumentou gradativamente a quantidade adicionada em cada frasco, como apresentado no quadro.\n\n![](https://enem.dev/2023/questions/110/f0ce2b28-d6bf-456a-945d-64bc0518a241.png)\n\nO produto obtido em cada experimento foi filtrado, secado e teve sua massa aferida. O assistente organizou os resultados na forma de um gráfico que correlaciona a massa de NaCl adicionada com a massa de Hg2Cl2 obtida em cada frasco. A massa molar do Hg2(NO3)2 é 525 g mol\\-1, a do NaCl é 58 g mol\\-1 e a do Hg2Cl2 é 472 g mol\\-1.", "prompt": "Qual foi o gráfico obtido pelo assistente de laboratório?", "alternatives": [{"letter": "A", "text": null, "file": "https://enem.dev/2023/questions/110/99a5e7f5-0a09-4d57-b9e8-363cbe34924d.png"}, {"letter": "B", "text": null, "file": "https://enem.dev/2023/questions/110/23a075d7-b302-4605-accc-f200e9ce2bc2.png"}, {"letter": "C", "text": null, "file": "https://enem.dev/2023/questions/110/b8bb098b-e8e0-4dae-b576-ca32f3e68aa5.png"}, {"letter": "D", "text": null, "file": "https://enem.dev/2023/questions/110/42caae88-c341-45b5-ba72-92c8c605bb60.png"}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/110/8366e6b5-7909-4fdd-9106-4cef546cb54b.png"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/110"}, {"id": "enem-2023-111-geral", "year": 2023, "number": 111, "discipline": "ciencias-natureza", "language": null, "context": "![](https://enem.dev/2023/questions/111/9ae85aec-1b17-4ee7-afd9-e9cf17101aca.png)\n\nSOUSA. M. Disponível em: www.monica.com.br. Acesso em: 2 out. 2012 (adaptado)", "prompt": "Na tirinha de Mauricio de Sousa, os personagens Cebolinha e Cascão fazem uma brincadeira utilizando duas latas e um barbante. Ao perceberem que o som pode ser transmitido através do barbante, resolvem alterar o comprimento do barbante para ficar cada vez mais extenso. As demais condições permaneceram inalteradas durante a brincadeira.\nNa prática, à medida que se aumenta o comprimento do barbante, ocorre a redução de qual característica da onda sonora?", "alternatives": [{"letter": "A", "text": "Altura.", "file": null}, {"letter": "B", "text": "Período.", "file": null}, {"letter": "C", "text": "Amplitude.", "file": null}, {"letter": "D", "text": "Velocidade.", "file": null}, {"letter": "E", "text": "Comprimento.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/111"}, {"id": "enem-2023-112-geral", "year": 2023, "number": 112, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "Informações digitais — dados — são gravadas em discos ópticos, como CD e DVD, na forma de cavidades microscópicas. A gravação e a leitura óptica dessas informações são realizadas por um laser (fonte de luz monocromática). Quanto menores as dimensões dessas cavidades, mais dados são armazenados na mesma área do disco. O fator limitante para a leitura de dados é o espalhamento da luz pelo efeito de difração, fenômeno que ocorre quando a luz atravessa um obstáculo com dimensões da ordem de seu comprimento de onda. Essa limitação motivou o desenvolvimento de lasers com emissão em menores comprimentos de onda, possibilitando armazenar e ler dados em cavidades cada vez menores.\nEm qual região espectral se situa o comprimento de onda do laser que otimiza o armazenamento e a leitura de dados em discos de uma mesma área?", "alternatives": [{"letter": "A", "text": "Violeta.", "file": null}, {"letter": "B", "text": "Azul.", "file": null}, {"letter": "C", "text": "Verde.", "file": null}, {"letter": "D", "text": "Vermelho.", "file": null}, {"letter": "E", "text": "Infravermelho.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/112"}, {"id": "enem-2023-113-geral", "year": 2023, "number": 113, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "O bluetooth é uma tecnologia de comunicação sem fio, de curto alcance, presente em diferentes dispositivos eletrônicos de consumo. Ela permite que aparelhos eletrônicos diferentes se conectem e troquem dados entre si. No padrão bluetooth, denominado de Classe 2, as antenas transmitem sinais de potência igual a 2,4 mW e possibilitam conectar dois dispositivos distanciados até 10 m. Considere que essas antenas se comportam como fontes puntiformes que emitem ondas eletromagnéticas esféricas e que a intensidade do sinal é calculada pela potência por unidade de área. Considere 3 como valor aproximado para π. \nPara que o sinal de bluetooth seja detectado pelas antenas, o valor mínimo de sua intensidade, em W/m²?, e mais próximo de", "alternatives": [{"letter": "A", "text": null, "file": "https://enem.dev/2023/questions/113/8d968451-63ce-4bb6-9fc1-2a9997a962bf.png"}, {"letter": "B", "text": null, "file": "https://enem.dev/2023/questions/113/7c34bc21-998f-433e-8687-e08b95f9b871.png"}, {"letter": "C", "text": null, "file": "https://enem.dev/2023/questions/113/7286e182-5f71-4bbd-a08e-95b6b020028b.png"}, {"letter": "D", "text": null, "file": "https://enem.dev/2023/questions/113/335c851b-35c6-4c99-8bd1-50cada05ce2e.png"}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/113/efe618e1-ecf9-47c4-81eb-00060a2954e0.png"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/113"}, {"id": "enem-2023-114-geral", "year": 2023, "number": 114, "discipline": "ciencias-natureza", "language": null, "context": "Uma equipe de segurança do transporte de uma empresa avalia o comportamento das tensões que aparecem em duas cordas, 1 e 2, usadas para prender uma carga de massa M = 200 kg na carroceria, conforme a ilustração. Quando o caminhão parte do repouso, sua aceleração é constante e igual a 3 m/s2 e, quando ele é freado bruscamente, sua frenagem é constante e igual a 5 m/s2. Em ambas as situações, a carga encontra-se na iminência de movimento, e o sentido do movimento do caminhão está indicado na figura. O coeficiente de atrito estático entre a caixa e c assoalho da carroceria é igual a 0,2. Considere a aceleração da gravidade igual a 10 m/s2, as tensões iniciais nas cordas iguais a zero e as duas cordas ideais.\n\n![](https://enem.dev/2023/questions/114/e245e16d-8a95-4b2e-ab33-6dd299ff9474.png)", "prompt": "Nas situações de aceleração e frenagem do caminhão, as tensões nas cordas 1 e 2, em newton, serão", "alternatives": [{"letter": "A", "text": "Aceleração: T1 = 0 e T2 = 200; frenagem: T1 = 600 e T2 = 0.", "file": null}, {"letter": "B", "text": "Aceleração: T1 = 0 e T2 = 200; frenagem: T1 = 1 400 e T2 = 0.", "file": null}, {"letter": "C", "text": "Aceleração: T1 = 0 e T2 = 200; frenagem: T1 = 600 e T2 = 0.", "file": null}, {"letter": "D", "text": "Aceleração: T1 = 560 e T2 = 0; frenagem: T1 = 0 e T2 = 960.", "file": null}, {"letter": "E", "text": "Aceleração: T1 = 640 e T2 = 0; frenagem: T1 = 0 e T2 = 1 040.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/114"}, {"id": "enem-2023-115-geral", "year": 2023, "number": 115, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "A biorremediação designa tratamentos que usam organismos para reduzir a quantidade de substâncias tóxicas no ambiente ou degradá-las em substâncias não tóxicas ou de menor toxicidade. Uma planta aquática, o aguapé, tem sido utilizada para a biorremediação de ambientes contaminados por metais tóxicos. Sabe-se que esses poluentes serão captados para dentro do corpo do vegetal.\nDentro do corpo do vegetal, esses contaminantes serão", "alternatives": [{"letter": "A", "text": "Digeridos por enzimas.", "file": null}, {"letter": "B", "text": "Acumulados nos tecidos.", "file": null}, {"letter": "C", "text": "Eliminados pelos estômatos.", "file": null}, {"letter": "D", "text": "Metabolizados por glândulas.", "file": null}, {"letter": "E", "text": "Utilizados como fonte energética.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/115"}, {"id": "enem-2023-116-geral", "year": 2023, "number": 116, "discipline": "ciencias-natureza", "language": null, "context": "O ciclo do nitrogênio é composto por várias etapas, conforme a figura, sendo cada uma desempenhada por um grupo específico de microrganismos.\n\n![](https://enem.dev/2023/questions/116/aab4b4fe-505c-4eda-a772-42a363f6ba8a.png)", "prompt": "Se o grupo dos microrganismos decompositores fosse exterminado, qual etapa não ocorreria?", "alternatives": [{"letter": "A", "text": "1", "file": null}, {"letter": "B", "text": "2", "file": null}, {"letter": "C", "text": "3", "file": null}, {"letter": "D", "text": "4", "file": null}, {"letter": "E", "text": "5", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/116"}, {"id": "enem-2023-117-geral", "year": 2023, "number": 117, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "Os raios cósmicos são fontes de radiação ionizante potencialmente perigosas para o organismo humano. Para quantificar a dose de radiação recebida, utiliza-se o sievert (Sv), definido como a unidade de energia recebida por unidade de massa. A exposição à radiação proveniente de raios cósmicos aumenta com a altitude, o que pode representar um problema para as tripulações de aeronaves. Recentemente, foram realizadas medições acuradas das doses de radiação ionizante para voos entre Rio de Janeiro e Roma.\nOs resultados têm indicado que a dose média de radiação recebida na fase de cruzeiro (que geralmente representa 80% do tempo total de voo) desse trecho intercontinental é 2 μSv/h. As normas internacionais da aviação civil limitam em 1 000 horas por ano o tempo de trabalho para as tripulações que atuem em voos intercontinentais. Considere que a dose de radiação ionizante para uma radiografia torácica é estimada em 0,2 mSv.\nRUAS, A. C. O tripulante de aeronaves e a radiação ionizante. São Paulo: Edição do Autor, 2019 (adaptado).\n \nA quantas radiografias torácicas corresponde a dose de radiação ionizante à qual um tripulante que atue no trecho Rio de Janeiro−Roma é exposto ao longo de um ano?", "alternatives": [{"letter": "A", "text": "8", "file": null}, {"letter": "B", "text": "10", "file": null}, {"letter": "C", "text": "80", "file": null}, {"letter": "D", "text": "100", "file": null}, {"letter": "E", "text": "1000", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/117"}, {"id": "enem-2023-118-geral", "year": 2023, "number": 118, "discipline": "ciencias-natureza", "language": null, "context": "A gasolina é uma mistura de hidrocarbonetos de cadeias saturadas contendo de 8 a 12 átomos de carbono. Além disso, a gasolina de alto desempenho deve conter elevados teores de hidrocarbonetos de cadeias ramificadas, de forma a resistir à compressão e entrar em ignição apenas quando a vela aciona uma centelha elétrica no motor. No quadro, estão apresentados compostos que podem ser utilizados como combustíveis.\n\n![](https://enem.dev/2023/questions/118/5d656ef9-cabd-499e-bd98-51993ccb6c1c.png)", "prompt": "Entre esses compostos, aquele que conferirá maior desempenho como combustível é o", "alternatives": [{"letter": "A", "text": "I.", "file": null}, {"letter": "B", "text": "II.", "file": null}, {"letter": "C", "text": "III.", "file": null}, {"letter": "D", "text": "IV.", "file": null}, {"letter": "E", "text": "V.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/118"}, {"id": "enem-2023-119-geral", "year": 2023, "number": 119, "discipline": "ciencias-natureza", "language": null, "context": "De acordo com a Constituição Federal, é competencia dos municípios o gerenciamento dos serviços de limpeza e coleta dos resíduos urbanos (lixo). No entanto, há relatos de que parte desse lixo acaba sendo incinerado, liberando substâncias tóxicas para o ambiente e causando acidentes por explosões, principalmente quando ocorre a incineração de frascos de aerossóis (por exemplo: desodorantes, inseticidas e repelentes). A temperatura elevada provoca a vaporização de todo o conteúdo dentro desse tipo de frasco, aumentando a pressão em seu interior até culminar na explosão da embalagem.\n\nZVEIBIL, V. Z. et al. **Cartilha de limpeza urbana**. Disponível em: www.lbam.org.br. Acesso em: 6 jul. 2015 (adaptado).\n\nSuponha um frasco metálico de um aerossol de capacidade igual a 100 mL, contendo 0,1 mol de produtos gasosos à temperatura de 650 °C, no momento da explosão.\n\n![](https://enem.dev/2023/questions/119/47913cea-fd78-4f5d-af82-f3494e353a85.png)", "prompt": "A pressão, em atm, dentro do frasco, no momento da explosão, é mais próxima de", "alternatives": [{"letter": "A", "text": "756.", "file": null}, {"letter": "B", "text": "533.", "file": null}, {"letter": "C", "text": "76.", "file": null}, {"letter": "D", "text": "53.", "file": null}, {"letter": "E", "text": "13.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/119"}, {"id": "enem-2023-120-geral", "year": 2023, "number": 120, "discipline": "ciencias-natureza", "language": null, "context": "O circuito com três lâmpadas incandescentes idênticas, representado na figura, consiste em uma associação mista de resistores. Cada lâmpada (L1, L2, e L3) é associada, em paralelo, a um resistor de resistência R, formando um conjunto. Esses conjuntos são associados em série, tendo todas as lâmpadas o mesmo brilho quando ligadas à fonte de energia. Após vários dias em uso, apenas a lâmpada L2 queima, enquanto as demais permanecem acesas.\n\n![](https://enem.dev/2023/questions/120/80ceec42-52be-4ea5-8cf1-c75004d0f166.png)", "prompt": "Em relação à situação em que todas as lâmpadas funcionam, após a queima de L2, os brilhos das lâmpadas serão", "alternatives": [{"letter": "A", "text": "Os mesmos.", "file": null}, {"letter": "B", "text": "Mais intensos.", "file": null}, {"letter": "C", "text": "Menos intensos.", "file": null}, {"letter": "D", "text": "Menos intenso para L1 e o mesmo para L3.", "file": null}, {"letter": "E", "text": "Mais intenso para L1 e menos intenso para L3.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/120"}, {"id": "enem-2023-121-geral", "year": 2023, "number": 121, "discipline": "ciencias-natureza", "language": null, "context": "Os solos amazônicos, ricos em silicato, não são apropriados para o cultivo por serem incapazes de reter nutrientes. Contudo, descobertas arqueológicas têm demonstrado que os antigos habitantes da Amazônia dominavam a técnica de preparo de um insumo agrícola natural, denominado terra preta. Esse insumo era constituído principalmente de uma espécie de biocarvão (biochar) obtido da queima de matéria orgânica, como troncos de árvores, pedaços de ossos e esterco, capaz de manter um solo fértil por anos.\n\nAdmite-se que o efeito do biocarvão na fertilização do solo estava, em parte, relacionado à presença de grupos orgânicos do tipo carboxilato em sua superfície, carregados negativamente (—COO–). Esses grupos atraem íons positivos necessários como nutrientes, tais quais os provenientes do potássio (K), do cálcio (Ca) e do magnésio (Mg), além de micronutrientes, como zinco (Zn) e ferro (Fe). Essa ligação no solo fertilizado é predominantemente iônica, conforme ilustra a figura, em que M\\* representa os cátions metálicos. De acordo com a escala de Pauling, a eletronegatividade do elemento oxigênio é igual a 3,44\n\n![](https://enem.dev/2023/questions/121/7814f78a-9417-4651-bec1-eb30fe7fd046.png)\n\nO quadro apresenta os valores de eletronegatividade desses cinco elementos metálicos.\n\n![](https://enem.dev/2023/questions/121/1913a73f-35d7-4367-a68e-949fa743bf7c.png)\n\nMICHALOVIC, M. Ancient Soil Chemists of the Amazon. **ChemMatters**, fev. 2009 (adaptado).", "prompt": "O cátion que resultará em uma interação de maior caráter iônico com o ânion carboxilato será aquele proveniente do elemento", "alternatives": [{"letter": "A", "text": "Potássio.", "file": null}, {"letter": "B", "text": "Cálcio.", "file": null}, {"letter": "C", "text": "Magnésio.", "file": null}, {"letter": "D", "text": "Zinco.", "file": null}, {"letter": "E", "text": "Ferro.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/121"}]') on conflict(id) do nothing;
insert into orbit_private.answer_keys select * from jsonb_populate_recordset(null::orbit_private.answer_keys,'[{"question_id": "enem-2023-92-geral", "correct_letter": "B"}, {"question_id": "enem-2023-93-geral", "correct_letter": "E"}, {"question_id": "enem-2023-94-geral", "correct_letter": "A"}, {"question_id": "enem-2023-95-geral", "correct_letter": "B"}, {"question_id": "enem-2023-96-geral", "correct_letter": "D"}, {"question_id": "enem-2023-97-geral", "correct_letter": "A"}, {"question_id": "enem-2023-98-geral", "correct_letter": "B"}, {"question_id": "enem-2023-99-geral", "correct_letter": "D"}, {"question_id": "enem-2023-100-geral", "correct_letter": "C"}, {"question_id": "enem-2023-101-geral", "correct_letter": "A"}, {"question_id": "enem-2023-102-geral", "correct_letter": "C"}, {"question_id": "enem-2023-103-geral", "correct_letter": "D"}, {"question_id": "enem-2023-104-geral", "correct_letter": "B"}, {"question_id": "enem-2023-105-geral", "correct_letter": "E"}, {"question_id": "enem-2023-106-geral", "correct_letter": "C"}, {"question_id": "enem-2023-107-geral", "correct_letter": "D"}, {"question_id": "enem-2023-108-geral", "correct_letter": "D"}, {"question_id": "enem-2023-109-geral", "correct_letter": "D"}, {"question_id": "enem-2023-110-geral", "correct_letter": "B"}, {"question_id": "enem-2023-111-geral", "correct_letter": "C"}, {"question_id": "enem-2023-112-geral", "correct_letter": "A"}, {"question_id": "enem-2023-113-geral", "correct_letter": "A"}, {"question_id": "enem-2023-114-geral", "correct_letter": "A"}, {"question_id": "enem-2023-115-geral", "correct_letter": "B"}, {"question_id": "enem-2023-116-geral", "correct_letter": "B"}, {"question_id": "enem-2023-117-geral", "correct_letter": "A"}, {"question_id": "enem-2023-118-geral", "correct_letter": "C"}, {"question_id": "enem-2023-119-geral", "correct_letter": "C"}, {"question_id": "enem-2023-120-geral", "correct_letter": "C"}, {"question_id": "enem-2023-121-geral", "correct_letter": "A"}]') on conflict(question_id) do nothing;
commit;
begin;
insert into public.orbit_questions(id,year,number,discipline,language,context,prompt,alternatives,source_url) select id,year,number,discipline,language,context,prompt,alternatives,source_url from jsonb_populate_recordset(null::public.orbit_questions,'[{"id": "enem-2023-122-geral", "year": 2023, "number": 122, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "Em uma indústria alimentícia, para produção de doce de leite, utiliza-se um tacho de parede oca com uma entrada para vapor de água a 120 °C e uma saída para água líquida em equilíbrio com o vapor a 100 °C. Ao passar pela parte oca do tacho, o vapor de água transforma-se em líquido, liberando energia. A parede transfere essa energia para o interior do tacho, resultando na evaporação de água e consequente concentração do produto.\nNo processo de concentração do produto, é utilizada energia proveniente", "alternatives": [{"letter": "A", "text": "Somente do calor latente de vaporização.", "file": null}, {"letter": "B", "text": "Somente do calor latente de condensação.", "file": null}, {"letter": "C", "text": "Do calor sensível e do calor latente de vaporização.", "file": null}, {"letter": "D", "text": "Do calor sensível e do calor latente de condensação.", "file": null}, {"letter": "E", "text": "Do calor latente de condensação e do calor latente de vaporização.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/122"}, {"id": "enem-2023-123-geral", "year": 2023, "number": 123, "discipline": "ciencias-natureza", "language": null, "context": "Entre os medicamentos mais comuns consumidos para o alívio da dor está o ibuprofeno, um composto quiral com ação anti-inflamatória e efeito analgésico, que é comercializado como fármaco opticamente puro, ou seja, sem a mistura com outro isômero óptico. A fórmula estrutural plana do ibuprofeno é:\n\n![](https://enem.dev/2023/questions/123/045ed5ac-600f-4d71-bc55-63a2f2804c13.png)\n\nAlém do ibuprofeno, destacam-se também os princípios ativos a seguir, presentes em outros medicamentos para o alívio da dor:\n\n![](https://enem.dev/2023/questions/123/5b164bb7-d865-44cf-820a-1dc266d8effe.jpg)", "prompt": "O princípio ativo que apresenta o mesmo tipo de isomeria espacial que o ibuprofeno é o(a)", "alternatives": [{"letter": "A", "text": "Fenacetina.", "file": null}, {"letter": "B", "text": "Paracetamol.", "file": null}, {"letter": "C", "text": "Dipirona sódica.", "file": null}, {"letter": "D", "text": "Diclofenaco sódico.", "file": null}, {"letter": "E", "text": "Butilbrometo de escopolamina.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/123"}, {"id": "enem-2023-124-geral", "year": 2023, "number": 124, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "Uma concessionária é responsável por um trecho de 480 quilômetros de uma rodovia. Nesse trecho, foram construídas 10 praças de pedágio, onde funcionários recebem os pagamentos nas cabines de cobrança. Também existe o serviço automático, em que os veículos providos de um dispositivo passam por uma cancela, que se abre automaticamente, evitando filas e diminuindo o tempo de viagem. Segundo a concessionária, o tempo médio para efetuar a passagem em uma cabine é de 3 minutos, e as velocidades máximas permitidas na rodovia são 100 km/h, para veículos leves, e 80 km/h, para veículos de grande porte.\nConsidere um carro e um caminhão viajando, ambos com velocidades constantes e iguais às máximas permitidas, e que somente o caminhão tenha o serviço automático de cobrança. Comparado ao caminhão, quantos minutos a menos o carro leva para percorrer toda a rodovia?", "alternatives": [{"letter": "A", "text": "30", "file": null}, {"letter": "B", "text": "42", "file": null}, {"letter": "C", "text": "72", "file": null}, {"letter": "D", "text": "288", "file": null}, {"letter": "E", "text": "360", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/124"}, {"id": "enem-2023-125-geral", "year": 2023, "number": 125, "discipline": "ciencias-natureza", "language": null, "context": "**Pais com síndrome de Down**\n\nA síndrome de Down é uma alteração genética associada à trissomia do cromossomo 21, ou seja, o indivíduo possui três cromossomos 21 e não um par, como é normal. Isso ocorre pela união de um gameta contendo um cromossomo 21 com um gameta possuidor de dois cromossomos 21. Embora, normalmente, as mulheres com a síndrome sejam estéreis, em 2008, no interior de São Paulo, uma delas deu à luz uma menina sem a síndrome de Down\n\nMORENO, T. **Três anos após dar à luz, mãe portadora de síndrome de Down revela detalhes de seu dia a dia**. Disponível em: www.band.uol.com.br. Acesso em: 31 out. 2013 (adaptado).", "prompt": "Sabendo disso, um jovem casal, ambos com essa síndrome, procura um médico especialista para aconselhamento genético porque querem ter um bebê.\nO médico informa ao casal que, com relação ao cromossomo 21, os zigotos formados serão", "alternatives": [{"letter": "A", "text": "Todos normais.", "file": null}, {"letter": "B", "text": "Todos tetrassômicos.", "file": null}, {"letter": "C", "text": "Apenas normais ou tetrassômicos", "file": null}, {"letter": "D", "text": "Apenas trissômicos ou tetrassômicos", "file": null}, {"letter": "E", "text": "Normais, trissômicos ou tetrassômicos.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/125"}, {"id": "enem-2023-126-geral", "year": 2023, "number": 126, "discipline": "ciencias-natureza", "language": null, "context": "Para que uma molécula dê origem a um medicamento de administração oral, além de apresentar atividade farmacológica, deve ser capaz de atingir o local de ação. Para tanto, essa molécula não deve se degradar no estômago (onde o meio é fortemente ácido e há várias enzimas que reagem mediante catálise ácida), deve ser capaz de atravessar as membranas celulares e ser solúvel no plasma sanguíneo (sistema aquoso). Para os fármacos cujas estruturas são formadas por cadeias carbônicas longas contendo pelo menos um grupamento amino, um recurso tecnológico empregado é sua conversão no cloridrato correspondente. Essa conversão é representada, de forma genérica, pela equação química:\n\n![](https://enem.dev/2023/questions/126/b0c226d9-5944-4f6d-8b81-0fa0f9f7d511.png)", "prompt": "O aumento da eficiência de circulação do fármaco no sangue, promovido por essa conversão, deve-se ao incremento de seu(sua)", "alternatives": [{"letter": "A", "text": "Basicidade.", "file": null}, {"letter": "B", "text": "Lipofilicidade.", "file": null}, {"letter": "C", "text": "Caráter iônico.", "file": null}, {"letter": "D", "text": "Cadeia carbônica.", "file": null}, {"letter": "E", "text": "Estado de oxidação.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/126"}, {"id": "enem-2023-127-geral", "year": 2023, "number": 127, "discipline": "ciencias-natureza", "language": null, "context": "**Toxicidade do cianeto**\n\nA produção de ATP depende do gradiente de prótons gerado pela cadeia respiratória. Nessas reações, os elétrons  \nprovenientes da oxidação do NADH em NAD+ percorrem a cadeia até chegarem à citocromo c oxidase reduzindo o  \nFe3+ a Fe2+. O oxigênio atua como aceptor final desses elétrons formando água. O cianeto é uma espécie química  \naltamente tóxica que tem grande afinidade pelo Fe3+. Quando células são expostas ao cianeto, ele se liga ao sítio de  \nFe3+ da citocromo c oxidase, impedindo a sua conversão em Fe2+ e bloqueando a cadeia respiratória.\n\n![](https://enem.dev/2023/questions/127/97828514-9c7c-491c-9146-e4d8bf25778a.png)\n\nALBERTS, B. et al. **Biologia molecular da célula**. Porto Alegre: Artmed, 2010 (adaptado).", "prompt": "Esse bloqueio aumenta a concentração celular de", "alternatives": [{"letter": "A", "text": "ATP.", "file": null}, {"letter": "B", "text": "Água.", "file": null}, {"letter": "C", "text": "NADH.", "file": null}, {"letter": "D", "text": "Dióxido de carbono.", "file": null}, {"letter": "E", "text": "Citocromo c oxidase.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/127"}, {"id": "enem-2023-128-geral", "year": 2023, "number": 128, "discipline": "matematica", "language": null, "context": "É comum em viagens de avião sermos solicitados a desligar aparelhos cujo funcionamento envolva a emissão ou a recepção de ondas eletromagnéticas, como celulares. A justificativa dada para esse procedimento é, entre outras coisas, a necessidade de eliminar fontes de sinais eletromagnéticos que possam interferir nas comunicações, via rádio, dos pilotos com a torre de controle.", "prompt": "Essa interferência poderá ocorrer somente se as ondas emitidas pelo celular e as recebidas pelo rádio do avião", "alternatives": [{"letter": "A", "text": "Forem ambas audíveis.", "file": null}, {"letter": "B", "text": "Tiverem a mesma potência.", "file": null}, {"letter": "C", "text": "Tiverem a mesma frequência.", "file": null}, {"letter": "D", "text": "Tiverem a mesma intensidade.", "file": null}, {"letter": "E", "text": "Propagarem-se com velocidades diferentes.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/128"}, {"id": "enem-2023-129-geral", "year": 2023, "number": 129, "discipline": "matematica", "language": null, "context": "O Aldrin é um inseticida agrícola organoclorado sintético de baixa polaridade, cuja estrutura molecular simétrica, de fórmula ![](https://enem.dev/broken-image.svg), está representada na figura. Introduzido na agricultura a partir da década de 1950, esse composto apresenta alta persistência no meio ambiente e acumulação nos organismos, sendo danoso para a saúde.\n\n![](https://enem.dev/broken-image.svg)\n\nVIEGAS JÚNIOR, C. Terpenos com atividade inseticida: uma alternativa para o controle químico de insetos. **Química Nova**, v. 26, n. 3, 2003 (adaptado).\n\nUm pesquisador coletou fluidos biológicos de indivíduos de uma população contaminada por esse inseticida agrícola. Ele analisou amostras de saliva, sangue, lágrima, urina e leite quanto à presença dessa substância.", "prompt": "Em qual dos fluidos o pesquisador provavelmente encontrou a maior concentração dessa substância?", "alternatives": [{"letter": "A", "text": "Saliva, por consequência da atividade de enzimas.", "file": null}, {"letter": "B", "text": "Sangue, em função das hemácias e leucócitos.", "file": null}, {"letter": "C", "text": "Lágrima, em razão da concentração de sais.", "file": null}, {"letter": "D", "text": "Urina, pela presenca de moléculas de ureia.", "file": null}, {"letter": "E", "text": "Leite, por causa do alto teor de gorduras.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/129"}, {"id": "enem-2023-130-geral", "year": 2023, "number": 130, "discipline": "matematica", "language": null, "context": "Uma cafeteria adotou copos fabricados a partir de uma composição de 50% de plástico reciclado não biodegradável e 50% de casca de café. O copo é reutilizável e retornável, pois o material, semelhante a uma cerâmica, suporta a lavagem. Embora ele seja comercializado por um preço considerado alto quando comparado ao de um copo de plástico descartável, essa cafeteria possibilita aos clientes retornarem o copo sujo e levarem o café quente servido em outro copo já limpo e higienizado. O material desse copo oferece também o conforto de não esquentar na parte externa.\n\n**Cafeteria adota copo reutilizável feito com casca de café.** Disponível em: www.gazetadopovo.com.br. Acesso em: 5 dez. 2019 (adaptado).", "prompt": "Quais duas vantagens esse copo apresenta em comparação ao copo descartável?", "alternatives": [{"letter": "A", "text": "Ter a durabilidade de uma cerâmica e ser totalmente biodegradável.", "file": null}, {"letter": "B", "text": "Ser tão durável quanto uma cerâmica e ter alta condutividade térmica.", "file": null}, {"letter": "C", "text": "Ser um mau condutor térmico e aumentar o resíduo biodegradável na natureza.", "file": null}, {"letter": "D", "text": "Ter baixa condutividade térmica e reduzir o resíduo não biodegradável na natureza.", "file": null}, {"letter": "E", "text": "Ter alta condutividade térmica e possibilitar a degradação do material no meio ambiente.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/130"}, {"id": "enem-2023-131-geral", "year": 2023, "number": 131, "discipline": "matematica", "language": null, "context": "O consumo exagerado de refrigerantes é preocupante, pois contribui para o aumento de casos de obesidade e diabetes. Considere dois refrigerantes enlatados, um comum e um diet, e que ambos possuam a mesma quantidade de aditivos, exceto pela presença de açúcar. O refrigerante comum contém basicamente água carbonatada e grande quantidade de açúcar; já o refrigerante diet tem água carbonatada e adoçantes, cujas massas são muito pequenas.\n\nCAVAGIS, A. D. M.; PEREIRA, E. A.; OLIVEIRA, L. C. Um método simples para avaliar o teor de sacarose e CO2 em refrigerantes. **Química Nova na Escola**, n. 3, ago. 2014 (adaptado).", "prompt": "Entre as duas versões apresentadas, o refrigerante comum possui", "alternatives": [{"letter": "A", "text": "Maior densidade.", "file": null}, {"letter": "B", "text": "Menor viscosidade.", "file": null}, {"letter": "C", "text": "Maior volume de gás dissolvido.", "file": null}, {"letter": "D", "text": "Menor massa de solutos dissolvidos.", "file": null}, {"letter": "E", "text": "Maior temperatura de congelamento.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/131"}, {"id": "enem-2023-132-geral", "year": 2023, "number": 132, "discipline": "matematica", "language": null, "context": "O manual de um automóvel alerta sobre os cuidados em relação à pressão do ar no interior dos pneus. Recomenda-se que a pressão seja verificada com os pneus frios (à temperatura ambiente). Um motorista, desatento a essa informação, realizou uma viagem longa sobre o asfalto quente e, em seguida, verificou que a pressão![](https://enem.dev/2023/questions/132/99a53ed4-bbd2-4aa0-9301-ee4cd640a4b6.jpg) no interior dos pneus não era a recomendada pelo fabricante. Na ocasião, a temperatura dos pneus era ![](https://enem.dev/2023/questions/132/2367c9cb-2c1a-4b79-b582-86fc01088ff8.jpg). Após um longo período em repouso, os pneus do carro atingiram a temperatura ambiente T. Durante o resfriamento, não há alteração no volume dos pneus e na quantidade de ar no seu interior. Considere o ar dos pneus um gás perfeito (também denominado gás ideal).", "prompt": "Durante o processo de resfriamento, os valores de pressão em relação à temperatura (P x T) são representados pelo gráfico:", "alternatives": [{"letter": "A", "text": null, "file": null}, {"letter": "B", "text": null, "file": null}, {"letter": "C", "text": null, "file": null}, {"letter": "D", "text": null, "file": null}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/132/cba38af9-964d-43be-8f6a-3c1def3c9b39.jpg"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/132"}, {"id": "enem-2023-133-geral", "year": 2023, "number": 133, "discipline": "ciencias-natureza", "language": null, "context": "O descarte de detergentes comuns nos esgotos domésticos ocasiona a formação de uma camada de espuma que impede a entrada de oxigênio na água. Os microrganismos que vivem nessas águas não são capazes de quebrar moléculas ramificadas, ocorrendo assim um desequilíbrio ambiental nos rios. A fórmula a seguir representa a estrutura química de um tensoativo presente na composição de um detergente não biodegradável.\n\n![](https://enem.dev/2023/questions/133/51c8e3c3-3a3f-4aec-ac94-b1ee4037a55f.png)\n\n**Tensoativo não biodegradável**", "prompt": "Qual modificação química na estrutura desse tensoativo o tornaria um detergente biodegradável?", "alternatives": [{"letter": "A", "text": "Retirar a parte polar da molécula.", "file": null}, {"letter": "B", "text": "Eliminar as insaturações do anel aromático.", "file": null}, {"letter": "C", "text": "Trocar o grupo aniônico por um grupo neutro.", "file": null}, {"letter": "D", "text": "Alterar o grupo aniônico por um grupo catiônico.", "file": null}, {"letter": "E", "text": "Modificar a cadeia carbônica para cadeia normal.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/133"}, {"id": "enem-2023-134-geral", "year": 2023, "number": 134, "discipline": "ciencias-natureza", "language": null, "context": "**Avaliação de substâncias genotóxicas**\n\nO ensaio de micronúcleos é um teste de avaliação de genotoxicidade que associa a presença de micronúcleos (pequenos núcleos que aparecem próximo aos núcleos das células) com lesões genéticas. Os micronúcleos são fragmentos de DNA encapsulados, provenientes do fuso mitótico durante a divisão celular.\n\nDIAS, V. M. **Micronúcleos em células tumorais**: biologia e implicações  \npara a tumorigênese. Dissertação de Mestrado. USP, 2006 (adaptado).", "prompt": "Os micronúcleos se originam dos(as)", "alternatives": [{"letter": "A", "text": "Nucléolos.", "file": null}, {"letter": "B", "text": "Lisossomos.", "file": null}, {"letter": "C", "text": "Ribossomos", "file": null}, {"letter": "D", "text": "Mitocôndrias", "file": null}, {"letter": "E", "text": "Cromossomos", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/134"}, {"id": "enem-2023-135-geral", "year": 2023, "number": 135, "discipline": "ciencias-natureza", "language": null, "context": "O petróleo é uma matéria-prima muito valiosa e métodos geofísicos são úteis na sua prospecção. É possível identificar a composição de materiais estratificados medindo-se a velocidade de propagação do som (onda mecânica) através deles. Considere que uma camada de 450 m de um líquido se encontra presa no subsolo entre duas camadas rochosas, conforme o esquema. Um pulso acústico (que gera uma vibração mecânica) é emitido a partir da superfície do solo, onde são posteriormente recebidas duas vibrações refletidas (ecos). A primeira corresponde à reflexão do pulso na interface superior do líquido com a camada rochosa. A segunda vibração deve-se à reflexão do pulso na interface inferior. O tempo entre a emissão do pulso e a chegada do primeiro eco é de 0,5 s. O segundo eco chega 1,1 s após a emissão do pulso\n\n![](https://enem.dev/2023/questions/135/11f4c343-9f23-4f60-a61f-10d4dbc2eb6c.png)", "prompt": "A velocidade do som na camada líquida, em metro por segundo, é", "alternatives": [{"letter": "A", "text": "270.", "file": null}, {"letter": "B", "text": "540.", "file": null}, {"letter": "C", "text": "818.", "file": null}, {"letter": "D", "text": "1 500.", "file": null}, {"letter": "E", "text": "1 800.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/135"}, {"id": "enem-2023-136-geral", "year": 2023, "number": 136, "discipline": "matematica", "language": null, "context": "Um artista plástico esculpe uma escultura a partir de um bloco de madeira de lei, em etapas. Inicialmente, esculpe um cone reto com 36 cm de altura e diâmetro da base medindo 18 cm. Em seguida, remove desse cone um cone menor, cujo diâmetro da base mede 6 cm, obtendo, assim, um tronco de cone, conforme ilustrado na figura.\n\n![](https://enem.dev/2023/questions/136/565c2d5a-96a0-4468-9bb1-2710707a40fd.png)\n\nEm seguida, perfura esse tronco de cone, removendo um cilindro reto, de diâmetro 6 cm, cujo eixo de simetria é o mesmo do cone original. Dessa forma, ao final, a escultura tem a forma de um tronco de cone com uma perfuração cilíndrica de base a base.  \nO tipo de madeira utilizada para produzir essa escultura tem massa igual a 0,6 g por centímetro cúbico de volume. Utilize 3 como aproximação para π.", "prompt": "Qual é a massa, em grama, dessa escultura?", "alternatives": [{"letter": "A", "text": "1.198,8", "file": null}, {"letter": "B", "text": "1.296,0", "file": null}, {"letter": "C", "text": "1.360,8", "file": null}, {"letter": "D", "text": "4.665,6", "file": null}, {"letter": "E", "text": "4.860,0", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/136"}, {"id": "enem-2023-137-geral", "year": 2023, "number": 137, "discipline": "matematica", "language": null, "context": "Os 100 funcionários de uma empresa estão distribuídos em dois setores: Produção e Administração.\n\nOs funcionários de um mesmo setor recebem salários com valores iguais. O quadro apresenta a quantidade de funcionários por setor e seus respectivos salários.\n\n![](https://enem.dev/2023/questions/137/fc161c5c-10e9-46d8-a75d-09c59b21d5a4.png)", "prompt": "A média dos salários dos 100 funcionários dessa empresa, em real, é", "alternatives": [{"letter": "A", "text": "2.000,00.", "file": null}, {"letter": "B", "text": "2.500,00.", "file": null}, {"letter": "C", "text": "3.250,00.", "file": null}, {"letter": "D", "text": "4.500,00.", "file": null}, {"letter": "E", "text": "9.000,00.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/137"}, {"id": "enem-2023-138-geral", "year": 2023, "number": 138, "discipline": "matematica", "language": null, "context": "Visando atrair mais clientes, o gerente de uma loja anunciou uma promoção em que cada cliente que realizar uma compra pode ganhar um voucher para ser usado em sua próxima compra. Para ganhar seu voucher, o cliente precisa retirar, ao acaso, uma bolinha de dentro de cada uma das duas urnas A e B disponibilizadas pelo gerente, nas quais há apenas bolinhas pretas e brancas. Atualmente, a probabilidade de se escolher, ao acaso, uma bolinha preta na urna A é igual a 20% e a probabilidade de se escolher uma bolinha preta na urna B é 25%. Ganha o voucher o cliente que retirar duas bolinhas pretas, uma de cada urna.\n\nCom o passar dos dias, o gerente percebeu que, para a promoção ser viável aos negócios, era preciso alterar a probabilidade de acerto do cliente sem alterar a regra da promoção. Para isso, resolveu alterar a quantidade de bolinhas brancas na urna B de forma que a probabilidade de um cliente ganhar o voucher passasse a ser menor ou igual a 1%. Sabe-se que a urna B tem 4 bolinhas pretas e que, em ambas as urnas, todas as bolinhas têm a mesma probabilidade de serem retiradas.", "prompt": "Qual é o número mínimo de bolinhas brancas que o gerente deve adicionar à urna B?", "alternatives": [{"letter": "A", "text": "20", "file": null}, {"letter": "B", "text": "60", "file": null}, {"letter": "C", "text": "64", "file": null}, {"letter": "D", "text": "68", "file": null}, {"letter": "E", "text": "80", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/138"}, {"id": "enem-2023-139-geral", "year": 2023, "number": 139, "discipline": "matematica", "language": null, "context": "O gerente de uma fábrica pretende comparar a evolução das vendas de dois produtos similares (I e II). Para isso, passou a verificar o número de unidades vendidas de cada um desses produtos em cada mês. Os resultados dessa verificação, para os meses de abril a junho, são apresentados na tabela.\n\n![](https://enem.dev/2023/questions/139/abba5cb1-da9d-4899-bda7-97099ca51147.png)\n\nO gerente estava decidido a cessar a produção do produto II no mês seguinte àquele em que as vendas do produto I superassem as do produto II.  \nSuponha que a variação na quantidade de unidades vendidas dos produtos I e II se manteve, mês a mês, como no período representado na tabela.", "prompt": "Em qual mês o produto II parou de ser produzido?", "alternatives": [{"letter": "A", "text": "Junho.", "file": null}, {"letter": "B", "text": "Julho.", "file": null}, {"letter": "C", "text": "Agosto.", "file": null}, {"letter": "D", "text": "Setembro.", "file": null}, {"letter": "E", "text": "Outubro.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/139"}, {"id": "enem-2023-140-geral", "year": 2023, "number": 140, "discipline": "matematica", "language": null, "context": "Uma empresa de transporte faz regularmente um levantamento do número de viagens realizadas durante o dia por todos os 160 motoristas cadastrados em seu aplicativo. Em um certo dia, foi gerado um relatório, por meio de um gráfico de barras, no qual se relacionaram a quantidade de motoristas com a quantidade de viagens realizadas até aquele instante do dia.\n\n![](https://enem.dev/2023/questions/140/846c1155-c9f0-48ad-a862-f9bf883c3935.png)", "prompt": "Comparando os valores da média, da mediana e da moda da distribuição das quantidades de viagens realizadas pelos motoristas cadastrados nessa empresa, obtém-se", "alternatives": [{"letter": "A", "text": "Mediana = média < moda.", "file": null}, {"letter": "B", "text": "Mediana = moda < média.", "file": null}, {"letter": "C", "text": "Mediana < média < moda.", "file": null}, {"letter": "D", "text": "Moda < média < mediana.", "file": null}, {"letter": "E", "text": "Moda < mediana < média.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/140"}, {"id": "enem-2023-141-geral", "year": 2023, "number": 141, "discipline": "matematica", "language": null, "context": "", "prompt": "Qual a probabilidade de o vencedor do sorteio ser um estudante do terceiro ano?", "alternatives": [{"letter": "A", "text": null, "file": "https://enem.dev/2023/questions/141/e698edb1-adc0-416b-9370-c20a7e878259.jpg"}, {"letter": "B", "text": null, "file": "https://enem.dev/2023/questions/141/b5f5bdf5-2251-4326-9877-ce9c2d831600.jpg"}, {"letter": "C", "text": null, "file": "https://enem.dev/2023/questions/141/d241fadb-6516-4ca8-aa9b-e72fff314881.jpg"}, {"letter": "D", "text": null, "file": "https://enem.dev/2023/questions/141/1dcce683-4ef7-4862-b554-3e3c66de54c3.jpg"}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/141/7b4de18d-92ca-488f-8419-ec95d852a135.jpg"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/141"}, {"id": "enem-2023-142-geral", "year": 2023, "number": 142, "discipline": "matematica", "language": null, "context": "", "prompt": "Qual é a quantidade mínima de água, em litro, que cada morador, em média, deverá economizar por dia, de modo que o reservatório não fique sem água nos próximos 10 dias?", "alternatives": [{"letter": "A", "text": "50", "file": null}, {"letter": "B", "text": "60", "file": null}, {"letter": "C", "text": "80", "file": null}, {"letter": "D", "text": "140", "file": null}, {"letter": "E", "text": "150", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/142"}, {"id": "enem-2023-143-geral", "year": 2023, "number": 143, "discipline": "matematica", "language": null, "context": "Em janeiro do ano passado, a direção de uma fábrica abriu uma creche para os filhos de seus funcionários, com 10 salas, cada uma com capacidade para atender 10 crianças a cada ano. As vagas são sorteadas entre os filhos dos funcionários inscritos, enquanto os não contemplados pelo sorteio formam uma lista de espera. No ano passado, a lista de espera teve 400 nomes e, neste ano, esse número cresceu 10%. A direção da fábrica realizou uma pesquisa e constatou que a lista de espera para o próximo ano terá a mesma quantidade de nomes da lista de espera deste ano. Decidiu, então, construir, ao longo desse ano, novas salas para a creche, também com capacidade de atendimento para 10 crianças cada, de modo que o número de nomes na lista de espera no próximo ano seja 25% menor que o deste ano.", "prompt": "O número mínimo de salas que deverão ser construídas é", "alternatives": [{"letter": "A", "text": "10", "file": null}, {"letter": "B", "text": "11", "file": null}, {"letter": "C", "text": "12", "file": null}, {"letter": "D", "text": "30", "file": null}, {"letter": "E", "text": "33", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/143"}, {"id": "enem-2023-144-geral", "year": 2023, "number": 144, "discipline": "matematica", "language": null, "context": "A foto mostra a construção de uma cisterna destinada ao armazenamento de água. Uma cisterna como essa, na forma de cilindro circular reto com 3 m² de área da base, foi abastecida por um curso-d’água com vazão constante. O seu proprietário registrou a altura do nível da água no interior da cisterna durante o abastecimento em diferentes momentos de um mesmo dia, conforme o quadro.\n\n![](https://enem.dev/2023/questions/144/c606403f-fd10-4c02-8e46-736fece94b85.png)\n\n![](https://enem.dev/2023/questions/144/2107cabc-64d0-4a1f-9eab-fa7dce0e9ac2.png)\n\nDisponível em: www.paraibamix.com. Acesso em: 3 dez. 2012.", "prompt": "Qual foi a vazão, em metro cúbico por hora, do curso-d’água que abasteceu a cisterna?", "alternatives": [{"letter": "A", "text": "0,3", "file": null}, {"letter": "B", "text": "0,5", "file": null}, {"letter": "C", "text": "0,9", "file": null}, {"letter": "D", "text": "1,8", "file": null}, {"letter": "E", "text": "2,7", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/144"}, {"id": "enem-2023-145-geral", "year": 2023, "number": 145, "discipline": "matematica", "language": null, "context": "Num certo momento de um jogo digital, a tela apresenta a imagem representada na figura. O ponto Q1 representa a posição de um jogador que está com a bola, os pontos Q2, Q3, Q4 , Q5 e Q6  \ntambém indicam posições de jogadores da mesma equipe, e os pontos A e B indicam os dois pés da trave mais próxima deles. No momento da partida retratado, o jogador Q1 tem a posse da bola, que será passada para um dos outros jogadores das posições Qn, n ∈ {2, 3, 4, 5, 6}, cujo ângulo AQnB tenha a mesma medida do ângulo AQ1 B.\n\n![](https://enem.dev/2023/questions/145/f338280e-33fe-4896-b296-cfb94ca78430.png)", "prompt": "Qual é o jogador que receberá a bola?", "alternatives": [{"letter": "A", "text": null, "file": "https://enem.dev/2023/questions/145/b794885b-0519-4e72-87e0-93de02461252.png"}, {"letter": "B", "text": null, "file": "https://enem.dev/2023/questions/145/57b5461f-1924-4599-9914-4b148b722d7c.png"}, {"letter": "C", "text": null, "file": "https://enem.dev/2023/questions/145/d7e46a12-9912-4fad-8d9d-225859b42312.png"}, {"letter": "D", "text": null, "file": "https://enem.dev/2023/questions/145/7a03bf64-9ae1-4137-924d-e1c6110fd1a3.png"}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/145/5be53460-7a9a-4138-8d62-ac01b26993d6.png"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/145"}, {"id": "enem-2023-146-geral", "year": 2023, "number": 146, "discipline": "matematica", "language": null, "context": "![](https://enem.dev/2023/questions/146/74e0c851-b2af-410d-9f19-3348dd8f883a.jpg)", "prompt": "Considere que os números colocados nos vértices do triângulo estejam em progressão aritmética de razão igual a 2.\nNas condições propostas, quais as possíveis soluções para as somas dos números que formam os lados do triângulo?", "alternatives": [{"letter": "A", "text": "Há somente uma solução possível, e as somas em cada lado do triângulo são iguais a 7.", "file": null}, {"letter": "B", "text": "Há somente uma solução possível, e as somas em cada lado do triângulo são iguais a 9.", "file": null}, {"letter": "C", "text": "Há somente duas soluções possíveis, uma em que as somas em cada lado do triângulo são iguais a 7 e outra em que as somas são iguais a 9.", "file": null}, {"letter": "D", "text": "Há somente duas soluções possíveis, uma em que as somas em cada lado do triângulo são iguais a 9 e outra em que as somas são iguais a 12.", "file": null}, {"letter": "E", "text": "Há somente duas soluções possíveis, uma em que as somas em cada lado do triângulo são iguais a 10 e outra em que as somas são iguais a 11.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/146"}, {"id": "enem-2023-147-geral", "year": 2023, "number": 147, "discipline": "matematica", "language": null, "context": "", "prompt": "Alguns estudos comprovam que os carboidratos fornecem energia ao corpo, preservam as proteínas estruturais dos músculos durante a prática de atividade física e ainda dão força para o cérebro coordenar os movimentos, o que de fato tem impacto positivo no desenvolvimento do praticante. O ideal é consumir 1 grama de carboidrato para cada minuto de caminhada.\nCIRINO, C. Boa pergunta: consumir carboidratos antes dos exercícios melhora o desempenho do atleta? Revista Saúde! É Vital, n. 330, nov. 2010 (adaptado).\nUm casal realizará diariamente 30 minutos de caminhada, ingerindo, antes dessa atividade, a quantidade ideal de carboidratos recomendada. Para ter o consumo ideal apenas por meio do consumo de pão de fôrma integral, o casal planeja garantir o suprimento de pães para um período de 30 dias ininterruptos. Sabe-se que cada pacote desse pão vem com 18 fatias, e que cada uma delas tem 15 gramas de carboidratos.\nA quantidade mínima de pacotes de pão de fôrma necessários para prover o suprimento a esse casal é", "alternatives": [{"letter": "A", "text": "1", "file": null}, {"letter": "B", "text": "4", "file": null}, {"letter": "C", "text": "6", "file": null}, {"letter": "D", "text": "7", "file": null}, {"letter": "E", "text": "8", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/147"}, {"id": "enem-2023-148-geral", "year": 2023, "number": 148, "discipline": "ciencias-humanas", "language": null, "context": "O mastro de uma bandeira foi instalado perpendicularmente ao solo em uma região plana. Devido aos fortes ventos, três cabos de aço, de mesmo comprimento, serão instalados para dar sustentação ao mastro. Cada cabo de aço ficará perfeitamente esticado, com uma extremidade num ponto P do mastro, a uma altura h do solo, e a outra extremidade, num ponto no chão, como mostra a figura.\n\n![](https://enem.dev/2023/questions/148/c6c6b6c4-3fba-4a68-99c6-014bb190c456.png)", "prompt": "Os cabos de aço formam um ângulo a com o plano do chão. Por medida de segurança, há apenas três opções de instalação:\n• opção I: h = 11 m e a = 30°\n• opção II: h = 12 m e a = 45°\n• opção III: h = 18 m e a = 60°\nA opção a ser escolhida é aquela em que a medida dos cabos seja a menor possível.\nQual será a medida, em metro, de cada um dos cabos a serem instalados?", "alternatives": [{"letter": "A", "text": null, "file": "https://enem.dev/2023/questions/148/5caf269a-1856-41a0-8c13-b8ad7c53b935.png"}, {"letter": "B", "text": null, "file": "https://enem.dev/2023/questions/148/43a6cfb3-4059-4789-b8cc-5c60dc86d06c.png"}, {"letter": "C", "text": null, "file": "https://enem.dev/2023/questions/148/16d931ae-49d5-4a30-9acf-8c5ad6e8eabb.png"}, {"letter": "D", "text": null, "file": "https://enem.dev/2023/questions/148/5de1f078-227d-45d8-9c32-d593632fbd05.png"}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/148/a642bb31-dc04-4195-beb4-3a3dfbade22c.png"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/148"}, {"id": "enem-2023-149-geral", "year": 2023, "number": 149, "discipline": "ciencias-humanas", "language": null, "context": "Um controlador de voo dispõe de um instrumento que descreve a altitude de uma aeronave em voo, em função da distância em solo. Essa distância em solo é a medida na horizontal entre o ponto de origem do voo até o ponto que representa a projeção ortogonal da posição da aeronave, em voo, no solo. Essas duas grandezas são dadas numa mesma unidade de medida.\n\nA tela do instrumento representa proporcionalmente as dimensões reais das distâncias associadas ao voo. A figura apresenta a tela do instrumento depois de concluída a viagem de um avião, sendo a medida do lado de cada quadradinho da malha igual a 1 cm.\n\n![](https://enem.dev/2023/questions/149/a88a534d-3ee0-4b70-aba7-1b3e7c46b5f3.png)", "prompt": "Essa tela apresenta os dados de um voo cuja maior altitude alcançada foi de 5 km.\nA escala em que essa tela representa as medidas reais é", "alternatives": [{"letter": "A", "text": "1 : 5.", "file": null}, {"letter": "B", "text": "1 : 11.", "file": null}, {"letter": "C", "text": "1 : 55.", "file": null}, {"letter": "D", "text": "1 : 5000.", "file": null}, {"letter": "E", "text": "1 : 500 000.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/149"}, {"id": "enem-2023-150-geral", "year": 2023, "number": 150, "discipline": "matematica", "language": null, "context": "Dirigir após ingerir bebidas alcoólicas é uma atitude extremamente perigosa, uma vez que, a partir da primeira dose, a pessoa já começa a ter perda de sensibilidade de movimentos e de reflexos. Apesar de a eliminação e absorção do álcool depender de cada pessoa e de como o organismo consegue metabolizar a substância, ao final da primeira hora após a ingestão, a concentração de álcool (C) no sangue corresponde a aproximadamente 90% da quantidade (q) de álcool ingerida, e a eliminação total dessa concentração pode demorar até 12 horas.\n\nDisponível em: http://g1.globo.com. Acesso em: 1 dez. 2018 (adaptado).", "prompt": "Nessas condições, ao final da primeira hora após a ingestão da quantidade q de álcool, a concentração C dessa substância no sangue é expressa algebricamente por", "alternatives": [{"letter": "A", "text": "C = 0,9q", "file": null}, {"letter": "B", "text": "C = 0,1q", "file": null}, {"letter": "C", "text": "C = 1 − 0,1q", "file": null}, {"letter": "D", "text": "C = 1 − 0,9q", "file": null}, {"letter": "E", "text": "C = q − 10", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/150"}, {"id": "enem-2023-151-geral", "year": 2023, "number": 151, "discipline": "matematica", "language": null, "context": "Um investidor iniciante observou o gráfico que apresenta a evolução dos valores de duas criptomoedas A e B em relação ao tempo.\n\n![](https://enem.dev/2023/questions/151/276495a3-e5f2-4e4c-83b0-3473512a5274.png)\n\nDurante horas consecutivas, esses valores foram observados em nove instantes, representados por horas exatas.", "prompt": "Em quantos desses instantes a criptomoeda A estava mais valorizada do que a criptomoeda B?", "alternatives": [{"letter": "A", "text": "3", "file": null}, {"letter": "B", "text": "4", "file": null}, {"letter": "C", "text": "6", "file": null}, {"letter": "D", "text": "7", "file": null}, {"letter": "E", "text": "9", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/151"}]') on conflict(id) do nothing;
