insert into public.orbit_questions(id,year,number,discipline,language,context,prompt,alternatives,source_url) select id,year,number,discipline,language,context,prompt,alternatives,source_url from jsonb_populate_recordset(null::public.orbit_questions,'[{"id": "enem-2023-152-geral", "year": 2023, "number": 152, "discipline": "matematica", "language": null, "context": "A exposição a alguns níveis sonoros pode causar lesões auditivas. Por isso, em uma indústria, são adotadas medidas preventivas de acordo com a máquina que o funcionário opera e o nível _N_ de intensidade do som, medido em decibel (dB), a que o operário é exposto, sendo ![](https://enem.dev/2023/questions/152/30b0ee85-ac44-4eca-a7c9-54bd70f9c069.png), _I_ a intensidade do som e ![](https://enem.dev/2023/questions/152/40f43a4f-f8da-44a9-a02c-f20ba89a48ce.png).\n\nDisponível em: www.sofisica.com.br. Acesso em: 8 jul. 2015 (adaptado).\n\nQuando o som é considerado baixo, ou seja, _N_ = 48 dB ou menos, deve ser utilizada a medida preventiva I. No caso de o som ser moderado, quando _N_ está no intervalo (48 dB, 55 dB), deve ser utilizada a medida preventiva II. Quando o som é moderado alto, que equivale a _N_ no intervalo (55 dB, 80 dB), a medida preventiva a ser usada é a III. Se _N_ estiver no intervalo (80 dB, 115 dB), quando o som é considerado alto, deve ser utilizada a medida preventiva IV. E se o som é considerado muito alto, com _N_ maior que 115 dB, deve-se utilizar a medida preventiva V.  \nUma nova máquina, com ![](https://enem.dev/2023/questions/152/13f26008-1dcf-404f-b3cf-aae104a036c1.png), foi adquirida e será classificada de acordo com o nível de ruído que produz.  \nConsidere 0,3 como aproximação para ![](https://enem.dev/2023/questions/152/717fdd2f-5eef-48c9-9211-8f62bdb2639c.png).", "prompt": "O funcionário que operará a nova máquina deverá adotar a medida preventiva", "alternatives": [{"letter": "A", "text": "I.", "file": null}, {"letter": "B", "text": "II.", "file": null}, {"letter": "C", "text": "III.", "file": null}, {"letter": "D", "text": "IV.", "file": null}, {"letter": "E", "text": "V.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/152"}, {"id": "enem-2023-153-geral", "year": 2023, "number": 153, "discipline": "ciencias-humanas", "language": null, "context": "Um supermercado conta com cinco caixas disponíveis para pagamento. Foram instaladas telas que apresentam o tempo médio gasto por cada caixa para iniciar e finalizar o atendimento de cada cliente, e o número de pessoas presentes na fila de cada caixa em tempo real. Um cliente, na hora de passar sua compra, sabendo que cada um dos cinco caixas iniciará um novo atendimento naquele momento, pretende gastar o menor tempo possível de espera na fila. Ele observa que as telas apresentavam as informações a seguir.  \n• Caixa I: atendimento 12 minutos, 5 pessoas na fila.  \n• Caixa II: atendimento 6 minutos, 9 pessoas na fila.  \n• Caixa III: atendimento 5 minutos, 6 pessoas na fila.  \n• Caixa IV: atendimento 15 minutos, 2 pessoas na fila.  \n• Caixa V: atendimento 9 minutos, 3 pessoas na fila.", "prompt": "Para alcançar seu objetivo, o cliente deverá escolher o caixa", "alternatives": [{"letter": "A", "text": "I.", "file": null}, {"letter": "B", "text": "II.", "file": null}, {"letter": "C", "text": "III.", "file": null}, {"letter": "D", "text": "IV.", "file": null}, {"letter": "E", "text": "V.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/153"}, {"id": "enem-2023-154-geral", "year": 2023, "number": 154, "discipline": "ciencias-humanas", "language": null, "context": "As figuras pintadas no quadro da sala de estar de uma residência representam as silhuetas de parte das torres de um castelo e, ao fundo, a de uma lua cheia. A lua foi pintada na forma de um círculo, e o telhado da torre mais alta, na forma de triângulo equilátero, foi pintado sobrepondo parte da lua. O centro da lua coincide com um dos vértices do telhado da torre mais alta.\n\n![](https://enem.dev/2023/questions/154/d39268bf-82aa-4063-8bcf-dfdafa4a3aa8.png)", "prompt": "Nesse quadro, a parte da lua escondida atrás da torre mais alta do castelo pode ser representada por um", "alternatives": [{"letter": "A", "text": "Cone.", "file": null}, {"letter": "B", "text": "Setor circular.", "file": null}, {"letter": "C", "text": "Segmento circular.", "file": null}, {"letter": "D", "text": "Triângulo isósceles.", "file": null}, {"letter": "E", "text": "Arco de circunferência.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/154"}, {"id": "enem-2023-155-geral", "year": 2023, "number": 155, "discipline": "matematica", "language": null, "context": "Na planta baixa de um clube, a piscina é representada por um quadrado cuja área real mede 400 m². Ao redor dessa piscina, será construída uma calçada, de largura constante igual a 5 m.\n\n![](https://enem.dev/2023/questions/155/05746583-c107-4dd6-8a3b-7e7d0da99377.png)", "prompt": "Qual é a medida da área, em metro quadrado, ocupada pela calçada?", "alternatives": [{"letter": "A", "text": "1.000", "file": null}, {"letter": "B", "text": "900", "file": null}, {"letter": "C", "text": "600", "file": null}, {"letter": "D", "text": "500", "file": null}, {"letter": "E", "text": "400", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/155"}, {"id": "enem-2023-156-geral", "year": 2023, "number": 156, "discipline": "matematica", "language": null, "context": "Uma pessoa caminha por 30 minutos e utiliza um aplicativo instalado em seu celular para monitorar a variação da intensidade do sinal de internet recebido pelo aparelho durante o deslocamento. Chegando ao seu destino, o aplicativo forneceu este gráfico:\n\n![](https://enem.dev/2023/questions/156/e9e0b793-5535-48e6-87c6-5516e6d7c8cd.png)", "prompt": "Por quantos minutos, durante essa caminhada, o celular dessa pessoa ficou sem receber sinal de internet?", "alternatives": [{"letter": "A", "text": "6", "file": null}, {"letter": "B", "text": "8", "file": null}, {"letter": "C", "text": "10", "file": null}, {"letter": "D", "text": "14", "file": null}, {"letter": "E", "text": "24", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/156"}, {"id": "enem-2023-157-geral", "year": 2023, "number": 157, "discipline": "matematica", "language": null, "context": "Um professor, para promover a aprendizagem dos estudantes em estatística, propôs uma atividade. O objetivo era verificar o percentual de estudantes com massa corporal abaixo da média e altura acima da média de um grupo de estudantes. Para isso, usando uma balança e uma fita métrica, avaliou uma amostra de dez estudantes, anotando as medidas observadas. O gráfico apresenta a massa corporal, em quilograma, e a altura, em metro, obtidas na atividade\n\n![](https://enem.dev/2023/questions/157/13cfbc97-0034-4904-9100-ff5ca3f6504e.png)\n\nApós a coleta dos dados, os estudantes calcularam a média dos valores obtidos, referentes à massa corporal e à altura, obtendo, respectivamente, 80 kg e 1,65 m.", "prompt": "Qual é o percentual de estudantes dessa amostra com massa corporal abaixo da média e altura acima da média?", "alternatives": [{"letter": "A", "text": "10", "file": null}, {"letter": "B", "text": "20", "file": null}, {"letter": "C", "text": "30", "file": null}, {"letter": "D", "text": "50", "file": null}, {"letter": "E", "text": "70", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/157"}, {"id": "enem-2023-158-geral", "year": 2023, "number": 158, "discipline": "matematica", "language": null, "context": "Um pescador tem um custo fixo diário de R$ 900,00 com combustível, iscas, manutenção de seu barco e outras pequenas despesas. Ele vende cada quilograma de peixe por R$ 5,00. Sua meta é obter um lucro mínimo de R$ 800,00 por dia. Sozinho, ele consegue, ao final de um dia de trabalho, pescar 180 kg de peixe, o que é suficiente apenas para cobrir o custo fixo diário. Portanto, precisa contratar ajudantes, pagando para cada um R$ 250,00 por dia de trabalho. Além desse valor, 4%dareceita obtida pela venda de peixe é repartida igualmente entre os ajudantes. Considerando o tamanho de seu barco, ele pode contratar até 5 ajudantes. Ele sabe que com um ajudante a pesca diária é de 300 kg e que, a partir do segundo ajudante contratado, aumenta-se em 100 kg a quantidade de peixe pescada por ajudante em um dia de trabalho.", "prompt": "A quantidade mínima de ajudantes que esse pescador precisa contratar para conseguir o lucro diário pretendido é", "alternatives": [{"letter": "A", "text": "1", "file": null}, {"letter": "B", "text": "2", "file": null}, {"letter": "C", "text": "3", "file": null}, {"letter": "D", "text": "4", "file": null}, {"letter": "E", "text": "5", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/158"}, {"id": "enem-2023-159-geral", "year": 2023, "number": 159, "discipline": "matematica", "language": null, "context": "Um agricultor é informado sobre um método de proteção para sua lavoura que consiste em inserir larvas específicas, de rápida reprodução. A reprodução dessas larvas faz com que sua população multiplique-se por 10 a cada 3 dias e, para evitar eventuais desequilíbrios, é possível cessar essa reprodução aplicando-se um produto X. O agricultor decide iniciar esse método com 100 larvas e dispõe de 5 litros do produto X, cuja aplicação recomendada é de exatamente 1 litro para cada população de 200 000 larvas. A quantidade total do produto X de que ele dispõe deverá ser aplicada de uma única vez.", "prompt": "Quantos dias após iniciado esse método o agricultor deverá aplicar o produto X?", "alternatives": [{"letter": "A", "text": "2", "file": null}, {"letter": "B", "text": "4", "file": null}, {"letter": "C", "text": "6", "file": null}, {"letter": "D", "text": "12", "file": null}, {"letter": "E", "text": "18", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/159"}, {"id": "enem-2023-160-geral", "year": 2023, "number": 160, "discipline": "matematica", "language": null, "context": "Ao realizar o cadastro em um aplicativo de investimentos, foi solicitado ao usuário que criasse uma senha, sendo permitido o uso somente dos seguintes caracteres:\n\n• algarismos de 0 a 9;\n\n• 26 letras minúsculas do alfabeto;\n\n• 26 letras maiúsculas do alfabeto;\n\n• 6 caracteres especiais !, @, #, $, \\*, &.\n\nTrês tipos de estruturas para senha foram apresentadas ao usuário:\n\n• tipo I: formada por quaisquer quatro caracteres distintos, escolhidos dentre os permitidos;\n\n• tipo II: formada por cinco caracteres distintos, iniciando por três letras, seguidas por um algarismo e, ao final, um caractere especial;\n\n• tipo III: formada por seis caracteres distintos, iniciando por duas letras, seguidas por dois algarismos e, ao final, dois caracteres especiais.\n\nConsidere ![](https://enem.dev/2023/questions/160/a2d565c2-f39f-4b43-b261-087e349850fe.png) as probabilidades de se descobrirem ao acaso, na primeira tentativa, as senhas dos tipos I, II e III, respectivamente.", "prompt": "Nessas condições, o tipo de senha que apresenta a menor probabilidade de ser descoberta ao acaso, na primeira tentativa, é o", "alternatives": [{"letter": "A", "text": "Tipo I, pois p1 < p2 < p3.", "file": null}, {"letter": "B", "text": "Tipo I, pois tem menor quantidade de caracteres.", "file": null}, {"letter": "C", "text": "Tipo II, pois tem maior quantidade de letras.", "file": null}, {"letter": "D", "text": "Tipo III, pois p3 < p2 < p1", "file": null}, {"letter": "E", "text": "Tipo III, pois tem maior quantidade de caracteres.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/160"}, {"id": "enem-2023-161-geral", "year": 2023, "number": 161, "discipline": "matematica", "language": null, "context": "Uma loja vende seus produtos de duas formas: à vista ou financiado em três parcelas mensais iguais. Para definir o valor dessas parcelas nas vendas financiadas, a loja aumenta em 20% o valor do produto à vista e divide esse novo valor por 3. A primeira parcela deve ser paga no ato da compra, e as duas últimas, em 30 e 60 dias após a compra.\n\nUm cliente da loja decidiu comprar, de forma financiada, um produto cujo valor à vista é R$ 1 500,00.\n\nUtilize 5,29 como aproximação para 28.", "prompt": "A taxa mensal de juros compostos praticada nesse financiamento é de", "alternatives": [{"letter": "A", "text": "6,7%", "file": null}, {"letter": "B", "text": "10%", "file": null}, {"letter": "C", "text": "20%", "file": null}, {"letter": "D", "text": "21,5%", "file": null}, {"letter": "E", "text": "23,3%", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/161"}, {"id": "enem-2023-162-geral", "year": 2023, "number": 162, "discipline": "matematica", "language": null, "context": "Para concretar a laje de sua residência, uma pessoa contratou uma construtora. Tal empresa informa que o preço _y_ do concreto bombeado é composto de duas partes: uma fixa, chamada de taxa de bombeamento, e uma variável, que depende do volume _x_ de concreto utilizado. Sabe-se que a taxa de bombeamento custa R$ 500,00 e que o metro cúbico do concreto bombeado é de R$ 250,00.", "prompt": "A expressão que representa o preço y em função do volume x, em metro cúbico, é", "alternatives": [{"letter": "A", "text": "Y = 250x", "file": null}, {"letter": "B", "text": "Y = 500x", "file": null}, {"letter": "C", "text": "Y = 750x", "file": null}, {"letter": "D", "text": "Y = 250x + 500", "file": null}, {"letter": "E", "text": "Y = 500x + 250", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/162"}, {"id": "enem-2023-163-geral", "year": 2023, "number": 163, "discipline": "matematica", "language": null, "context": "Uma empresa de segurança domiciliar oferece o serviço de patrulha noturna, no qual vigilantes em motocicletas fazem o monitoramento periódico de residências. A empresa conta com uma base, de onde acompanha o trajeto realizado pelos vigilantes durante as patrulhas e orienta o deslocamento de equipes de reforço quando necessário. Numa patrulha rotineira, sem ocorrências, um vigilante conduziu sua motocicleta a uma velocidade constante durante todo o itinerário estabelecido, levando 30 minutos para conclusão. De acordo com os registros do GPS alocado na motocicleta, a distância da posição do vigilante à base, ao longo do tempo de realização do trajeto, é descrita pelo gráfico.\n\n![](https://enem.dev/2023/questions/163/ff0caefb-56e7-4c17-bae7-b65b91037e9c.png)", "prompt": "A vista superior da trajetória realizada pelo vigilante durante a patrulha registrada no gráfico é descrita pela representação", "alternatives": [{"letter": "A", "text": null, "file": "https://enem.dev/2023/questions/163/71c51165-c400-4d10-bb4b-c03ed19ff5ad.png"}, {"letter": "B", "text": null, "file": "https://enem.dev/2023/questions/163/e04c3016-712a-4e6b-a9e5-be3505a57d41.png"}, {"letter": "C", "text": null, "file": "https://enem.dev/2023/questions/163/1706f84a-c72a-48c1-982b-708ed91bcc8a.png"}, {"letter": "D", "text": null, "file": "https://enem.dev/2023/questions/163/d49e3db4-31ee-4123-9a19-599e0b473503.png"}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/163/7f6e3bbf-ef4c-4a6f-9fdb-407513158e78.png"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/163"}, {"id": "enem-2023-164-geral", "year": 2023, "number": 164, "discipline": "matematica", "language": null, "context": "O gráfico expõe alguns números da gripe A-H1N1. Entre as categorias que estão em processo de imunização, uma já está completamente imunizada, a dos trabalhadores da saúde.\n\n![](https://enem.dev/2023/questions/164/194cf28a-b40d-493d-b106-8f71aee57f51.png)\n\nÉpoca, 26 abr. 2010 (adaptado).", "prompt": "De acordo com o gráfico, entre as demais categorias, a que está mais exposta ao vírus da gripe A-H1N1 é a categoria de", "alternatives": [{"letter": "A", "text": "Indígenas.", "file": null}, {"letter": "B", "text": "Gestantes.", "file": null}, {"letter": "C", "text": "Doentes crônicos.", "file": null}, {"letter": "D", "text": "Adultos entre 20 e 29 anos.", "file": null}, {"letter": "E", "text": "Crianças de 6 meses a 2 anos.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/164"}, {"id": "enem-2023-165-geral", "year": 2023, "number": 165, "discipline": "matematica", "language": null, "context": "A figura representa uma escada com três degraus, construída em concreto maciço, com suas medidas especificadas.\n\n![](https://enem.dev/2023/questions/165/bf369224-eb93-4bba-98c4-ff7d1e17df36.png)\n\nNessa escada, pisos e espelhos têm formato retangular, e as paredes laterais têm formato de um polígono cujos lados adjacentes são perpendiculares. Pisos, espelhos e paredes laterais serão revestidos em cerâmica.", "prompt": "A área a ser revestida em cerâmica, em metro quadrado, mede", "alternatives": [{"letter": "A", "text": "1,20.", "file": null}, {"letter": "B", "text": "1,35.", "file": null}, {"letter": "C", "text": "1,65.", "file": null}, {"letter": "D", "text": "1,80.", "file": null}, {"letter": "E", "text": "1,95.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/165"}, {"id": "enem-2023-166-geral", "year": 2023, "number": 166, "discipline": "matematica", "language": null, "context": "Uma pessoa pratica quatro atividades físicas — caminhar, correr, andar de bicicleta e jogar futebol — como parte de seu programa de emagrecimento. Essas atividades são praticadas semanalmente de acordo com o quadro, que apresenta o número de horas diárias por atividade.\n\n![](https://enem.dev/2023/questions/166/80863c14-e426-4ae6-9ff0-03f5b3c71160.png)\n\nEla deseja comemorar seu aniversário e escolhe o dia da semana em que o gasto calórico com as atividades físicas  praticadas for o maior. Para tanto, considera que os valores dos gastos calóricos das atividades por hora (cal/h) são os seguintes:\n\n![](https://enem.dev/2023/questions/166/e3d70b62-2929-4694-ba58-cf45c0ac1374.png)", "prompt": "O dia da semana em que será comemorado o aniversário é", "alternatives": [{"letter": "A", "text": "Segunda-feira.", "file": null}, {"letter": "B", "text": "Terça-feira.", "file": null}, {"letter": "C", "text": "Quarta-feira.", "file": null}, {"letter": "D", "text": "Quinta-feira.", "file": null}, {"letter": "E", "text": "Sexta-feira.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/166"}, {"id": "enem-2023-167-geral", "year": 2023, "number": 167, "discipline": "matematica", "language": null, "context": "A cada bimestre, a diretora de uma escola compra uma quantidade de folhas de papel ofício proporcional ao número de alunos matriculados. No bimestre passado, ela comprou 6 000 folhas para serem utilizadas pelos 1 200 alunos matriculados. Neste bimestre, alguns alunos cancelaram suas matrículas e a escola tem, agora, 1 150 alunos. A diretora só pode gastar R$ 220,00 nessa compra, e sabe que o fornecedor da escola vende as folhas de papel ofício em embalagens de 100 unidades a R$ 4,00 a embalagem. Assim, será preciso convencer o fornecedor a dar um desconto à escola, de modo que seja possível comprar a quantidade total de papel ofício necessária para o bimestre.", "prompt": "O desconto necessário no preço final da compra, em porcentagem, pertence ao intervalo", "alternatives": [{"letter": "A", "text": "(5,0 ; 5,5).", "file": null}, {"letter": "B", "text": "(8,0 ; 8,5).", "file": null}, {"letter": "C", "text": "(11,5 ; 12,5).", "file": null}, {"letter": "D", "text": "(19,5 ; 20,5).", "file": null}, {"letter": "E", "text": "(3,5 ; 4,0).", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/167"}, {"id": "enem-2023-168-geral", "year": 2023, "number": 168, "discipline": "matematica", "language": null, "context": "Em um colégio público, a admissão no primeiro ano se dá por sorteio. Neste ano há 55 candidatos, cujas inscrições são numeradas de 01 a 55. O sorteio de cada número de inscrição será realizado em etapas, utilizando-se duas urnas. Da primeira urna será sorteada uma bola, dentre bolas numeradas de 0 a 9, que representará o algarismo das unidades do número de inscrição a ser sorteado e, em seguida, da segunda urna, será sorteada uma bola para representar o algarismo das dezenas desse número. Depois do primeiro sorteio, e antes de se sortear o algarismo das dezenas, as bolas que estarão presentes na segunda urna serão apenas aquelas cujos números formam, com o algarismo já sorteado, um número de 01 a 55.", "prompt": "As probabilidades de os candidatos de inscrição número 50 e 02 serem sorteados são, respectivamente,", "alternatives": [{"letter": "A", "text": null, "file": "https://enem.dev/2023/questions/168/a5689a77-7cbd-4f5f-b548-eef2a3fee87f.png"}, {"letter": "B", "text": null, "file": "https://enem.dev/2023/questions/168/67248715-8948-439d-9770-a652c76ac110.png"}, {"letter": "C", "text": null, "file": "https://enem.dev/2023/questions/168/4d9a67e0-9136-42e4-855e-c72b0b876d28.png"}, {"letter": "D", "text": null, "file": "https://enem.dev/2023/questions/168/24184847-9c76-40d3-9c78-44a35f0600e8.png"}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/168/adeb932f-030f-4190-9b20-33a4a5f968f5.png"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/168"}, {"id": "enem-2023-169-geral", "year": 2023, "number": 169, "discipline": "matematica", "language": null, "context": "O esquema mostra como a intensidade luminosa decresce com o aumento da profundidade em um rio, sendo ![](https://enem.dev/2023/questions/169/76239f15-d46d-4067-bb38-bb40ca2f87c0.png) a intensidade na sua superfície.\n\n![](https://enem.dev/2023/questions/169/3af229c8-e385-4ca2-891a-22bdf6b2d593.png)\n\nConsidere que a intensidade luminosa diminui, a cada metro acrescido na profundidade, segundo o mesmo padrão do esquema.", "prompt": "A intensidade luminosa correspondente à profundidade de 6 m é igual a", "alternatives": [{"letter": "A", "text": null, "file": "https://enem.dev/2023/questions/169/0ad62fa9-ccdd-40b7-95e6-024319a5c9bc.png"}, {"letter": "B", "text": null, "file": "https://enem.dev/2023/questions/169/74afb699-867b-4b47-8fa9-9c0fddd6db14.png"}, {"letter": "C", "text": null, "file": "https://enem.dev/2023/questions/169/23fe5ab4-dc1d-4693-8a62-c17abdd5c5cb.png"}, {"letter": "D", "text": null, "file": "https://enem.dev/2023/questions/169/9394f679-b291-4e10-9384-b1f2c2dba975.png"}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/169/5037e73b-aa7f-43fd-baa8-4f70d9f0f498.png"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/169"}, {"id": "enem-2023-170-geral", "year": 2023, "number": 170, "discipline": "matematica", "language": null, "context": "Analisando as vendas de uma empresa, o gerente concluiu que o montante diário arrecadado, em milhar de real, poderia ser calculado pela expressão ![](https://enem.dev/2023/questions/170/369b24e4-258e-4faf-b7df-0c2e3da3c22a.png) , em que os valores de x representam os dias do mês, variando de 1 a 30.\n\nUm dos fatores para avaliar o desempenho mensal da empresa é verificar qual é o menor montante diário ![](https://enem.dev/2023/questions/170/b158b079-eaf5-4f8c-84b1-99db8076a950.png) arrecadado ao longo do mês e classificar o desempenho conforme as categorias apresentadas a seguir, em que as quantidades estão expressas em milhar de real.\n\n![](https://enem.dev/2023/questions/170/e7404490-a2b4-46e1-b1e6-3a8c828050fe.png)", "prompt": "No caso analisado, qual seria a classificação do desempenho da empresa?", "alternatives": [{"letter": "A", "text": "Ótimo.", "file": null}, {"letter": "B", "text": "Bom.", "file": null}, {"letter": "C", "text": "Normal.", "file": null}, {"letter": "D", "text": "Ruim.", "file": null}, {"letter": "E", "text": "Péssimo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/170"}, {"id": "enem-2023-171-geral", "year": 2023, "number": 171, "discipline": "matematica", "language": null, "context": "O calendário maia apresenta duas contagens simultâneas de anos, o chamado ano Tzolkim, composto por 260 dias e que determinava o calendário religioso, e o ano Haab, composto por 365 dias e que determinava o calendário agrícola. Um historiador encontrou evidências de que gerações de uma mesma família governaram certa comunidade maia pelo período de 20 ciclos, sendo cada ciclo formado por 52 anos Haab.\n\nDisponível em: www.suapesquisa.com. Acesso em: 20 ago. 2014.", "prompt": "De acordo com as informações fornecidas, durante quantos anos Tzolkim aquela comunidade maia foi governada por tal família?", "alternatives": [{"letter": "A", "text": "741", "file": null}, {"letter": "B", "text": "1 040", "file": null}, {"letter": "C", "text": "1 460", "file": null}, {"letter": "D", "text": "2 100", "file": null}, {"letter": "E", "text": "5 200", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/171"}, {"id": "enem-2023-172-geral", "year": 2023, "number": 172, "discipline": "matematica", "language": null, "context": "Sejam _a_, _b_ e _c_ as medidas dos lados de um triângulo retângulo, tendo a como medida da hipotenusa. Esses valores _a_, _b_ e _c_ são, respectivamente, os diâmetros dos círculos _C1_ , _C2_ e _C3_, como apresentados na figura.\n\n![](https://enem.dev/2023/questions/172/dcdd2743-6ad6-44e8-94ae-d2adec3a3400.png)\n\nObserve que essa construção assegura, pelo teorema de Pitágoras, que área (C1) = área (C2) + área (C3).\n\nUm professor de matemática era conhecedor dessa construção e, confraternizando com dois amigos em uma pizzaria onde são vendidas pizzas somente em formato de círculo, lançou um desafio: mesmo sem usar um instrumento de medição, poderia afirmar com certeza se a área do círculo correspondente à pizza que ele pedisse era maior, igual ou menor do que a soma das áreas das pizzas dos dois amigos. Assim, foram pedidas três pizzas. O professor as dividiu ao meio e formou um triângulo com os diâmetros das pizzas, conforme indicado na figura.\n\n![](https://enem.dev/2023/questions/172/8bd02f79-d5fb-4b8d-9321-c57434be3374.png)\n\nA partir da medida do ângulo a, o professor afirmou que a área de sua pizza é maior do que a soma das áreas das outras duas pizzas.", "prompt": "A área da pizza do professor de matemática é maior do que a soma das áreas das outras duas pizzas, pois", "alternatives": [{"letter": "A", "text": "0° < a < 90°", "file": null}, {"letter": "B", "text": "A = 90°", "file": null}, {"letter": "C", "text": "90° < a < 180°", "file": null}, {"letter": "D", "text": "A = 180°", "file": null}, {"letter": "E", "text": "180° < a < 360°", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/172"}, {"id": "enem-2023-173-geral", "year": 2023, "number": 173, "discipline": "matematica", "language": null, "context": "Entre maratonistas, um parâmetro utilizado é o de economia de corrida (EC). O valor desse parâmetro é calculado pela razão entre o consumo de oxigênio, em mililitro (mL) por minuto (min), e a massa, em quilograma (kg), do atleta correndo a uma velocidade constante.\n\nDisponível em: www.treinamentoonline.com.br. Acesso em: 23 out. 2019 (adaptado).", "prompt": "Um maratonista, visando melhorar sua performance, auxiliado por um médico, mensura o seu consumo de oxigênio por minuto a velocidade constante. Com base nesse consumo e na massa do atleta, o médico calcula o EC do atleta.\nA unidade de medida da grandeza descrita pelo parâmetro EC é", "alternatives": [{"letter": "A", "text": null, "file": "https://enem.dev/2023/questions/173/58763f45-39e0-4355-b932-75233adbdf21.png"}, {"letter": "B", "text": null, "file": "https://enem.dev/2023/questions/173/81adc538-3ad2-4ced-9a2f-9a7f5f247c20.png"}, {"letter": "C", "text": null, "file": "https://enem.dev/2023/questions/173/5d5d774d-009d-44a6-a774-55719c5547bf.png"}, {"letter": "D", "text": null, "file": "https://enem.dev/2023/questions/173/3464da35-f15a-4506-b75a-168a26ff4664.png"}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/173/146d0f23-94de-4fd7-ae01-2d31285103d3.png"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/173"}, {"id": "enem-2023-175-geral", "year": 2023, "number": 175, "discipline": "matematica", "language": null, "context": "O metrô de um município oferece dois tipos de tíquetes com colorações diferentes, azul e vermelha, sendo vendidos em cartelas, cada qual com nove tíquetes da mesma cor e mesmo valor unitário. Duas cartelas de tíquetes azuis e uma cartela de tíquetes vermelhos são vendidas por R$ 32,40. Sabe-se que o preço de um tíquete azul menos o preço de um tíquete vermelho é igual ao preço de um tíquete vermelho mais cinco centavos.", "prompt": "Qual o preço, em real, de uma cartela de tíquetes vermelhos?", "alternatives": [{"letter": "A", "text": "4,68", "file": null}, {"letter": "B", "text": "6,30", "file": null}, {"letter": "C", "text": "9,30", "file": null}, {"letter": "D", "text": "10,50", "file": null}, {"letter": "E", "text": "10,65", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/175"}, {"id": "enem-2023-176-geral", "year": 2023, "number": 176, "discipline": "matematica", "language": null, "context": "Os números figurados pentagonais provavelmente foram introduzidos pelos pitagóricos por volta do século V a.C. As figuras ilustram como obter os seis primeiros deles, sendo os demais obtidos seguindo o mesmo padrão geométrico.\n\n![](https://enem.dev/2023/questions/176/d21e916b-a5fc-441e-b782-d2d4aca3522b.png)", "prompt": "O oitavo número pentagonal é", "alternatives": [{"letter": "A", "text": "59", "file": null}, {"letter": "B", "text": "83", "file": null}, {"letter": "C", "text": "86", "file": null}, {"letter": "D", "text": "89", "file": null}, {"letter": "E", "text": "92", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/176"}, {"id": "enem-2023-177-geral", "year": 2023, "number": 177, "discipline": "matematica", "language": null, "context": "A figura ilustra uma roda-gigante no exato instante em que a cadeira onde se encontra a pessoa P está no ponto mais alto dessa roda-gigante.\n\n![](https://enem.dev/2023/questions/177/27c49bd5-ad8c-450c-9f56-970b9ca9c53c.png)\n\nCom o passar do tempo, à medida que a roda-gigante gira, com velocidade angular constante e no sentido horário, a altura da cadeira onde se encontra a pessoa P, em relação ao solo, vai se alterando.", "prompt": "O gráfico que melhor representa a variação dessa altura, em função do tempo, contado a partir do instante em que a cadeira da pessoa P se encontra na posição mais alta da roda-gigante, é", "alternatives": [{"letter": "A", "text": null, "file": "https://enem.dev/2023/questions/177/3837d9d0-2ff6-49d7-affa-9bb60aacb00a.png"}, {"letter": "B", "text": null, "file": "https://enem.dev/2023/questions/177/262c33a1-0c7b-494c-9bd4-92d308154b59.png"}, {"letter": "C", "text": null, "file": "https://enem.dev/2023/questions/177/b9b5c23e-3ae9-4f92-9500-a1bda3ed5638.png"}, {"letter": "D", "text": null, "file": "https://enem.dev/2023/questions/177/03cd2618-be50-4803-b159-da8033fdeb8d.png"}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/177/0624eace-e934-40dc-895c-a505c0c9f183.png"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/177"}, {"id": "enem-2023-178-geral", "year": 2023, "number": 178, "discipline": "matematica", "language": null, "context": "Estudantes trabalhando com robótica criaram uma “torneira inteligente” que automatiza sua abertura e seu fechamento durante a limpeza das mãos. A tecnologia funciona da seguinte forma: ao se colocarem as mãos sob a torneira, ela libera água durante 3 segundos para que a pessoa possa molhá-las. Em seguida, interrompe o fornecimento de água por 5 segundos, enquanto a pessoa ensaboa suas mãos, e finaliza o ciclo liberando água para o enxágue por mais 3 segundos. Considere o tempo (_t_), em segundo, contado a partir do instante em que se inicia o ciclo. A vazão de água nessa torneira é constante.", "prompt": "Um esboço de gráfico que descreve o volume de água acumulado, em litro, liberado por essa torneira durante um ciclo de lavagem das mãos, em função do tempo (t), em segundo, é", "alternatives": [{"letter": "A", "text": null, "file": "https://enem.dev/2023/questions/178/ad5cc202-0c4f-44fb-aa1a-ec86c2f86da4.png"}, {"letter": "B", "text": null, "file": "https://enem.dev/2023/questions/178/c3b0946f-0e59-4928-858d-3f0a8887fb80.png"}, {"letter": "C", "text": null, "file": "https://enem.dev/2023/questions/178/f9e8ae9f-c9d6-4b83-9376-55b5ecba8a38.png"}, {"letter": "D", "text": null, "file": "https://enem.dev/2023/questions/178/46326c50-0f0b-42cf-a1d5-65299d39a4fd.png"}, {"letter": "E", "text": null, "file": "https://enem.dev/2023/questions/178/7ebc0f53-95db-497b-bc23-30cf64649c3a.png"}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/178"}, {"id": "enem-2023-179-geral", "year": 2023, "number": 179, "discipline": "matematica", "language": null, "context": "As características culturais variam de povo para povo. Há notícias de um povo que possuía formas de contar diferentes das nossas, como indicado no quadrinho a seguir.\n\n![](https://enem.dev/2023/questions/179/d2b83dd3-33ef-40d6-944a-b98d17f6411b.png)", "prompt": "Segundo o padrão de contagem indicado na figura, as representações dos numerais cinco e sete, nessa cultura, devem ser, respectivamente,", "alternatives": [{"letter": "A", "text": "Okosa urapum urapum urapum e okosa okosa urapum urapum urapum.", "file": null}, {"letter": "B", "text": "Okosa okosa urapum e okosa okosa okosa okosa urapum.", "file": null}, {"letter": "C", "text": "Okosa okosa urapum e okosa okosa okosa urapum.", "file": null}, {"letter": "D", "text": "Okosa urapum urapum e okosa urapum okosa urapum urapum.", "file": null}, {"letter": "E", "text": "Okosa okosa urapum e okosa okosa okosa okosa.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/179"}, {"id": "enem-2023-180-geral", "year": 2023, "number": 180, "discipline": "matematica", "language": null, "context": "Um tipo de semente necessita de bastante água nos dois primeiros meses após o plantio. Um produtor pretende estabelecer o melhor momento para o plantio desse tipo de semente, nos meses de outubro a março. Após consultar a previsão do índice mensal de precipitação de chuva (ImPC) da região onde ocorrerá o plantio, para o período chuvoso de 2020-2021, ele obteve os seguintes dados:  \n• outubro/2020: ImPC = 250 mm;  \n• novembro/2020: ImPC = 150 mm;  \n• dezembro/2020: ImPC = 200 mm;  \n• janeiro/2021: ImPC = 450 mm;  \n• fevereiro/2021: ImPC = 100 mm;  \n• março/2021: ImPC = 200 mm.\n\nCom base nessas previsões, ele precisa escolher dois meses consecutivos em que a média mensal de precipitação seja a maior possível.", "prompt": "No início de qual desses meses o produtor deverá plantar esse tipo de semente?", "alternatives": [{"letter": "A", "text": "Outubro.", "file": null}, {"letter": "B", "text": "Novembro.", "file": null}, {"letter": "C", "text": "Dezembro.", "file": null}, {"letter": "D", "text": "Janeiro.", "file": null}, {"letter": "E", "text": "Fevereiro.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/180"}]') on conflict(id) do nothing;
insert into orbit_private.answer_keys select * from jsonb_populate_recordset(null::orbit_private.answer_keys,'[{"question_id": "enem-2023-152-geral", "correct_letter": "B"}, {"question_id": "enem-2023-153-geral", "correct_letter": "E"}, {"question_id": "enem-2023-154-geral", "correct_letter": "B"}, {"question_id": "enem-2023-155-geral", "correct_letter": "D"}, {"question_id": "enem-2023-156-geral", "correct_letter": "A"}, {"question_id": "enem-2023-157-geral", "correct_letter": "B"}, {"question_id": "enem-2023-158-geral", "correct_letter": "D"}, {"question_id": "enem-2023-159-geral", "correct_letter": "D"}, {"question_id": "enem-2023-160-geral", "correct_letter": "A"}, {"question_id": "enem-2023-161-geral", "correct_letter": "D"}, {"question_id": "enem-2023-162-geral", "correct_letter": "D"}, {"question_id": "enem-2023-163-geral", "correct_letter": "A"}, {"question_id": "enem-2023-164-geral", "correct_letter": "D"}, {"question_id": "enem-2023-165-geral", "correct_letter": "E"}, {"question_id": "enem-2023-166-geral", "correct_letter": "C"}, {"question_id": "enem-2023-167-geral", "correct_letter": "A"}, {"question_id": "enem-2023-168-geral", "correct_letter": "A"}, {"question_id": "enem-2023-169-geral", "correct_letter": "D"}, {"question_id": "enem-2023-170-geral", "correct_letter": "D"}, {"question_id": "enem-2023-171-geral", "correct_letter": "C"}, {"question_id": "enem-2023-172-geral", "correct_letter": "C"}, {"question_id": "enem-2023-173-geral", "correct_letter": "B"}, {"question_id": "enem-2023-175-geral", "correct_letter": "B"}, {"question_id": "enem-2023-176-geral", "correct_letter": "E"}, {"question_id": "enem-2023-177-geral", "correct_letter": "A"}, {"question_id": "enem-2023-178-geral", "correct_letter": "B"}, {"question_id": "enem-2023-179-geral", "correct_letter": "C"}, {"question_id": "enem-2023-180-geral", "correct_letter": "C"}]') on conflict(question_id) do nothing;
commit;-- The upstream API has inconsistent discipline labels; use the exam's question ranges.
update public.orbit_questions set discipline=case when number<=45 then 'linguagens' when number<=90 then 'ciencias-humanas' when number<=135 then 'ciencias-natureza' else 'matematica' end where year=2023;
